import ValidationUtilities from "../../../../../../../../utilities/validationUtilities";
import ValueUtilities from "../../../../../../../../utilities/valueUtilities";

import { getHasToBeStringMessage } from "./../../../../../../../messages";
import { getHasToBePositiveNumberMessage } from "./../../../../../../../messages";
import { getFailedToMessage } from "./../../../../../../../messages";

const getFailedToSendGroupContentToFtpMessage = function(contentId, contentTitle, groupId, groupName) {

    const contentIdHasToBeStringMessage = getHasToBeStringMessage("Content id");
    ValidationUtilities.isString(contentId, contentIdHasToBeStringMessage);

    const contentTitleHasToBeStringMessage = getHasToBeStringMessage("Content title");
    ValidationUtilities.isString(contentTitle, contentTitleHasToBeStringMessage);

    const groupIdHasToBePositiveNumberMessage = getHasToBePositiveNumberMessage("Group id");
    ValidationUtilities.isPositiveNumber(groupId, groupIdHasToBePositiveNumberMessage);

    let sendGroupContentToFtpMessage = "" +
        "send content " + contentId + " (" + contentTitle + ") to FTP " +
        "for group " + groupId;

    const hasGroupName = !ValueUtilities.isNullOrUndefined(groupName);

    if (hasGroupName) {

        const groupNameHasToBeStringMessage = getHasToBeStringMessage("Group name");
        ValidationUtilities.isString(groupName, groupNameHasToBeStringMessage);

        sendGroupContentToFtpMessage += " (" + groupName + ")";

    }

    return getFailedToMessage(sendGroupContentToFtpMessage);

};

Object.freeze(getFailedToSendGroupContentToFtpMessage);

export default getFailedToSendGroupContentToFtpMessage;
