import ValueUtilities from "../utilities/valueUtilities";

const OsdRotatingFilter = function() {

    return function(input) {

        if (ValueUtilities.isNullOrUndefined(input)) {

            return null;

        }

        const inputUpperCase = input.toUpperCase();

        switch (inputUpperCase) {

            case "ON":

                return "Portrait";

            case "OFF":

                return "Landscape";

            default:

                return null;

        }

    };

};

export default OsdRotatingFilter;
