import ValueUtilities from "../utilities/valueUtilities";
import ValidationUtilities from "../utilities/validationUtilities";

import ErrorServiceMessages from "../messages/services/error/errorService";

class ErrorService {

    constructor(LedColor, LedStatus) {

        this._LedColor = LedColor;
        this._LedStatus = LedStatus;

    }

    static get _errorServiceMessages() {

        return ErrorServiceMessages;

    }

    handleLedError(led, alert) {

        const handleLedErrorMessages = ErrorService._errorServiceMessages.HandleLedError;

        // Validate led \\

        ValidationUtilities.isNotNullOrUndefined(led, handleLedErrorMessages.LED_CAN_NOT_BE_NULL_OR_UNDEFINED);

        // Handle led \\

        led.color = this._LedColor.RED;
        led.status = this._LedStatus.BLINKING;

        // Handle alert \\

        const hasAlert = !ValueUtilities.isNullOrUndefined(alert);
        ValidationUtilities.isBoolean(hasAlert, handleLedErrorMessages.HAS_ALERT_HAS_TO_BE_A_BOOLEAN);

        if (hasAlert) {

            const popover = led.popover;

            // Validate popover \\

            ValidationUtilities.isNotNullOrUndefined(

                popover, handleLedErrorMessages.POPOVER_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            // Add alert \\

            popover.addAlert(alert);

        }

    }

}

export default ErrorService;
