import ValueUtilities from "./valueUtilities";
import ValidationUtilities from "./validationUtilities";

import ArrayUtilitiesMessages from "../messages/utilities/array/arrayUtilities";

const ArrayUtilities = function() {

    const equals = function(array1, array2) {

        if (array1.length !== array2.length) {

            return false;

        }

        for (var i = 0; i < array1.length; i++) {

            if (array1[i] !== array2[i]) {

                return false;

            }

        }

        return true;

    };

    const unique = function(array, compareFunction) {

        const uniqueMessages = ArrayUtilitiesMessages.Unique;
        ValidationUtilities.isNotNullOrUndefined(array, uniqueMessages.ARRAY_CAN_NOT_BE_NULL_OR_UNDEFINED);

        if (ValueUtilities.isNullOrUndefined(compareFunction)) {

            compareFunction = function(element1, element2) {

                return element1 === element2;

            };

        }

        const uniqueArray = [];

        const addIfUnique = function(newElement) {

            const matchesNewElement = function(addedElement) {

                return compareFunction(addedElement, newElement);

            };

            if (!uniqueArray.some(matchesNewElement)) {

                uniqueArray.push(newElement);

            }

        };

        array.forEach(addIfUnique);

        return uniqueArray;

    };

    const isEmpty = function(array) {

        const isEmptyMessages = ArrayUtilitiesMessages.IsEmpty;
        ValidationUtilities.isNotNullOrUndefined(array, isEmptyMessages.ARRAY_CAN_NOT_BE_NULL_OR_UNDEFINED);

        return array.length === 0;

    };

    return {

        equals: equals,
        unique: unique,
        isEmpty: isEmpty

    };

}();

export default ArrayUtilities;
