import ValidationUtilities from "../../../../../../utilities/validationUtilities";
import ValueUtilities from "../../../../../../utilities/valueUtilities";

import { getHasToBeStringMessage } from "../../../../../messages";
import { getCanNotBeEmptyMessage } from "../../../../../messages";
import { getHasToBePositiveNumberMessage } from "../../../../../messages";
import { getFailedToMessage } from "../../../../../messages";

const getFailedToSaveDeviceSettingMessage = function(settingName, deviceId, deviceName) {

    const settingNameHasToBeStringMessage = getHasToBeStringMessage("Setting name");
    ValidationUtilities.isString(settingName, settingNameHasToBeStringMessage);

    const settingNameCanNotBeEmptyMessage = getCanNotBeEmptyMessage("Setting name");
    ValidationUtilities.isTrue(settingName.length > 0, settingNameCanNotBeEmptyMessage);

    const deviceIdHasToBePositiveNumberMessage = getHasToBePositiveNumberMessage("Device id");
    ValidationUtilities.isPositiveNumber(deviceId, deviceIdHasToBePositiveNumberMessage);

    let saveSettingMessage = "save " + settingName + " for device " + deviceId;
    const hasDeviceName = !ValueUtilities.isNullOrUndefined(deviceName);

    if (hasDeviceName) {

        const deviceNameHasToBeStringMessage = getHasToBeStringMessage("Device name");
        ValidationUtilities.isString(deviceName, deviceNameHasToBeStringMessage);

        saveSettingMessage += " (" + deviceName + ")";

    }

    return getFailedToMessage(saveSettingMessage);

};

Object.freeze(getFailedToSaveDeviceSettingMessage);

export default getFailedToSaveDeviceSettingMessage;
