import ValueUtilities from "../utilities/valueUtilities";
import ValidationUtilities from "../utilities/validationUtilities";

import DevicesControllerMessages from "../messages/controllers/devices/devicesController";

const DevicesController = function(

    ErrorService, SuccessService, AlertService, LedService, PopoverService, DevicePropertyService,
    DeviceSettingsService, DeviceService, Devices, DeviceActions, DevicesData,
    $scope, $window, $parse, $interval, $timeout

) {

    // Background task

    let backgroundTaskRunning = false;

    // Other

    const saveSetting = function(device, propertyPath, oldValue) {

        const saveSettingMessages = DevicesControllerMessages.SaveSetting;

        ValidationUtilities.isNotEmpty(device, saveSettingMessages.DEVICE_CAN_NOT_BE_EMPTY);

        ValidationUtilities.isString(propertyPath, saveSettingMessages.PROPERTY_PATH_HAS_TO_BE_A_STRING);
        ValidationUtilities.isTrue(propertyPath.length > 0, saveSettingMessages.PROPERTY_PATH_CAN_NOT_BE_EMPTY);

        // TODO: make oldValue required & add validation checks

        const splitPropertyPath = propertyPath.split(".");
        const propertyName = splitPropertyPath[0];

        ValidationUtilities.isNotNullOrUndefined(

            propertyName, saveSettingMessages.PROPERTY_NAME_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        const deviceId = device.id;

        ValidationUtilities.isPositiveNumber(

            deviceId, saveSettingMessages.DEVICE_ID_HAS_TO_BE_A_POSITIVE_NUMBER

        );

        const led = $scope.getDeviceLed(deviceId);

        ValidationUtilities.isNotNullOrUndefined(

            led, saveSettingMessages.LED_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        ValidationUtilities.isNotEmpty(led, saveSettingMessages.LED_CAN_NOT_BE_EMPTY);

        const successHandler = function() {

            SuccessService.handleLedSuccess(led);

        };

        const failHandler = function() {

            const failHandlerMessages = saveSettingMessages.FailHandler;

            const getPropertyPathValueCaller = $parse(propertyPath);
            const setPropertyPathValueCaller = getPropertyPathValueCaller.assign;
            setPropertyPathValueCaller(device, oldValue);

            const settingName = DeviceSettingsService.getSettingName(propertyName);
            ValidationUtilities.isString(settingName, failHandlerMessages.SETTING_NAME_HAS_TO_BE_A_STRING);
            ValidationUtilities.isTrue(settingName.length > 0, failHandlerMessages.SETTING_NAME_CAN_NOT_BE_EMPTY);

            const message = failHandlerMessages.getFailedToSaveSettingMessage(settingName);
            const alert = AlertService.getDangerAlertWithAlertGlyphicon(message);

            ValidationUtilities.isNotNullOrUndefined(

                alert, failHandlerMessages.ALERT_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            ValidationUtilities.isNotEmpty(

                alert, failHandlerMessages.ALERT_CAN_NOT_BE_EMPTY

            );

            ErrorService.handleLedError(led, alert);

        };

        DevicePropertyService.saveProperty(device, propertyPath, successHandler, failHandler);

    };

    // Button functions
    const detectDevices = function() {

        $scope.showModal("detectDevicesModal");

    };

    const addDeviceModal = function() {

        $scope.showModal("addDeviceModal");

    };

    const createGroupModal = function() {

        const createGroupModalMessages = DevicesControllerMessages.CreateGroupModal;

        const checkedDevices = $scope.getCheckedDevices();
        ValidationUtilities.isNotEmpty(checkedDevices, createGroupModalMessages.CHECKED_DEVICES_CAN_NOT_BE_EMPTY);

        const isEnoughCheckedDevices = enoughCheckedDevices();
        ValidationUtilities.isTrue(isEnoughCheckedDevices, createGroupModalMessages.NOT_ENOUGH_CHECKED_DEVICES);

        const group = {

            type: "group",
            name: "",
            devices: checkedDevices

        };

        $scope.setCurrentGroup(group);
        $scope.showModal("createGroupModal");

    };

    const assignContentModal = function() {

        $scope.showModal("assignContentModal");

    };

    const settingsModal = function() {

        $scope.showModal("settingsModal");

    };

    // Device buttons
    const deviceInfo = function(device) {

        const deviceInfoMessages = DevicesControllerMessages.DeviceInfo;

        ValidationUtilities.isNotNullOrUndefined(device, deviceInfoMessages.DEVICE_CAN_NOT_BE_NULL_OR_UNDEFINED);
        ValidationUtilities.isNotEmpty(device, deviceInfoMessages.DEVICE_CAN_NOT_BE_EMPTY);

        $scope.setCurrentDevice(device);
        $scope.showModal("deviceInfoModal");

        const deviceId = device.id;

        ValidationUtilities.isPositiveNumber(

            deviceId, deviceInfoMessages.DEVICE_ID_HAS_TO_BE_A_POSITIVE_NUMBER

        );

        const led = $scope.getDeviceLed(deviceId);
        ValidationUtilities.isNotNullOrUndefined(led, deviceInfoMessages.LED_CAN_NOT_BE_NULL_OR_UNDEFINED);

        SuccessService.handleLedSuccess(led);

    };

    const deviceSettings = function(device) {

        const deviceSettingsMessages = DevicesControllerMessages.DeviceSettings;

        ValidationUtilities.isNotNullOrUndefined(

            device, deviceSettingsMessages.DEVICE_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        ValidationUtilities.isNotEmpty(device, deviceSettingsMessages.DEVICE_CAN_NOT_BE_EMPTY);

        const deviceId = device.id;

        ValidationUtilities.isPositiveNumber(

            deviceId, deviceSettingsMessages.DEVICE_ID_HAS_TO_BE_A_POSITIVE_NUMBER

        );

        const throbber = $scope.setLoading("settings-" + deviceId, true);

        const parameters = {

            id: deviceId,
            type: "settings"

        };

        const led = $scope.getDeviceLed(deviceId);
        ValidationUtilities.isNotNullOrUndefined(led, deviceSettingsMessages.LED_CAN_NOT_BE_NULL_OR_UNDEFINED);

        const successHandler = function(model) {

            const successHandlerMessages = deviceSettingsMessages.SuccessHandler;
            ValidationUtilities.isNotEmpty(model, successHandlerMessages.MODEL_CAN_NOT_BE_EMPTY);

            throbber.off();
            model.id = deviceId;

            model.volumeLimits = {

                minimum: 0,
                maximum: 100

            };

            $scope.setCurrentDevice(model);
            $scope.showModal("deviceSettingsModal");

            SuccessService.handleLedSuccess(led);

        };

        const failHandler = function() {

            const failHandlerMessages = deviceSettingsMessages.FailHandler;
            throbber.off();

            const deviceName = device.name;
            const hasDeviceName = !ValueUtilities.isNullOrUndefined(deviceName);

            if (hasDeviceName) {

                ValidationUtilities.isString(

                    deviceName, failHandlerMessages.DEVICE_NAME_HAS_TO_BE_A_STRING

                );

            }

            const message = failHandlerMessages.getFailedToLoadDeviceMessage(deviceId, deviceName);
            const alert = AlertService.getDangerAlertWithAlertGlyphicon(message);

            ValidationUtilities.isNotNullOrUndefined(

                alert, failHandlerMessages.ALERT_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            ValidationUtilities.isNotEmpty(alert, failHandlerMessages.ALERT_CAN_NOT_BE_EMPTY);

            ErrorService.handleLedError(led, alert);

        };

        Devices.get(parameters, null, successHandler, failHandler);

    };

    const editDevice = function(device) {

        const editDeviceMessages = DevicesControllerMessages.EditDevice;
        ValidationUtilities.isNotEmpty(device, editDeviceMessages.DEVICE_CAN_NOT_BE_EMPTY);

        const deviceId = device.id;
        ValidationUtilities.isPositiveNumber(deviceId, editDeviceMessages.DEVICE_ID_HAS_TO_BE_A_POSITIVE_NUMBER);

        const throbber = $scope.setLoading("edit-" + deviceId, true);

        const parameters = {

            id: deviceId,
            type: "edit"

        };

        const led = $scope.getDeviceLed(deviceId);
        ValidationUtilities.isNotNullOrUndefined(led, editDeviceMessages.LED_CAN_NOT_BE_NULL_OR_UNDEFINED);

        const successHandler = function(addOrEditDeviceViewModel) {

            const successHandlerMessages = editDeviceMessages.SuccessHandler;

            ValidationUtilities.isNotNullOrUndefined(

                addOrEditDeviceViewModel, successHandlerMessages.ADD_OR_EDIT_DEVICE_VIEW_MODEL_CAN_NOT_BE_EMPTY

            );

            throbber.off();
            $scope.setCurrentDevice(addOrEditDeviceViewModel);
            SuccessService.handleLedSuccess(led);
            $scope.showModal("editDeviceModal");

        };

        const failHandler = function() {

            const failHandlerMessages = editDeviceMessages.FailHandler;
            throbber.off();

            const deviceName = device.name;
            const hasDeviceName = !ValueUtilities.isNullOrUndefined(deviceName);

            if (hasDeviceName) {

                ValidationUtilities.isString(

                    deviceName, failHandlerMessages.DEVICE_NAME_HAS_TO_BE_A_STRING

                );

            }

            const message = failHandlerMessages.getFailedToLoadDeviceMessage(deviceId, deviceName);
            const alert = AlertService.getDangerAlertWithAlertGlyphicon(message);

            ValidationUtilities.isNotNullOrUndefined(

                alert, failHandlerMessages.ALERT_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            ValidationUtilities.isNotEmpty(alert, failHandlerMessages.ALERT_CAN_NOT_BE_EMPTY);

            ErrorService.handleLedError(led, alert);

        };

        Devices.get(parameters, null, successHandler, failHandler);

    };

    const downloadContent = function(device) {

        const downloadContentMessage = DevicesControllerMessages.DownloadContent;

        ValidationUtilities.isNotNullOrUndefined(device, downloadContentMessage.DEVICE_CAN_NOT_BE_NULL_OR_UNDEFINED);
        ValidationUtilities.isNotEmpty(device, downloadContentMessage.DEVICE_CAN_NOT_BE_EMPTY);

        const deviceId = device.id;
        ValidationUtilities.isPositiveNumber(deviceId, downloadContentMessage.DEVICE_ID_HAS_TO_BE_A_POSITIVE_NUMBER);

        $scope.setCurrentDevice(device);
        $scope.showModal("downloadContentModal");

    };

    const isDeviceInAnyGroup = function(device) {

        const isDeviceInAnyGroupMessages = DevicesControllerMessages.IsDeviceInAnyGroup;

        ValidationUtilities.isNotNullOrUndefined(

            device, isDeviceInAnyGroupMessages.DEVICE_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        const devicesInGroup = $scope.devicesInGroup;

        ValidationUtilities.isNotNullOrUndefined(

            devicesInGroup, isDeviceInAnyGroupMessages.DEVICES_IN_GROUP_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        const deviceId = device.id;

        ValidationUtilities.isPositiveNumber(

            deviceId, isDeviceInAnyGroupMessages.DEVICE_ID_HAS_TO_BE_A_POSITIVE_NUMBER

        );

        return devicesInGroup[deviceId] === true;

    };

    const getFirstFoundGroup = function(device, groups) {

        const getFirstFoundGroupMessages = DevicesControllerMessages.GetFirstFoundGroup;

        ValidationUtilities.isNotNullOrUndefined(

            device, getFirstFoundGroupMessages.DEVICE_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        ValidationUtilities.isNotNullOrUndefined(

            groups, getFirstFoundGroupMessages.GROUPS_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        let foundGroup = null;
        let groupFound = false;

        const checkGroup = function(group) {

            const checkGroupMessages = getFirstFoundGroupMessages.CheckGroup;

            ValidationUtilities.isNotNullOrUndefined(

                group, checkGroupMessages.GROUP_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            ValidationUtilities.isNotEmpty(group, checkGroupMessages.GROUP_CAN_NOT_BE_EMPTY);

            const isDeviceInGroup = function() {

                const isDeviceInGroupMessages = checkGroupMessages.IsDeviceInGroup;

                const deviceId = device.id;

                ValidationUtilities.isPositiveNumber(

                    deviceId, isDeviceInGroupMessages.DEVICE_ID_HAS_TO_BE_A_POSITIVE_NUMBER

                );

                const checkDeviceId = function(device) {

                    const checkDeviceIdMessages = isDeviceInGroupMessages.CheckDeviceId;

                    ValidationUtilities.isNotNullOrUndefined(

                        device, checkDeviceIdMessages.DEVICE_CAN_NOT_BE_NULL_OR_UNDEFINED

                    );

                    ValidationUtilities.isNotEmpty(device, checkDeviceIdMessages.DEVICE_CAN_NOT_BE_EMPTY);

                    const deviceIdToCheck = device.id;

                    ValidationUtilities.isPositiveNumber(

                        deviceIdToCheck, checkDeviceIdMessages.DEVICE_ID_TO_CHECK_HAS_TO_BE_A_POSITIVE_NUMBER

                    );

                    if (deviceId === deviceIdToCheck) {

                        return true;

                    }

                };

                const devices = group.devices;

                ValidationUtilities.isNotNullOrUndefined(

                    devices, isDeviceInGroupMessages.DEVICES_CAN_NOT_BE_NULL_OR_UNDEFINED

                );

                ValidationUtilities.isNotEmpty(devices, isDeviceInGroupMessages.DEVICES_CAN_NOT_BE_EMPTY);

                return devices.some(checkDeviceId);

            };

            if (groupFound === true) {

                return;

            }

            const isTheDeviceInGroup = isDeviceInGroup();

            ValidationUtilities.isBoolean(

                isTheDeviceInGroup, checkGroupMessages.IS_THE_DEVICE_IN_GROUP_HAS_TO_BE_A_BOOLEAN

            );

            if (isTheDeviceInGroup) {

                foundGroup = group;
                groupFound = true;

            }

        };

        groups.forEach(checkGroup);

        return foundGroup;

    };

    const deleteDevice = function(device) {

        const deleteDeviceMessages = DevicesControllerMessages.DeleteDevice;
        ValidationUtilities.isNotNullOrUndefined(device, deleteDeviceMessages.DEVICE_CAN_NOT_BE_NULL_OR_UNDEFINED);
        ValidationUtilities.isNotEmpty(device, deleteDeviceMessages.DEVICE_CAN_NOT_BE_EMPTY);

        const deviceId = device.id;
        ValidationUtilities.isPositiveNumber(deviceId, deleteDeviceMessages.DEVICE_ID_HAS_TO_BE_A_POSITIVE_NUMBER);

        const led = $scope.getDeviceLed(deviceId);
        ValidationUtilities.isNotNullOrUndefined(led, deleteDeviceMessages.LED_CAN_NOT_BE_NULL_OR_UNDEFINED);

        const deviceName = device.name;
        const hasDeviceName = !ValueUtilities.isNullOrUndefined(deviceName);

        if (hasDeviceName) {

            ValidationUtilities.isString(deviceName, deleteDeviceMessages.DEVICE_NAME_HAS_TO_BE_A_STRING);

        }

        const isTheDeviceInAnyGroup = isDeviceInAnyGroup(device);

        ValidationUtilities.isBoolean(

            isTheDeviceInAnyGroup, deleteDeviceMessages.IS_THE_DEVICE_IN_ANY_GROUP_HAS_TO_BE_A_BOOLEAN

        );

        if (isTheDeviceInAnyGroup) {

            const groups = $scope.groups;

            ValidationUtilities.isNotNullOrUndefined(

                groups, deleteDeviceMessages.GROUPS_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            const group = getFirstFoundGroup(device, groups);

            ValidationUtilities.isNotNullOrUndefined(

                group, deleteDeviceMessages.GROUP_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            ValidationUtilities.isNotEmpty(group, deleteDeviceMessages.GROUP_CAN_NOT_BE_EMPTY);

            const groupId = group.id;

            ValidationUtilities.isPositiveNumber(

                groupId, deleteDeviceMessages.GROUP_ID_HAS_TO_BE_A_POSITIVE_NUMBER

            );

            const groupName = group.name;
            const hasGroupName = !ValueUtilities.isNullOrUndefined(groupName);

            if (hasGroupName) {

                ValidationUtilities.isString(groupName, deleteDeviceMessages.GROUP_NAME_HAS_TO_BE_A_STRING);

            }

            const message = deleteDeviceMessages.getDeviceIsStillInGroupMessage(

                deviceId, deviceName, groupId, groupName

            );

            const alert = AlertService.getDangerAlertWithAlertGlyphicon(message);

            ValidationUtilities.isNotNullOrUndefined(

                alert, deleteDeviceMessages.ALERT_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            ValidationUtilities.isNotEmpty(alert, deleteDeviceMessages.ALERT_CAN_NOT_BE_EMPTY);

            ErrorService.handleLedError(led, alert);

            return;

        }

        const parameters = {

            id: deviceId

        };

        const successHandler = function() {

            const successHandlerMessages = deleteDeviceMessages.SuccessHandler;

            SuccessService.handleLedSuccess(led);

            const polling = $scope.polling;
            ValidationUtilities.isNotEmpty(polling, successHandlerMessages.POLLING_CAN_NOT_BE_EMPTY);

            polling.update();

        };

        const failHandler = function() {

            const failHandlerMessages = deleteDeviceMessages.FailHandler;

            const message = failHandlerMessages.getFailedToDeleteDeviceMessage(deviceId, deviceName);
            const alert = AlertService.getDangerAlertWithAlertGlyphicon(message);

            ValidationUtilities.isNotNullOrUndefined(

                alert, failHandlerMessages.ALERT_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            ValidationUtilities.isNotEmpty(alert, failHandlerMessages.ALERT_CAN_NOT_BE_EMPTY);

            ErrorService.handleLedError(led, alert);

        };

        Devices.delete(parameters, successHandler, failHandler);

    };

    // Misc
    const enoughCheckedDevices = function() {

        const enoughCheckedDevicesMessages = DevicesControllerMessages.EnoughCheckedDevices;
        const checkedDevices = $scope.getCheckedDevices();

        ValidationUtilities.isNotNullOrUndefined(

            checkedDevices, enoughCheckedDevicesMessages.CHECKED_DEVICES_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        return checkedDevices.length >= 2;

    };

    const runBackgroundTask = function() {

        const runBackgroundTaskMessages = DevicesControllerMessages.RunBackgroundTask;

        const successHandler = function() {

            const successHandlerMessages = runBackgroundTaskMessages.SuccessHandler;

            const polling = $scope.polling;
            ValidationUtilities.isNotEmpty(polling, successHandlerMessages.POLLING_CAN_NOT_BE_EMPTY);

            polling.update();
            loadBackgroundTaskStatus();

        };

        const failHandler = function(response) {

            const failHandlerMessages = runBackgroundTaskMessages.FailHandler;

            ValidationUtilities.isNotNullOrUndefined(

                response, failHandlerMessages.RESPONSE_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            const data = response.data;
            ValidationUtilities.isNotNullOrUndefined(data, failHandlerMessages.DATA_CAN_NOT_BE_NULL_OR_UNDEFINED);

            const message = data.message;
            ValidationUtilities.isString(message, failHandlerMessages.MESSAGE_HAS_TO_BE_A_STRING);

            alert(message);

        };

        DevicesData.save({}, null, successHandler, failHandler);
        $timeout(loadBackgroundTaskStatus, 200);

    };

    const loadBackgroundTaskStatus = function(checkPolling) {

        const loadBackgroundTaskStatusMessages = DevicesControllerMessages.LoadBackgroundTaskStatus;

        const hasCheckPolling = !ValueUtilities.isNullOrUndefined(checkPolling);

        if (hasCheckPolling) {

            ValidationUtilities.isBoolean(

                checkPolling, loadBackgroundTaskStatusMessages.CHECK_POLLING_HAS_TO_BE_A_BOOLEAN

            );

            const polling = $scope.polling;
            ValidationUtilities.isNotEmpty(polling, loadBackgroundTaskStatusMessages.POLLING_CAN_NOT_BE_EMPTY);

            const isPollingEnabled = polling.isEnabled();

            ValidationUtilities.isBoolean(

                isPollingEnabled, loadBackgroundTaskStatusMessages.IS_POLLING_ENABLED_HAS_TO_BE_A_BOOLEAN

            );

            if (!isPollingEnabled) {

                return;

            }

        }

        const successHandler = function(response) {

            const successHandlerMessages = loadBackgroundTaskStatusMessages.SuccessHandler;

            ValidationUtilities.isNotNullOrUndefined(

                response, successHandlerMessages.RESPONSE_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            const result = response.result;
            ValidationUtilities.isBoolean(result, successHandlerMessages.RESULT_HAS_TO_BE_A_BOOLEAN);

            backgroundTaskRunning = result;

        };

        return DevicesData.get(successHandler);

    };

    $interval(function() {

        loadBackgroundTaskStatus(true);

    }, 30000);

    const isBackgroundTaskRunning = function() {

        return backgroundTaskRunning === true;

    };

    const getBackgroundTaskStatus = function() {

        const getBackgroundTaskStatusMessages = DevicesControllerMessages.GetBackgroundTaskStatus;

        const isRunning = isBackgroundTaskRunning();
        ValidationUtilities.isBoolean(isRunning, getBackgroundTaskStatusMessages.IS_RUNNING_HAS_TO_BE_A_BOOLEAN);

        return isRunning ? " (running)" : "";

    };

    const getDeleteDeviceButtonTitle = function(device) {

        const deleteDeviceButtonTitleMessages = DevicesControllerMessages.GetDeleteDeviceButtonTitle;

        ValidationUtilities.isNotNullOrUndefined(

            device, deleteDeviceButtonTitleMessages.DEVICE_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        const groups = $scope.groups;

        ValidationUtilities.isNotNullOrUndefined(

            groups, deleteDeviceButtonTitleMessages.GROUPS_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        const isTheDeviceInAnyGroup = isDeviceInAnyGroup(device);

        if (isTheDeviceInAnyGroup) {

            const group = getFirstFoundGroup(device, groups);

            ValidationUtilities.isNotNullOrUndefined(

                group, deleteDeviceButtonTitleMessages.GROUP_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            ValidationUtilities.isNotEmpty(group, deleteDeviceButtonTitleMessages.GROUP_CAN_NOT_BE_EMPTY);

            const groupId = group.id;

            ValidationUtilities.isPositiveNumber(

                groupId, deleteDeviceButtonTitleMessages.GROUP_ID_HAS_TO_BE_A_POSITIVE_NUMBER

            );

            const groupName = group.name;
            const hasGroupName = !ValueUtilities.isNullOrUndefined(groupName);

            if (hasGroupName) {

                ValidationUtilities.isString(

                    groupName, deleteDeviceButtonTitleMessages.GROUP_NAME_HAS_TO_BE_A_STRING

                );

            }

            const message = deleteDeviceButtonTitleMessages.getDeviceIsStillInGroupMessage(groupId, groupName);
            ValidationUtilities.isString(message, deleteDeviceButtonTitleMessages.MESSAGE_HAS_TO_BE_A_STRING);

            return message;

        } else {

            return "Delete device";

        }

    };

    const getDeleteDeviceButtonClass = function(device) {

        const getDeleteDeviceButtonClassMessages = DevicesControllerMessages.GetDeleteDeviceButtonClass;

        ValidationUtilities.isNotNullOrUndefined(

            device, getDeleteDeviceButtonClassMessages.DEVICE_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        const isTheDeviceInAnyGroup = isDeviceInAnyGroup(device);

        return {

            opacityDisabled: isTheDeviceInAnyGroup

        };

    };

    const getSortGlyphiconClass = function(column) {

        const getSortGlyphiconClassMessages = DevicesControllerMessages.GetSortGlyphiconClass;

        ValidationUtilities.isString(

            column, getSortGlyphiconClassMessages.COLUMN_HAS_TO_BE_A_STRING

        );

        ValidationUtilities.isTrue(column.length > 0, getSortGlyphiconClassMessages.COLUMN_CAN_NOT_BE_EMPTY);

        const sorting = $scope.devicesSorting;

        const sortColumn = sorting.column;
        ValidationUtilities.isString(sortColumn, getSortGlyphiconClassMessages.SORT_COLUMN_HAS_TO_BE_A_STRING);
        ValidationUtilities.isTrue(sortColumn.length > 0, getSortGlyphiconClassMessages.SORT_COLUMN_CAN_NOT_BE_EMPTY);

        if (column === sortColumn) {

            const direction = sorting.direction;
            ValidationUtilities.isString(direction, getSortGlyphiconClassMessages.DIRECTION_HAS_TO_BE_A_STRING);
            ValidationUtilities.isTrue(direction.length > 0, getSortGlyphiconClassMessages.DIRECTION_CAN_NOT_BE_EMPTY);

            if (direction === "desc") {

                return "glyphicon-sort-by-alphabet-alt";

            } else {

                return "glyphicon-sort-by-alphabet";

            }

        }

        return "";

    };

    const sort = function(column) {

        const sortMessages = DevicesControllerMessages.Sort;

        ValidationUtilities.isString(

            column, sortMessages.COLUMN_HAS_TO_BE_A_STRING

        );

        ValidationUtilities.isTrue(column.length > 0, sortMessages.COLUMN_CAN_NOT_BE_EMPTY);

        const sorting = $scope.devicesSorting;

        const sortColumn = sorting.column;
        ValidationUtilities.isString(sortColumn, sortMessages.SORT_COLUMN_HAS_TO_BE_A_STRING);
        ValidationUtilities.isTrue(sortColumn.length > 0, sortMessages.SORT_COLUMN_CAN_NOT_BE_EMPTY);

        if (sortColumn === column) {

            const direction = sorting.direction;
            ValidationUtilities.isString(direction, sortMessages.DIRECTION_HAS_TO_BE_A_STRING);
            ValidationUtilities.isTrue(direction.length > 0, sortMessages.DIRECTION_CAN_NOT_BE_EMPTY);

            if (direction === "asc") {

                sorting.direction = "desc";

            } else {

                sorting.direction = "asc";

            }

        } else {

            sorting.column = column;
            sorting.direction = "asc";

        }

        const successHandler = function(devices) {

            const successHandlerMessages = sortMessages.SuccessHandler;

            ValidationUtilities.isNotNullOrUndefined(

                devices, successHandlerMessages.DEVICES_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            $scope.setDeviceList(devices);

        };

        DeviceService
            .getDevices(sorting.column, sorting.direction)
            .$promise
            .then(successHandler);

    };

    const importDevices = function() {

        $scope.showModal("importDevicesModal");

    };

    const exportDevices = function() {

        const exportDevicesMessages = DevicesControllerMessages.ExportDevices;

        const parameters = {

            action: "export"

        };

        const checkedDevices = $scope.getCheckedDevices();

        ValidationUtilities.isNotNullOrUndefined(

            checkedDevices, exportDevicesMessages.CHECKED_DEVICES_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        const deviceIds = checkedDevices.map(device => device.id);
        const deviceLeds = deviceIds.map($scope.getDeviceLed);

        const checkedGroups = $scope.getCheckedGroups();

        ValidationUtilities.isNotNullOrUndefined(

            checkedGroups, exportDevicesMessages.CHECKED_GROUPS_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        const groupIds = checkedGroups.map(group => group.id);
        const groupLeds = groupIds.map($scope.getGroupLed);

        const exportViewModel = {

            devices: deviceIds,
            groups: groupIds

        };

        const successHandler = function() {

            const successHandlerMessages = exportDevicesMessages.SuccessHandler;

            const uncheckDevice = function(deviceId) {

                const uncheckDeviceMessages = successHandlerMessages.UncheckDevice;

                ValidationUtilities.isPositiveNumber(

                    deviceId, uncheckDeviceMessages.DEVICE_ID_HAS_TO_BE_A_POSITIVE_NUMBER

                );

                $scope.checkedDevices[deviceId] = false;

            };

            deviceIds.forEach(uncheckDevice);

            const uncheckGroup = function(groupId) {

                const uncheckGroupMessages = successHandlerMessages.UncheckGroup;

                ValidationUtilities.isPositiveNumber(

                    groupId, uncheckGroupMessages.GROUP_ID_HAS_TO_BE_A_POSITIVE_NUMBER

                );

                $scope.checkedGroups[groupId] = false;

            };

            groupIds.forEach(uncheckGroup);

            const handleLedSuccess = function(led) {

                const handleLedSuccessMessages = successHandlerMessages.HandleLedSuccess;

                ValidationUtilities.isNotNullOrUndefined(

                    led, handleLedSuccessMessages.LED_CAN_NOT_BE_NULL_OR_UNDEFINED

                );

                ValidationUtilities.isNotEmpty(led, handleLedSuccessMessages.LED_CAN_NOT_BE_EMPTY);

                SuccessService.handleLedSuccess(led);

            };

            deviceLeds.forEach(handleLedSuccess);
            groupLeds.forEach(handleLedSuccess);

        };

        const failHandler = function() {

            const failHandlerMessages = exportDevicesMessages.FailHandler;

            const handleLedError = function(led) {

                const handleLedErrorMessages = failHandlerMessages.HandleLedError;

                ValidationUtilities.isNotNullOrUndefined(

                    led, handleLedErrorMessages.LED_CAN_NOT_BE_NULL_OR_UNDEFINED

                );

                ValidationUtilities.isNotEmpty(led, handleLedErrorMessages.LED_CAN_NOT_BE_EMPTY);

                const message = handleLedErrorMessages.FAILED_TO_EXPORT_DEVICE;
                const alert = AlertService.getDangerAlertWithAlertGlyphicon(message);

                ValidationUtilities.isNotNullOrUndefined(

                    alert, handleLedErrorMessages.ALERT_CAN_NOT_BE_NULL_OR_UNDEFINED

                );

                ValidationUtilities.isNotEmpty(alert, handleLedErrorMessages.ALERT_CAN_NOT_BE_EMPTY);

                ErrorService.handleLedError(led, alert);

            };

            deviceLeds.forEach(handleLedError);
            groupLeds.forEach(handleLedError);

        };

        DeviceActions.save(parameters, exportViewModel, successHandler, failHandler);

    };

    return {

        saveSetting: saveSetting,
        detectDevices: detectDevices,
        addDeviceModal: addDeviceModal,
        createGroupModal: createGroupModal,
        assignContentModal: assignContentModal,
        settingsModal: settingsModal,
        deviceInfo: deviceInfo,
        deviceSettings: deviceSettings,
        editDevice: editDevice,
        downloadContent: downloadContent,
        deleteDevice: deleteDevice,
        enoughCheckedDevices: enoughCheckedDevices,
        isBackgroundTaskRunning: isBackgroundTaskRunning,
        runBackgroundTask: runBackgroundTask,
        getBackgroundTaskStatus: getBackgroundTaskStatus,
        getDeleteDeviceButtonTitle: getDeleteDeviceButtonTitle,
        getDeleteDeviceButtonClass: getDeleteDeviceButtonClass,
        getSortGlyphiconClass: getSortGlyphiconClass,
        sort: sort,
        importDevices: importDevices,
        exportDevices: exportDevices

    };

};

export default DevicesController;
