import ValidationUtilities from "../../utilities/validationUtilities";
import AddDeviceControllerMessages from "../../messages/controllers/add_device/addDeviceController";

const AddDeviceController = function(
    ErrorService, SuccessService, AlertService, LedService, PopoverService, Devices, Settings, $scope
) {

    // Popover
    const title = "Error";
    const popover = PopoverService.getAlertsPopoverWithPlacementBottom(title);

    ValidationUtilities.isNotNullOrUndefined(
        popover, AddDeviceControllerMessages.POPOVER_CAN_NOT_BE_NULL_OR_UNDEFINED
    );

    // Led
    const led = LedService.getGreenOnLed(popover);
    ValidationUtilities.isNotNullOrUndefined(led, AddDeviceControllerMessages.LED_CAN_NOT_BE_NULL_OR_UNDEFINED);

    const addDevice = function(device) {
        const addDeviceMessages = AddDeviceControllerMessages.AddDevice;
        ValidationUtilities.isNotEmpty(device, addDeviceMessages.DEVICE_CAN_NOT_BE_EMPTY);

        const successHandler = function() {
            const successHandlerMessages = addDeviceMessages.SuccessHandler;

            SuccessService.handleLedSuccess(led);

            const polling = $scope.polling;
            ValidationUtilities.isNotEmpty(polling, successHandlerMessages.POLLING_CAN_NOT_BE_EMPTY);

            polling.update();

            $scope.hideModal("addDeviceModal");
        };

        const failHandler = function() {
            const failHandlerMessages = addDeviceMessages.FailHandler;

            const message = failHandlerMessages.FAILED_TO_ADD_DEVICE;
            const alert = AlertService.getDangerAlertWithAlertGlyphicon(message);

            ValidationUtilities.isNotNullOrUndefined(
                alert, failHandlerMessages.ALERT_CAN_NOT_BE_NULL_OR_UNDEFINED
            );

            ValidationUtilities.isNotEmpty(alert, failHandlerMessages.ALERT_CAN_NOT_BE_EMPTY);

            ErrorService.handleLedError(led, alert);
        };

        Devices.save({}, device, successHandler, failHandler);
    };

    const getNewDevice = function() {
        const ipDestination = {
            port: 5000,
            controlId: 1,
            groupId: 0
        };

        const ftpSettings = {
            useDefault: true
        };

        return {
            ipDestination: ipDestination,
            ftpSettings: ftpSettings
        };
    };

    angular.element("#addDeviceModal").on("hidden.bs.modal", function() {
        SuccessService.handleLedSuccess(led);
    });

    return {
        led: led,

        addDevice: addDevice,
        getNewDevice: getNewDevice
    };

};

export default AddDeviceController;
