import ValidationUtilities from "../utilities/validationUtilities";

import RootControllerMessages from "../messages/controllers/root/rootController";

const RootController = function($rootScope) {

    // Loading

    $rootScope.loading = {};

    /**
     * Sets $rootScope.loading[name] to true (or to value if given) until .off() on the returned object is called.
     * Use for 'busy/loading' state display.
     */
    $rootScope.setLoading = function(name, value) {

        const setLoadingMessages = RootControllerMessages.SetLoading;

        ValidationUtilities.isString(name, setLoadingMessages.NAME_HAS_TO_BE_A_STRING);
        ValidationUtilities.isTrue(name.length > 0, setLoadingMessages.NAME_CAN_NOT_BE_EMPTY);

        ValidationUtilities.isBoolean(value, setLoadingMessages.VALUE_HAS_TO_BE_A_BOOLEAN);

        $rootScope.loading[name] = value;

        const off = function() {

            $rootScope.loading[name] = false;

        };

        return {

            off: off

        };

    };

    /**
     * Returns $rootScope.loading[name].
     */
    $rootScope.getLoading = function(name) {

        const getLoadingMessages = RootControllerMessages.GetLoading;

        ValidationUtilities.isString(name, getLoadingMessages.NAME_HAS_TO_BE_A_STRING);
        ValidationUtilities.isTrue(name.length > 0, getLoadingMessages.NAME_CAN_NOT_BE_EMPTY);

        return $rootScope.loading[name] === true;

    };

};

export default RootController;
