import ValidationUtilities from "../utilities/validationUtilities";
import AlertsPopoverLedDirectiveMessages from "../messages/directives/alerts_popover_led/alertsPopoverLedDirective";

const alertsPopoverLedDirective = function(LedColor, LedStatus) {

    const scope = {

        led: "=led"

    };

    const link = function(scope) {

        const linkMessages = AlertsPopoverLedDirectiveMessages.Link;

        scope.alertsSeen = function() {

            const led = scope.led;
            led.status = LedStatus.OFF;

        };

        scope.isErrorLed = function() {

            const isErrorLedMessages = linkMessages.IsErrorLed;

            const led = scope.led;
            ValidationUtilities.isNotNullOrUndefined(led, isErrorLedMessages.LED_CAN_NOT_BE_NULL_OR_UNDEFINED);

            const color = led.color;
            ValidationUtilities.isNotNullOrUndefined(color, isErrorLedMessages.COLOR_CAN_NOT_BE_NULL_OR_UNDEFINED);

            return color === LedColor.RED;

        };

        scope.getLedClass = function() {

            const getLedClassMessages = linkMessages.GetLedClass;

            const led = scope.led;
            ValidationUtilities.isNotNullOrUndefined(led, getLedClassMessages.LED_CAN_NOT_BE_NULL_OR_UNDEFINED);

            const color = led.color;
            ValidationUtilities.isNotNullOrUndefined(color, getLedClassMessages.COLOR_CAN_NOT_BE_NULL_OR_UNDEFINED);

            const status = led.status;
            ValidationUtilities.isNotNullOrUndefined(status, getLedClassMessages.STATUS_CAN_NOT_BE_NULL_OR_UNDEFINED);

            return "led-" + color + "-" + status;

        };

    };

    return {

        restrict: "E",
        scope: scope,
        templateUrl: "directives/alertsPopoverLed.html",
        link: link

    };

};

export default alertsPopoverLedDirective;
