import ValueUtilities from "../utilities/valueUtilities";
import ValidationUtilities from "../utilities/validationUtilities";

import PopoverServiceMessages from "../messages/services/popover/popoverService";

class PopoverService {

    constructor(PopoverPlacement) {

        this._PopoverPlacement = PopoverPlacement;

    }

    static get _popoverServiceMessages() {

        return PopoverServiceMessages;

    }

    /**
     * Gets the maximum number of alerts.
     *
     * @return {number}, the maximum number of alerts.
     */
    static get MAXIMUM_NUMBER_OF_ALERTS() {

        return 3;

    }

    getPopover(templateUrl, placement, title) {

        const getPopoverMessages = PopoverService._popoverServiceMessages.GetPopover;

        // Validation \\

        // Template URL

        ValidationUtilities.isString(templateUrl, getPopoverMessages.TEMPLATE_URL_HAS_TO_BE_A_STRING);
        ValidationUtilities.isTrue(templateUrl.length > 0, getPopoverMessages.TEMPLATE_URL_CAN_NOT_BE_EMPTY);

        // Placement

        ValidationUtilities.isString(placement, getPopoverMessages.PLACEMENT_HAS_TO_BE_A_STRING);
        ValidationUtilities.isTrue(placement.length > 0, getPopoverMessages.PLACEMENT_CAN_NOT_BE_EMPTY);

        // Title

        ValidationUtilities.isString(title, getPopoverMessages.TITLE_HAS_TO_BE_A_STRING);
        ValidationUtilities.isTrue(title.length > 0, getPopoverMessages.TITLE_CAN_NOT_BE_EMPTY);

        // Popover \\

        return {

            templateUrl: templateUrl,
            placement: placement,
            title: title

        };

    }

    getAlertsPopover(placement, title, alerts) {

        const getAlertsPopoverMessages = PopoverService._popoverServiceMessages.GetAlertsPopover;

        // Validation \\

        // Placement

        ValidationUtilities.isString(placement, getAlertsPopoverMessages.PLACEMENT_HAS_TO_BE_A_STRING);
        ValidationUtilities.isTrue(placement.length > 0, getAlertsPopoverMessages.PLACEMENT_CAN_NOT_BE_EMPTY);

        // Title

        ValidationUtilities.isString(title, getAlertsPopoverMessages.TITLE_HAS_TO_BE_A_STRING);
        ValidationUtilities.isTrue(title.length > 0, getAlertsPopoverMessages.TITLE_CAN_NOT_BE_EMPTY);

        // Popover \\

        const templateUrl = "directives/alertsPopover.html";
        const popover = this.getPopover(templateUrl, placement, title);

        ValidationUtilities.isNotNullOrUndefined(

            popover, getAlertsPopoverMessages.POPOVER_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        const hasAlerts = !ValueUtilities.isNullOrUndefined(alerts);
        ValidationUtilities.isBoolean(hasAlerts, getAlertsPopoverMessages.HAS_ALERTS_HAS_TO_BE_A_BOOLEAN);

        if (hasAlerts) {

            const numberOfAlerts = alerts.length;

            if (numberOfAlerts > PopoverService.MAXIMUM_NUMBER_OF_ALERTS) {

                popover.alerts = alerts.slice(0, PopoverService.MAXIMUM_NUMBER_OF_ALERTS);

            } else {

                popover.alerts = alerts;

            }

        } else {

            popover.alerts = [];

        }

        popover.addAlert = function(alert) {

            const addAlertMessages = getAlertsPopoverMessages.AddAlert;

            ValidationUtilities.isNotNullOrUndefined(

                alert, addAlertMessages.ALERT_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            const alerts = popover.alerts;

            ValidationUtilities.isNotNullOrUndefined(

                alerts, addAlertMessages.ALERTS_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            while (alerts.length >= PopoverService.MAXIMUM_NUMBER_OF_ALERTS) {

                alerts.shift();

            }

            alerts.push(alert);

        };

        return popover;

    }

    getAlertsPopoverWithPlacementBottom(title, alerts) {

        const getAlertsPopoverWithPlacementBottomMessages =
            PopoverService._popoverServiceMessages.GetAlertsPopoverWithPlacementBottom;

        // Validate title \\

        ValidationUtilities.isString(title, getAlertsPopoverWithPlacementBottomMessages.TITLE_HAS_TO_BE_A_STRING);
        ValidationUtilities.isTrue(title.length > 0, getAlertsPopoverWithPlacementBottomMessages.TITLE_CAN_NOT_BE_EMPTY);

        // Popover \\

        const placement = this._PopoverPlacement.BOTTOM;

        return this.getAlertsPopover(placement, title, alerts);

    }

    getAlertsPopoverWithPlacementBottomLeft(title, alerts) {

        // Popover \\

        const placement = this._PopoverPlacement.BOTTOM_LEFT;

        return this.getAlertsPopover(placement, title, alerts);

    }

}

export default PopoverService;
