const AjaxSessionTimeoutInterceptor = function($window, $q) {

    const responseError = function(response) {

        const status = response.status;

        if (status === 418) {

            $q.reject(response);
            $window.location.href = "/smartcontrol/login";

        } else {

            return $q.reject(response);

        }

    };

    return {

        responseError: responseError

    };

};

export default AjaxSessionTimeoutInterceptor;
