import ValueUtilities from "../../utilities/valueUtilities";
import ValidationUtilities from "../../utilities/validationUtilities";
import StringUtilities from "../../utilities/stringUtilities";

import SettingsControllerMessages from "../../messages/controllers/settings/settingsController";

const SettingsController = function(
    ErrorService, SuccessService, AlertService, LedService, PopoverService, Settings, $scope, $timeout
) {

    // Timeouts

    const timeouts = {};

    // Popover

    const title = "Error";

    const popover = PopoverService.getAlertsPopoverWithPlacementBottom(title);

    ValidationUtilities.isNotNullOrUndefined(
        popover, SettingsControllerMessages.POPOVER_CAN_NOT_BE_NULL_OR_UNDEFINED
    );

    // Led

    const led = LedService.getGreenOnLed(popover);
    ValidationUtilities.isNotNullOrUndefined(led, SettingsControllerMessages.LED_CAN_NOT_BE_NULL_OR_UNDEFINED);

    // Network adapters

    let networkAdapters = [];
    let showNetworkAdapters = false;

    const getNetworkAdapters = function() {
        return networkAdapters;
    };

    const shouldShowNetworkAdapters = function() {
        return showNetworkAdapters;
    };

    const loadSettings = function() {

        const loadSettingsMessages = SettingsControllerMessages.LoadSettings;
        const throbber = $scope.setLoading("settings", true);

        const successHandler = function(settings) {

            const successHandlerMessages = loadSettingsMessages.SuccessHandler;

            ValidationUtilities.isNotEmpty(settings, successHandlerMessages.SETTINGS_CAN_NOT_BE_EMPTY);

            throbber.off();
            $scope.settings = settings;

        };

        const failHandler = function() {

            const failHandlerMessages = loadSettingsMessages.FailHandler;
            throbber.off();

            const message = failHandlerMessages.FAILED_TO_GET_SETTINGS;
            const alert = AlertService.getDangerAlertWithAlertGlyphicon(message);

            ValidationUtilities.isNotNullOrUndefined(
                alert, failHandlerMessages.ALERT_CAN_NOT_BE_NULL_OR_UNDEFINED
            );

            ValidationUtilities.isNotEmpty(alert, failHandlerMessages.ALERT_CAN_NOT_BE_EMPTY);

            ErrorService.handleLedError(led, alert);

        };

        Settings.get({}, null, successHandler, failHandler);

    };

    const saveSetting = function(propertyPath, skipSettingValidCheck) {

        const saveSettingMessages = SettingsControllerMessages.SaveSetting;

        ValidationUtilities.isString(propertyPath, saveSettingMessages.PROPERTY_PATH_HAS_TO_BE_A_STRING);
        ValidationUtilities.isTrue(propertyPath.length > 0, saveSettingMessages.PROPERTY_PATH_CAN_NOT_BE_EMPTY);

        const splitPropertyPath = propertyPath.split(".");
        const propertyName = splitPropertyPath[0];
        const fieldName = propertyPath.slice(propertyName.length + 1);

        const existingTimeout = timeouts[propertyPath];

        if (existingTimeout) {

            $timeout.cancel(existingTimeout);
            delete timeouts[propertyPath];

        }

        let isSettingValid = false;

        const forms = $scope.forms;
        ValidationUtilities.isNotEmpty(forms, saveSettingMessages.FORMS_CAN_NOT_BE_EMPTY);

        const editSettingsForm = forms.editSettingsForm;
        ValidationUtilities.isNotEmpty(editSettingsForm, saveSettingMessages.EDIT_SETTINGS_FORM_CAN_NOT_BE_EMPTY);

        let property = null;
        let parsedFieldName = fieldName;

        if (!ValueUtilities.isEmpty(fieldName)) {

            if (propertyName === "defaultFtpSettings") {

                const capitalizedFieldName = StringUtilities.capitalize(fieldName);
                parsedFieldName = "defaultFtpSettings" + capitalizedFieldName;

            }

            const field = editSettingsForm[parsedFieldName];
            ValidationUtilities.isNotNullOrUndefined(field, saveSettingMessages.FIELD_CAN_NOT_BE_NULL_OR_UNDEFINED);

            isSettingValid = $scope.forms.editSettingsForm[parsedFieldName].$valid;
            property = fieldName;

        } else {

            const field = editSettingsForm[propertyName];
            ValidationUtilities.isNotNullOrUndefined(field, saveSettingMessages.FIELD_CAN_NOT_BE_NULL_OR_UNDEFINED);

            isSettingValid = $scope.forms.editSettingsForm[propertyName].$valid;

        }

        if (isSettingValid === true || skipSettingValidCheck === true) {

            const saveProperty = function() {

                const savePropertyMessages = saveSettingMessages.SaveProperty;
                const throbber = $scope.setLoading("saveSetting", true);

                let payload = null;
                let value;

                if ($scope.settings !== undefined) {

                    switch (propertyName) {

                        case "serverIp":

                            value = $scope.settings.serverIp;
                            break;

                        case "defaultFtpSettings":

                            if (property === "password") {

                                value = null;

                                payload = {

                                    password: $scope.settings.defaultFtpSettings.password

                                };

                            } else {

                                value = $scope.settings[propertyName][property];

                            }

                            break;

                    }
                }

                const settings = {

                    setting: propertyName,
                    property: property,
                    value: value

                };

                const successHandler = function() {
                    throbber.off();
                    SuccessService.handleLedSuccess(led);
                };

                const failHandler = function() {

                    const failHandlerMessages = savePropertyMessages.FailHandler;
                    throbber.off();

                    const message = failHandlerMessages.FAILED_TO_SAVE_SETTING;
                    const alert = AlertService.getDangerAlertWithAlertGlyphicon(message);

                    ValidationUtilities.isNotNullOrUndefined(
                        alert, failHandlerMessages.ALERT_CAN_NOT_BE_NULL_OR_UNDEFINED
                    );

                    ValidationUtilities.isNotEmpty(
                        alert, failHandlerMessages.ALERT_CAN_NOT_BE_EMPTY
                    );

                    ErrorService.handleLedError(led, alert);

                };

                Settings.put(settings, payload, successHandler, failHandler);

            };

            timeouts[propertyPath] = $timeout(saveProperty, 1000);

        }

    };

    const detectNetworkAdapters = function() {
        const detectNetworkAdaptersMessages = SettingsControllerMessages.DetectNetworkAdapters;
        const throbber = $scope.setLoading("detectNetworkAdapters", true);

        const parameters = {
            setting: "networkAdapters"
        };

        const successHandler = function(detectedNetworkAdapters) {
            const successHandlerMessages = detectNetworkAdaptersMessages.SuccessHandler;
            ValidationUtilities.isNotNullOrUndefined(
                detectedNetworkAdapters, successHandlerMessages.DETECTED_NETWORK_ADAPTERS_CAN_NOT_BE_NULL_OR_UNDEFINED
            );

            networkAdapters = detectedNetworkAdapters;
            showNetworkAdapters = true;
            throbber.off();
            SuccessService.handleLedSuccess(led);
        };

        const failHandler = function() {
            const failHandlerMessages = detectNetworkAdaptersMessages.FailHandler;
            throbber.off();
            const message = failHandlerMessages.FAILED_TO_DETECT_NETWORK_ADAPTERS;

            const alert = AlertService.getDangerAlertWithAlertGlyphicon(message);
            ValidationUtilities.isNotNullOrUndefined(alert, failHandlerMessages.ALERT_CAN_NOT_BE_NULL_OR_UNDEFINED);
            ValidationUtilities.isNotEmpty(alert, failHandlerMessages.ALERT_CAN_NOT_BE_EMPTY);

            ErrorService.handleLedError(led, alert);
        };

        Settings.query(parameters, successHandler, failHandler);
    };

    const selectNetworkAdapter = function(networkAdapter) {
        const selectNetworkAdapterMessages = SettingsControllerMessages.SelectNetworkAdapter;
        ValidationUtilities.isNotEmpty(networkAdapter, selectNetworkAdapterMessages.NETWORK_ADAPTER_CAN_NOT_BE_EMPTY);

        const settings = $scope.settings;
        ValidationUtilities.isNotNullOrUndefined(
            settings, selectNetworkAdapterMessages.SETTINGS_CAN_NOT_BE_NULL_OR_UNDEFINED
        );
        settings.serverIp = networkAdapter.ipv4Address;
        saveSetting("serverIp", true);
        showNetworkAdapters = false;
    };

    const resetEditSettingsForm = function() {

        const resetEditSettingsFormMessages = SettingsControllerMessages.ResetEditSettingsForm;

        const forms = $scope.forms;
        ValidationUtilities.isNotEmpty(forms, resetEditSettingsFormMessages.FORMS_CAN_NOT_BE_EMPTY);

        const editSettingsForm = forms.editSettingsForm;

        ValidationUtilities.isNotEmpty(
            editSettingsForm, resetEditSettingsFormMessages.EDIT_SETTINGS_FORM_CAN_NOT_BE_EMPTY
        );

        editSettingsForm.$setPristine();

    };

    angular.element("#settingsModal").on("show.bs.modal", loadSettings);
    angular.element("#settingsModal").on("hide.bs.modal", resetEditSettingsForm);

    angular.element("#settingsModal").on("hidden.bs.modal", function() {

        $scope.settings = {};
        networkAdapters = [];
        showNetworkAdapters = false;
        SuccessService.handleLedSuccess(led);

    });

    return {

        led: led,

        saveSetting: saveSetting,
        getNetworkAdapters: getNetworkAdapters,
        shouldShowNetworkAdapters: shouldShowNetworkAdapters,
        detectNetworkAdapters: detectNetworkAdapters,
        selectNetworkAdapter: selectNetworkAdapter

    };

};

export default SettingsController;
