import DeviceServiceMessages from "../messages/services/device/deviceService";

class DeviceService {

    constructor(resource) {

        this._resource = resource;

    }

    static get _DeviceServiceMessages() {

        return DeviceServiceMessages;

    }

    static get _DevicesUrl() {

        return "/smartcontrol/api/devices";

    }

    getDevices(orderBy, orderDirection) {

        const url = DeviceService._DevicesUrl + "?orderBy=" + orderBy + "&orderDirection=" + orderDirection;
        const resource = this._resource(url);

        return resource.query({});

    }

}

export default DeviceService;
