import ValueUtilities from "../../../utilities/valueUtilities";
import ValidationUtilities from "../../../utilities/validationUtilities";

import AssignContentControllerMessages from "../../../messages/controllers/assign_content/assignContentController";

const AssignContentController = function(

    ErrorService, SuccessService, AlertService, LedService, PopoverService,
    Devices, Content, GroupContent, $timeout, $scope

) {

    // Popover

    const title = "Error";
    const popover = PopoverService.getAlertsPopoverWithPlacementBottom(title);

    ValidationUtilities.isNotNullOrUndefined(

        popover, AssignContentControllerMessages.POPOVER_CAN_NOT_BE_NULL_OR_UNDEFINED

    );

    // Led

    const led = LedService.getGreenOnLed(popover);
    ValidationUtilities.isNotNullOrUndefined(led, AssignContentControllerMessages.LED_CAN_NOT_BE_NULL_OR_UNDEFINED);

    // Content

    let selectedContent = {};

    const loadContent = function() {

        const loadContentMessages = AssignContentControllerMessages.LoadContent;
        const throbber = $scope.setLoading("content", true);

        const successHandler = function(contentList) {

            const successHandlerMessages = loadContentMessages.SuccessHandler;

            ValidationUtilities.isNotNullOrUndefined(

                contentList, successHandlerMessages.CONTENT_LIST_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            throbber.off();
            $scope.contentList = contentList;

            SuccessService.handleLedSuccess(led);

        };

        const failHandler = function() {

            const failHandlerMessages = loadContentMessages.FailHandler;
            throbber.off();

            const message = failHandlerMessages.FAILED_TO_LOAD_CONTENT;

            const alert = AlertService.getDangerAlertWithAlertGlyphicon(message);
            ValidationUtilities.isNotNullOrUndefined(alert, failHandlerMessages.ALERT_CAN_NOT_BE_NULL_OR_UNDEFINED);
            ValidationUtilities.isNotEmpty(alert, failHandlerMessages.ALERT_CAN_NOT_BE_EMPTY);

            ErrorService.handleLedError(led, alert);

        };

        Content.query({}, successHandler, failHandler);

    };

    $scope.getBackgroundColor = function(content) {

        const getBackgroundColorMessages = AssignContentControllerMessages.GetBackgroundColor;
        ValidationUtilities.isNotEmpty(content, getBackgroundColorMessages.CONTENT_CAN_NOT_BE_EMPTY);

        const isContentSelected = !ValueUtilities.isEmpty(selectedContent) && (selectedContent.id === content.id);

        return (isContentSelected) ? "#428bca" : "";

    };

    $scope.assignContent = function(content, sendToFtp) {

        const assignContentMessages = AssignContentControllerMessages.AssignContent;

        ValidationUtilities.isNotEmpty(content, assignContentMessages.CONTENT_CAN_NOT_BE_EMPTY);

        const contentId = content.id;
        ValidationUtilities.isString(contentId, assignContentMessages.CONTENT_ID_HAS_TO_BE_A_STRING);
        ValidationUtilities.isTrue(contentId.length > 0, assignContentMessages.CONTENT_ID_CAN_NOT_BE_EMPTY);

        const throbber = $scope.setLoading("assign-" + contentId, true);
        selectedContent = content;

        const contentTitle = content.title;
        ValidationUtilities.isString(contentTitle, assignContentMessages.CONTENT_TITLE_HAS_TO_BE_A_STRING);

        const assignContentToDevice = function(device) {

            const assignContentToDeviceMessages = assignContentMessages.AssignContentToDevice;

            ValidationUtilities.isNotEmpty(device, assignContentToDeviceMessages.DEVICE_CAN_NOT_BE_EMPTY);

            const deviceId = device.id;

            ValidationUtilities.isPositiveNumber(

                deviceId, assignContentToDeviceMessages.DEVICE_ID_HAS_TO_BE_A_POSITIVE_NUMBER

            );

            const deviceName = device.name;
            const hasDeviceName = !ValueUtilities.isNullOrUndefined(deviceName);

            if (hasDeviceName) {

                ValidationUtilities.isString(

                    deviceName, assignContentToDeviceMessages.DEVICE_NAME_HAS_TO_BE_A_STRING

                );

            }

            const led = $scope.getDeviceLed(deviceId);

            ValidationUtilities.isNotNullOrUndefined(

                led, assignContentToDeviceMessages.LED_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            const parameters = {

                id: deviceId,
                property: "content",
                value: contentId

            };

            const successHandler = function() {

                const successHandlerMessages = assignContentToDeviceMessages.SuccessHandler;
                SuccessService.handleLedSuccess(led);

                const sendDeviceContentToFtp = function() {

                    const sendDeviceContentToFtpMessages = successHandlerMessages.SendDeviceContentToFtp;

                    const parameters = {

                        id: deviceId,
                        type: "content",
                        prefix: "sendToFtp"

                    };

                    const successHandler = function() {

                        SuccessService.handleLedSuccess(led);
                        $scope.checkedDevices[deviceId] = false;

                    };

                    const failHandler = function() {

                        const failHandlerMessages = sendDeviceContentToFtpMessages.FailHandler;

                        const message = failHandlerMessages.getFailedToSendContentToFtpMessage(

                            contentId, contentTitle, deviceId, deviceName

                        );

                        const alert = AlertService.getDangerAlertWithAlertGlyphicon(message);

                        ValidationUtilities.isNotNullOrUndefined(

                            alert, failHandlerMessages.ALERT_CAN_NOT_BE_NULL_OR_UNDEFINED

                        );

                        ValidationUtilities.isNotEmpty(alert, failHandlerMessages.ALERT_CAN_NOT_BE_EMPTY);

                        ErrorService.handleLedError(led, alert);

                    };

                    return Devices.save(parameters, null, successHandler, failHandler);

                };

                if (sendToFtp === true) {

                    sendDeviceContentToFtp();

                } else {

                    $scope.checkedDevices[deviceId] = false;

                }

            };

            const failHandler = function() {

                const failHandlerMessages = assignContentToDeviceMessages.FailHandler;

                const message = failHandlerMessages.getFailedToAssignContentMessage(contentId, contentTitle);
                const alert = AlertService.getDangerAlertWithAlertGlyphicon(message);

                ValidationUtilities.isNotNullOrUndefined(

                    alert, failHandlerMessages.ALERT_CAN_NOT_BE_NULL_OR_UNDEFINED

                );

                ValidationUtilities.isNotEmpty(alert, failHandlerMessages.ALERT_CAN_NOT_BE_EMPTY);

                ErrorService.handleLedError(led, alert);

            };

            return Devices.put(parameters, null, successHandler, failHandler);

        };

        const checkedDevices = $scope.getCheckedDevices();

        ValidationUtilities.isNotNullOrUndefined(

            checkedDevices, assignContentMessages.CHECKED_DEVICES_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        checkedDevices.forEach(assignContentToDevice);

        const assignContentToGroup = function(group) {

            const assignContentToGroupMessages = assignContentMessages.AssignContentToGroup;

            ValidationUtilities.isNotEmpty(group, assignContentToGroupMessages.GROUP_CAN_NOT_BE_EMPTY);

            const groupId = group.id;

            ValidationUtilities.isPositiveNumber(

                groupId, assignContentToGroupMessages.GROUP_ID_HAS_TO_BE_A_POSITIVE_NUMBER

            );

            const groupName = group.name;
            const hasGroupName = !ValueUtilities.isNullOrUndefined(groupName);

            if (hasGroupName) {

                ValidationUtilities.isString(groupName, assignContentToGroupMessages.GROUP_NAME_HAS_TO_BE_A_STRING);

            }

            const led = $scope.getGroupLed(groupId);

            ValidationUtilities.isNotNullOrUndefined(

                led, assignContentToGroupMessages.LED_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            const parameters = {

                groupId: groupId,
                contentId: contentId

            };

            const successHandler = function() {

                const successHandlerMessages = assignContentToGroupMessages.SuccessHandler;
                SuccessService.handleLedSuccess(led);

                const sendGroupContentToFtp = function() {

                    const sendGroupContentToFtpMessages = successHandlerMessages.SendGroupContentToFtp;

                    const parameters = {

                        groupId: groupId,
                        contentId: "sendToFtp"

                    };

                    const successHandler = function() {

                        SuccessService.handleLedSuccess(led);
                        $scope.checkedGroups[groupId] = false;

                    };

                    const failHandler = function() {

                        const failHandlerMessages = sendGroupContentToFtpMessages.FailHandler;

                        const message = failHandlerMessages.getFailedToSendGroupContentToFtpMessage(

                            contentId, contentTitle, groupId, groupName

                        );

                        const alert = AlertService.getDangerAlertWithAlertGlyphicon(message);

                        ValidationUtilities.isNotNullOrUndefined(

                            alert, failHandlerMessages.ALERT_CAN_NOT_BE_NULL_OR_UNDEFINED

                        );

                        ValidationUtilities.isNotEmpty(alert, failHandlerMessages.ALERT_CAN_NOT_BE_EMPTY);

                        ErrorService.handleLedError(led, alert);

                    };

                    GroupContent.save(parameters, null, successHandler, failHandler);

                };

                if (sendToFtp === true) {

                    sendGroupContentToFtp();

                } else {

                    $scope.checkedGroups[groupId] = false;

                }

            };

            const failHandler = function() {

                const failHandlerMessages = assignContentToGroupMessages.FailHandler;

                const message = failHandlerMessages.getFailedToAssignContentMessage(contentId, contentTitle);
                const alert = AlertService.getDangerAlertWithAlertGlyphicon(message);

                ValidationUtilities.isNotNullOrUndefined(

                    alert, failHandlerMessages.ALERT_CAN_NOT_BE_NULL_OR_UNDEFINED

                );

                ValidationUtilities.isNotEmpty(alert, failHandlerMessages.ALERT_CAN_NOT_BE_EMPTY);

                ErrorService.handleLedError(led, alert);

            };

            return GroupContent.put(parameters, null, successHandler, failHandler);

        };

        const checkedGroups = $scope.getCheckedGroups();

        ValidationUtilities.isNotNullOrUndefined(

            checkedGroups, assignContentMessages.CHECKED_GROUPS_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        checkedGroups.forEach(assignContentToGroup);

        throbber.off();
        $scope.hideModal("assignContentModal");

    };

    angular.element("#assignContentModal").on("show.bs.modal", loadContent);

    angular.element("#assignContentModal").on("hidden.bs.modal", function() {

        selectedContent = {};
        $scope.contentList = [];

        SuccessService.handleLedSuccess(led);

    });

    return {

        led: led

    };

};

export default AssignContentController;
