import ValueUtilities from "../utilities/valueUtilities";
import ValidationUtilities from "../utilities/validationUtilities";

import GroupsControllerMessages from "../messages/controllers/groups_controller/groupsController";

const GroupsController = function(

    ErrorService, SuccessService, AlertService, PopoverService, LedService, GroupService, DevicePropertyService,
    Groups, Devices, $scope

) {

    const expandedPanels = {};
    let newNames = [];

    /**
     * Check if panel should be expanded. Keeps group panels open after refreshes for user comfort.
     */
    const shouldExpandPanel = function(groupId) {

        const shouldExpandPanelMessages = GroupsControllerMessages.ShouldExpandPanel;

        ValidationUtilities.isNotNullOrUndefined(

            groupId, shouldExpandPanelMessages.GROUP_ID_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        return expandedPanels["collapseGroup" + groupId] === true;

    };

    const setExpandedPanel = function(panelId, value) {

        const setExpandedPanelMessages = GroupsControllerMessages.SetExpandedPanel;

        ValidationUtilities.isNotNullOrUndefined(

            panelId, setExpandedPanelMessages.PANEL_ID_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        ValidationUtilities.isBoolean(value, setExpandedPanelMessages.VALUE_HAS_TO_BE_A_BOOLEAN);

        expandedPanels[panelId] = value;

    };

    const groupPanels = angular.element("#groupPanels");

    groupPanels.on("shown.bs.collapse", function(e) {

        const id = e.target.id;
        setExpandedPanel(id, true);

    });

    groupPanels.on("hidden.bs.collapse", function(e) {

        const id = e.target.id;
        setExpandedPanel(id, false);

    });

    /**
     * Disable polling when user tries to rename group.
     */
    groupPanels.focusin(function(e) {

        const groupPanelsFocusInMessages = GroupsControllerMessages.GroupPanelsFocusIn;

        const polling = $scope.polling;
        ValidationUtilities.isNotEmpty(polling, groupPanelsFocusInMessages.POLLING_CAN_NOT_BE_EMPTY);

        if (e.target.classList.contains("renameGroup")) {

            polling.setOverride(true);

        }

    });

    /**
     * Restore polling to last state when user finishes renaming a group.
     */
    groupPanels.focusout(function(e) {

        const groupPanelsFocusOutMessages = GroupsControllerMessages.GroupPanelsFocusOut;

        const polling = $scope.polling;
        ValidationUtilities.isNotEmpty(polling, groupPanelsFocusOutMessages.POLLING_CAN_NOT_BE_EMPTY);

        if (e.target.classList.contains("renameGroup")) {

            polling.setOverride(false);
            polling.update();

        }

    });

    const renameGroup = function(group) {

        const renameGroupMessages = GroupsControllerMessages.RenameGroup;
        ValidationUtilities.isNotEmpty(group, renameGroupMessages.GROUP_CAN_NOT_BE_EMPTY);

        const groupId = group.id;
        ValidationUtilities.isPositiveNumber(groupId, renameGroupMessages.GROUP_ID_HAS_TO_BE_A_POSITIVE_NUMBER);

        const groupCopy = angular.copy(group);
        groupCopy.name = newNames[groupId];

        const led = $scope.getGroupLed(groupId);

        ValidationUtilities.isNotNullOrUndefined(

            led, renameGroupMessages.LED_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        const parameters = {

            id: groupId

        };

        const successHandler = function() {

            const successHandlerMessages = renameGroupMessages.SuccessHandler;

            SuccessService.handleLedSuccess(led);

            const polling = $scope.polling;
            ValidationUtilities.isNotEmpty(polling, successHandlerMessages.POLLING_CAN_NOT_BE_EMPTY);

            polling.update();

        };

        const failHandler = function() {

            const failHandlerMessages = renameGroupMessages.FailHandler;

            const message = failHandlerMessages.FAILED_TO_RENAME_GROUP;
            const alert = AlertService.getDangerAlertWithAlertGlyphicon(message);

            ValidationUtilities.isNotNullOrUndefined(

                alert, failHandlerMessages.ALERT_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            ValidationUtilities.isNotEmpty(alert, failHandlerMessages.ALERT_CAN_NOT_BE_EMPTY);

            ErrorService.handleLedError(led, alert);

        };

        Groups.put(parameters, groupCopy, successHandler, failHandler);

    };

    const removeDevice = function(device, group) {

        const removeDeviceMessages = GroupsControllerMessages.RemoveDevice;

        ValidationUtilities.isNotEmpty(device, removeDeviceMessages.DEVICE_CAN_NOT_BE_EMPTY);
        ValidationUtilities.isNotEmpty(group, removeDeviceMessages.GROUP_CAN_NOT_BE_EMPTY);

        const devices = group.devices;

        ValidationUtilities.isNotNullOrUndefined(

            devices, removeDeviceMessages.GROUP_DEVICES_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        const groupCopy = angular.copy(group);
        const deviceIndex = devices.indexOf(device);
        groupCopy.devices.splice(deviceIndex, 1);

        const groupId = group.id;
        ValidationUtilities.isPositiveNumber(groupId, removeDeviceMessages.GROUP_ID_HAS_TO_BE_A_POSITIVE_NUMBER);

        const led = $scope.getGroupLed(groupId);
        ValidationUtilities.isNotNullOrUndefined(led, removeDeviceMessages.LED_CAN_NOT_BE_NULL_OR_UNDEFINED);

        const parameters = {

            id: groupId

        };

        const successHandler = function() {

            const successHandlerMessages = removeDeviceMessages.SuccessHandler;

            SuccessService.handleLedSuccess(led);

            const polling = $scope.polling;
            ValidationUtilities.isNotEmpty(polling, successHandlerMessages.POLLING_CAN_NOT_BE_EMPTY);

            polling.update();

        };

        const failHandler = function() {

            const failHandlerMessages = removeDeviceMessages.FailHandler;

            const deviceId = device.id;

            ValidationUtilities.isPositiveNumber(

                deviceId, failHandlerMessages.DEVICE_ID_HAS_TO_BE_A_POSITIVE_NUMBER

            );

            const deviceName = device.name;
            const hasDeviceName = !ValueUtilities.isNullOrUndefined(deviceName);

            if (hasDeviceName) {

                ValidationUtilities.isString(

                    deviceName, failHandlerMessages.DEVICE_NAME_HAS_TO_BE_A_STRING

                );

            }

            const message = failHandlerMessages.getFailedToRemoveDeviceFromGroupMessage(deviceId, deviceName);
            const alert = AlertService.getDangerAlertWithAlertGlyphicon(message);

            ValidationUtilities.isNotNullOrUndefined(

                alert, failHandlerMessages.ALERT_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            ValidationUtilities.isNotEmpty(alert, failHandlerMessages.ALERT_CAN_NOT_BE_EMPTY);

            ErrorService.handleLedError(led, alert);

        };

        Groups.put(parameters, groupCopy, successHandler, failHandler);

    };

    const deleteGroup = function(group) {

        const deleteGroupMessages = GroupsControllerMessages.DeleteGroup;
        ValidationUtilities.isNotEmpty(group, deleteGroupMessages.GROUP_CAN_NOT_BE_EMPTY);

        const groupId = group.id;
        ValidationUtilities.isPositiveNumber(groupId, deleteGroupMessages.GROUP_ID_HAS_TO_BE_A_POSITIVE_NUMBER);

        const led = $scope.getGroupLed(groupId);
        ValidationUtilities.isNotNullOrUndefined(led, deleteGroupMessages.LED_CAN_NOT_BE_NULL_OR_UNDEFINED);

        const parameters = {

            id: groupId

        };

        const successHandler = function() {

            const successHandlerMessages = deleteGroupMessages.SuccessHandler;

            SuccessService.handleLedSuccess(led);

            const polling = $scope.polling;
            ValidationUtilities.isNotEmpty(polling, successHandlerMessages.POLLING_CAN_NOT_BE_EMPTY);

            polling.update();

        };

        const failHandler = function() {

            const failHandlerMessages = deleteGroupMessages.FailHandler;

            const message = failHandlerMessages.FAILED_TO_DELETE_GROUP;
            const alert = AlertService.getDangerAlertWithAlertGlyphicon(message);

            ValidationUtilities.isNotNullOrUndefined(

                alert, failHandlerMessages.ALERT_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            ValidationUtilities.isNotEmpty(alert, failHandlerMessages.ALERT_CAN_NOT_BE_EMPTY);

            ErrorService.handleLedError(led, alert);

        };

        Groups.delete(parameters, successHandler, failHandler);

    };

    /**
     * HTTP GETs the settings models for the given devices one by one asynchronously. Calls success when done and fail
     * when any model fails to load.
     */
    const getModels = function(index, devices, models, success, fail) {

        const getModelsMessages = GroupsControllerMessages.GetModels;

        const validateParameters = function() {

            const validateParametersMessages = getModelsMessages.ValidateParameters;

            ValidationUtilities.isPositiveNumber(index, validateParametersMessages.INDEX_HAS_TO_BE_A_POSITIVE_NUMBER);
            ValidationUtilities.isNotEmpty(devices, validateParametersMessages.DEVICES_CAN_NOT_BE_EMPTY);
            ValidationUtilities.isNotNullOrUndefined(models, validateParametersMessages.MODELS_CAN_NOT_BE_NULL_OR_UNDEFINED);

        };

        validateParameters();

        function recursive(index, devices, models, success, fail) {

            const recursiveMessages = getModelsMessages.Recursive;
            validateParameters();

            if (index < devices.length) {

                const device = devices[index];
                ValidationUtilities.isNotEmpty(device, recursiveMessages.DEVICE_CAN_NOT_BE_EMPTY);

                const parameters = {

                    id: device.id,
                    type: "settings"

                };

                const successHandler = function(model) {

                    const successHandlerMessages = recursiveMessages.SuccessHandler;
                    ValidationUtilities.isNotEmpty(model, successHandlerMessages.MODEL_CAN_NOT_BE_EMPTY);

                    model.id = device.id;
                    model.name = device.name;

                    model.volumeLimits = {

                        minimum: 0,
                        maximum: 100

                    };

                    models.push(model);
                    recursive(++index, devices, models, success, fail);

                };

                Devices.get(parameters, successHandler, fail);

            } else {

                success(models);

            }

        }

        recursive(index, devices, models, success, fail);

    };

    /**
     * Returns pseudo-device that contains all deep-merged properties of all given devices where all values are
     * deep-equal. Incoherent values are set to null. All sub-properties are recreated (with values set to null or the
     * globally equal value).
     */
    const mergeSettings = function(mergedSettings, devices) {

        const mergeSettingsMessages = GroupsControllerMessages.MergeSettings;

        ValidationUtilities.isNotNullOrUndefined(

            mergedSettings, mergeSettingsMessages.MERGED_SETTINGS_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        ValidationUtilities.isNotEmpty(devices, mergeSettingsMessages.DEVICES_CAN_NOT_BE_EMPTY);

        function recursive(mergedSettings, elements, properties) {

            const recursiveMessages = mergeSettingsMessages.Recursive;

            ValidationUtilities.isNotNullOrUndefined(

                mergedSettings, recursiveMessages.MERGED_SETTINGS_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            ValidationUtilities.isNotNullOrUndefined(

                elements, recursiveMessages.ELEMENTS_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            ValidationUtilities.isNotNullOrUndefined(

                properties, recursiveMessages.PROPERTIES_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            const mergeElementProperty = function(property) {

                const mergeElementPropertyMessages = recursiveMessages.MergeElementProperty;

                ValidationUtilities.isNotNullOrUndefined(

                    property, mergeElementPropertyMessages.PROPERTY_CAN_NOT_BE_NULL_OR_UNDEFINED

                );

                const isElementPropertyNullOrUndefined = function(element) {

                    const isElementPropertyNullOrUndefinedMessages =
                        mergeElementPropertyMessages.IsElementPropertyNullOrUndefined;

                    ValidationUtilities.isNotNullOrUndefined(

                        element, isElementPropertyNullOrUndefinedMessages.ELEMENT_CAN_NOT_BE_NULL_OR_UNDEFINED

                    );

                    return ValueUtilities.isNullOrUndefined(element[property]);

                };

                const isAnyElementPropertyNullOrUndefined = elements.some(isElementPropertyNullOrUndefined);

                if (isAnyElementPropertyNullOrUndefined) {

                    mergedSettings[property] = null;

                } else {

                    const referenceProperty = elements[0][property];

                    if (!Array.isArray(referenceProperty) && typeof(referenceProperty) === "object") {

                        mergedSettings[property] = {};

                        const getElementProperty = function(element) {

                            const getElementPropertyMessages = mergeElementPropertyMessages.GetElementProperty;

                            ValidationUtilities.isNotNullOrUndefined(

                                element, getElementPropertyMessages.ELEMENT_CAN_NOT_BE_NULL_OR_UNDEFINED

                            );

                            return element[property];

                        };

                        const elementProperties = elements.map(getElementProperty);
                        const referenceProperties = Object.keys(referenceProperty);

                        recursive(mergedSettings[property], elementProperties, referenceProperties);

                    } else {

                        let isElementPropertyNotEqual;

                        if (Array.isArray(referenceProperty)) {

                            isElementPropertyNotEqual = function(element) {

                                ValidationUtilities.isNotNullOrUndefined(

                                    element, mergeElementPropertyMessages.ELEMENT_CAN_NOT_BE_NULL_OR_UNDEFINED

                                );

                                return !ArrayUtilities.equals(referenceProperty, element[property]);

                            };

                        } else {

                            isElementPropertyNotEqual = function(element) {

                                ValidationUtilities.isNotNullOrUndefined(

                                    element, mergeElementPropertyMessages.ELEMENT_CAN_NOT_BE_NULL_OR_UNDEFINED

                                );

                                return referenceProperty !== element[property];

                            };

                        }

                        const isAnyElementPropertyNotEqual = elements.some(isElementPropertyNotEqual);

                        mergedSettings[property] = isAnyElementPropertyNotEqual ? null : referenceProperty;

                    }

                }

            };

            properties.forEach(mergeElementProperty);

            return mergedSettings;

        }

        const settingsProperties = DevicePropertyService.getSettingsProperties();

        ValidationUtilities.isNotNullOrUndefined(

            settingsProperties, mergeSettingsMessages.PROPERTIES_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        return recursive(mergedSettings, devices, settingsProperties);

    };

    /**
     * Merges deviceLimits of all given devices into a new object where minimums are set to the highest value found and
     * maximums are set to the lowest value found.
     */
    const mergeLimits = function(mergedSettings, devices) {

        const mergeLimitsMessages = GroupsControllerMessages.MergeLimits;

        ValidationUtilities.isNotNullOrUndefined(

            mergedSettings, mergeLimitsMessages.MERGED_SETTINGS_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        ValidationUtilities.isNotNullOrUndefined(devices, mergeLimitsMessages.DEVICES_CAN_NOT_BE_NULL_OR_UNDEFINED);

        function recursive(mergedSettings, elements, properties) {

            const recursiveMessages = mergeLimitsMessages.Recursive;

            ValidationUtilities.isNotNullOrUndefined(

                mergedSettings, recursiveMessages.MERGED_SETTINGS_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            ValidationUtilities.isNotNullOrUndefined(

                elements, recursiveMessages.ELEMENTS_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            ValidationUtilities.isNotNullOrUndefined(

                properties, recursiveMessages.PROPERTIES_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            const mergeElementProperty = function(property) {

                const mergeElementPropertyMessages = recursiveMessages.MergeElementProperty;

                ValidationUtilities.isNotNullOrUndefined(

                    property, mergeElementPropertyMessages.PROPERTY_CAN_NOT_BE_NULL_OR_UNDEFINED

                );

                const referenceProperty = elements[0][property];

                ValidationUtilities.isNotNullOrUndefined(

                    property, mergeElementPropertyMessages.REFERENCE_PROPERTY_CAN_NOT_BE_NULL_OR_UNDEFINED

                );

                let minimum = referenceProperty.minimum;
                let maximum = referenceProperty.maximum;
                let step = referenceProperty.step;

                if (!ValueUtilities.isNullOrUndefined(minimum) && !ValueUtilities.isNullOrUndefined(maximum)) {

                    if (!ValueUtilities.isNullOrUndefined(step)) {
                        const loadMinimumAndMaximum = function(element) {

                            const loadMinimumAndMaximumMessages = mergeElementPropertyMessages.LoadMinimumAndMaximum;

                            ValidationUtilities.isNotNullOrUndefined(

                                element, loadMinimumAndMaximumMessages.ELEMENT_CAN_NOT_BE_NULL_OR_UNDEFINED

                            );

                            minimum = Math.max(minimum, element[property].minimum);
                            maximum = Math.min(maximum, element[property].maximum);
                            step = element[property].step;

                        };

                        elements.forEach(loadMinimumAndMaximum);

                        mergedSettings[property] = {

                            minimum: minimum,
                            maximum: maximum,
                            step: step

                        };

                    } else {
                        const loadMinimumAndMaximum = function(element) {

                            const loadMinimumAndMaximumMessages = mergeElementPropertyMessages.LoadMinimumAndMaximum;

                            ValidationUtilities.isNotNullOrUndefined(

                                element, loadMinimumAndMaximumMessages.ELEMENT_CAN_NOT_BE_NULL_OR_UNDEFINED

                            );

                            minimum = Math.max(minimum, element[property].minimum);
                            maximum = Math.min(maximum, element[property].maximum);

                        };

                        elements.forEach(loadMinimumAndMaximum);

                        mergedSettings[property] = {

                            minimum: minimum,
                            maximum: maximum

                        };
                    }
                } else {

                    const enumClass = referenceProperty.enumClass;
                    const values = referenceProperty.values;

                    if (!ValueUtilities.isNullOrUndefined(enumClass) && !ValueUtilities.isNullOrUndefined(values)) {

                        mergedSettings[property] = {

                            enumClass: enumClass,
                            values: values

                        };

                    } else {

                        mergedSettings[property] = {};

                        const getElementProperty = function(element) {

                            const getElementPropertyMessages = mergeElementPropertyMessages.GetElementProperty;

                            ValidationUtilities.isNotNullOrUndefined(

                                element, getElementPropertyMessages.ELEMENT_CAN_NOT_BE_NULL_OR_UNDEFINED

                            );

                            return element[property];

                        };

                        const elementProperties = elements.map(getElementProperty);
                        const referenceProperties = Object.keys(referenceProperty);

                        mergedSettings[property] = recursive(mergedSettings[property], elementProperties, referenceProperties);

                    }

                }

            };

            properties.forEach(mergeElementProperty);

            return mergedSettings;

        }

        mergedSettings.deviceLimits = {};

        const getDeviceLimits = function(device) {

            const getDeviceLimitsMessages = mergeLimitsMessages.GetDeviceLimits;
            ValidationUtilities.isNotNullOrUndefined(device, getDeviceLimitsMessages.DEVICE_CAN_NOT_BE_EMPTY);

            return device.deviceLimits;

        };

        const devicesDeviceLimits = devices.map(getDeviceLimits);
        const deviceLimit = devicesDeviceLimits[0];
        const deviceLimitsProperties = Object.keys(deviceLimit);

        return recursive(mergedSettings.deviceLimits, devicesDeviceLimits, deviceLimitsProperties);

    };

    const mergeDevices = function(devices) {

        const mergeDevicesMessages = GroupsControllerMessages.MergeDevices;
        ValidationUtilities.isNotEmpty(devices, mergeDevicesMessages.DEVICES_CAN_NOT_BE_EMPTY);

        let mergedSettings = {};

        mergedSettings = mergeSettings(mergedSettings, devices);
        mergedSettings.deviceLimits = mergeLimits(mergedSettings, devices);

        return mergedSettings;

    };

    const groupSettingsModal = function(group) {

        const groupSettingsModalMessages = GroupsControllerMessages.GroupSettingsModal;
        ValidationUtilities.isNotEmpty(group, groupSettingsModalMessages.GROUP_CAN_NOT_BE_EMPTY);

        const groupId = group.id;
        ValidationUtilities.isPositiveNumber(groupId, groupSettingsModalMessages.GROUP_ID_HAS_TO_BE_A_POSITIVE_NUMBER);

        const throbber = $scope.setLoading("groupSettings-" + groupId, true);
        $scope.setCurrentGroup(group);

        const led = $scope.getGroupLed(groupId);
        ValidationUtilities.isNotNullOrUndefined(led, groupSettingsModalMessages.LED_CAN_NOT_BE_NULL_OR_UNDEFINED);

        const successHandler = function(models) {

            const successHandlerMessages = groupSettingsModalMessages.SuccessHandler;
            ValidationUtilities.isNotEmpty(models, successHandlerMessages.MODELS_CAN_NOT_BE_EMPTY);

            $scope.setCurrentGroupDevices(models);

            const pseudoDevice = mergeDevices(models);
            $scope.setCurrentDevice(pseudoDevice);

            SuccessService.handleLedSuccess(led);

            throbber.off();
            $scope.showModal("deviceSettingsModal");

        };

        const failHandler = function() {

            const failHandlerMessages = groupSettingsModalMessages.FailHandler;
            throbber.off();

            const message = failHandlerMessages.FAILED_TO_LOAD_GROUP_SETTINGS;
            const alert = AlertService.getDangerAlertWithAlertGlyphicon(message);

            ValidationUtilities.isNotNullOrUndefined(

                alert, failHandlerMessages.ALERT_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            ValidationUtilities.isNotEmpty(alert, failHandlerMessages.ALERT_CAN_NOT_BE_EMPTY);

            ErrorService.handleLedError(led, alert);

        };

        getModels(0, group.devices, [], successHandler, failHandler);

    };

    const addDevice = function(group, device) {

        const addDeviceMessages = GroupsControllerMessages.AddDevice;

        ValidationUtilities.isNotNullOrUndefined(group, addDeviceMessages.GROUP_CAN_NOT_BE_NULL_OR_UNDEFINED);
        ValidationUtilities.isNotNullOrUndefined(device, addDeviceMessages.DEVICE_CAN_NOT_BE_NULL_OR_UNDEFINED);

        const groupId = group.id;
        ValidationUtilities.isPositiveNumber(groupId, addDeviceMessages.GROUP_ID_HAS_TO_BE_A_POSITIVE_NUMBER);

        const parameters = {

            id: groupId

        };

        const deviceId = device.id;
        ValidationUtilities.isPositiveNumber(deviceId, addDeviceMessages.DEVICE_ID_HAS_TO_BE_A_POSITIVE_NUMBER);

        const ipDestination = device.ipDestination;
        ValidationUtilities.isNotNullOrUndefined(ipDestination, addDeviceMessages.IP_DESTINATION_CAN_NOT_BE_EMPTY);

        const deviceToAdd = {

            id: deviceId,
            ipDestination: ipDestination

        };

        const groupCopy = angular.copy(group);

        const devices = groupCopy.devices;
        ValidationUtilities.isNotNullOrUndefined(devices, addDeviceMessages.DEVICES_CAN_NOT_BE_NULL_OR_UNDEFINED);
        ValidationUtilities.isNotEmpty(devices, addDeviceMessages.DEVICES_CAN_NOT_BE_EMPTY);

        devices.push(deviceToAdd);

        const led = $scope.getGroupLed(groupId);
        ValidationUtilities.isNotNullOrUndefined(led, addDeviceMessages.LED_CAN_NOT_BE_NULL_OR_UNDEFINED);

        const successHandler = function() {

            const successHandlerMessages = addDeviceMessages.SuccessHandler;

            SuccessService.handleLedSuccess(led);

            const polling = $scope.polling;
            ValidationUtilities.isNotEmpty(polling, successHandlerMessages.POLLING_CAN_NOT_BE_EMPTY);

            polling.update();

        };

        const failHandler = function() {

            const failHandlerMessages = addDeviceMessages.FailHandler;

            const deviceName = device.name;
            const hasDeviceName = !ValueUtilities.isNullOrUndefined(deviceName);

            if (hasDeviceName) {

                ValidationUtilities.isString(

                    deviceName, failHandlerMessages.DEVICE_NAME_HAS_TO_BE_A_STRING

                );

            }

            const message = failHandlerMessages.getFailedToAddDeviceToGroupMessage(deviceId, deviceName);
            const alert = AlertService.getDangerAlertWithAlertGlyphicon(message);

            ValidationUtilities.isNotNullOrUndefined(

                alert, failHandlerMessages.ALERT_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            ValidationUtilities.isNotEmpty(alert, failHandlerMessages.ALERT_CAN_NOT_BE_EMPTY);

            ErrorService.handleLedError(led, alert);

        };

        Groups.put(parameters, groupCopy, successHandler, failHandler);

    };

    const getAddDeviceOptionsLabel = function(device) {

        const getAddDeviceOptionsLabelMessages = GroupsControllerMessages.GetAddDeviceOptionsLabel;

        ValidationUtilities.isNotNullOrUndefined(

            device, getAddDeviceOptionsLabelMessages.DEVICE_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        const deviceId = device.id;

        ValidationUtilities.isPositiveNumber(

            deviceId, getAddDeviceOptionsLabelMessages.DEVICE_ID_HAS_TO_BE_A_POSITIVE_NUMBER

        );

        let label = "" + deviceId;

        const deviceName = device.name;
        const hasDeviceName = !ValueUtilities.isNullOrUndefined(deviceName);

        if (hasDeviceName) {

            ValidationUtilities.isString(

                deviceName, getAddDeviceOptionsLabelMessages.DEVICE_NAME_HAS_TO_BE_A_STRING

            );

            label += " - " + deviceName;

        }

        const modelNumber = device.modelNumber;
        const hasModelNumber = !ValueUtilities.isNullOrUndefined(modelNumber);

        if (hasModelNumber) {

            ValidationUtilities.isString(

                modelNumber, getAddDeviceOptionsLabelMessages.MODEL_NUMBER_HAS_TO_BE_A_STRING

            );

            label += " - " + modelNumber;

        }

        return label;

    };

    const getSortGlyphiconClass = function(group, column) {

        // const getSortGlyphiconClassMessages = DevicesControllerMessages.GetSortGlyphiconClass;

        const groupId = group.id;
        ValidationUtilities.isPositiveNumber(groupId, "Group id has to be a positive number.");

        ValidationUtilities.isString(

            column, "getSortGlyphiconClassMessages.COLUMN_HAS_TO_BE_A_STRING"

        );

        ValidationUtilities.isTrue(column.length > 0, "getSortGlyphiconClassMessages.COLUMN_CAN_NOT_BE_EMPTY");

        const sorting = $scope.getGroupDevicesSorting(groupId);

        const sortColumn = sorting.column;
        ValidationUtilities.isString(sortColumn, "getSortGlyphiconClassMessages.SORT_COLUMN_HAS_TO_BE_A_STRING");
        ValidationUtilities.isTrue(sortColumn.length > 0, "getSortGlyphiconClassMessages.SORT_COLUMN_CAN_NOT_BE_EMPTY");

        if (column === sortColumn) {

            const direction = sorting.direction;
            ValidationUtilities.isString(direction, "getSortGlyphiconClassMessages.DIRECTION_HAS_TO_BE_A_STRING");
            ValidationUtilities.isTrue(direction.length > 0, "getSortGlyphiconClassMessages.DIRECTION_CAN_NOT_BE_EMPTY");

            if (direction === "desc") {

                return "glyphicon-sort-by-alphabet-alt";

            } else {

                return "glyphicon-sort-by-alphabet";

            }

        }

        return "";

    };

    return {

        newNames: newNames,

        shouldExpandPanel: shouldExpandPanel,
        renameGroup: renameGroup,
        removeDevice: removeDevice,
        deleteGroup: deleteGroup,
        groupSettingsModal: groupSettingsModal,
        addDevice: addDevice,
        getAddDeviceOptionsLabel: getAddDeviceOptionsLabel,
        getSortGlyphiconClass: getSortGlyphiconClass

    };

};

export default GroupsController;
