const FileDirective = function() {

    const link = function(scope, element, attributes, ngModel) {

        const change = function(event) {

            const files = event.target.files;
            const file = files[0];

            ngModel.$setViewValue(file);
            scope.$apply();

        };

        element.bind("change", change);

    };

    return {

        require: "ngModel",
        restrict: "A",
        link: link

    };

};

export default FileDirective;
