import RootController from "../controllers/rootController";
import NavigationBarController from "../controllers/navigationBarController";
import FooterController from "../controllers/footerController";
import OverviewController from "../controllers/overviewController";
import DevicesController from "../controllers/devicesController";
import GroupsController from "../controllers/groupsController";
import LedDevicesController from "../controllers/ledDevicesController";

import AddDeviceController from "../controllers/modals/addDeviceController";
import CreateGroupController from "../controllers/modals/createGroupController";
import DetectDevicesController from "../controllers/modals/detectDevicesController";
import DeviceInfoController from "../controllers/modals/deviceInfoController";
import DeviceSettingsController from "../controllers/modals/deviceSettingsController";
import EditDeviceController from "../controllers/modals/editDeviceController";
import SettingsController from "../controllers/modals/settingsController";

import AssignContentController from "../controllers/modals/content/assignContentController";
import DownloadContentController from "../controllers/modals/content/downloadContentController";

import ImportDevicesController from "../controllers/modals/importDevicesController";

const app = angular.module("smartcontrol");

app.controller(

    "RootController",

    [

        "$rootScope",

        RootController

    ]

);

app.controller(

    "NavigationBarController",

    [

        "NavigationService",
        "$sce",

        NavigationBarController

    ]

);

app.controller(

    "FooterController",

    [

        "VersionService",

        FooterController

    ]

);

app.controller(

    "OverviewController",

    [

        "LedService", "PopoverService", "DeviceService", "GroupService",
        "PopoverPlacement",
        "Groups",
        "$scope", "$cookies", "$location", "$interval", "$timeout",

        OverviewController

    ]

);

app.controller(

    "DevicesController",

    [

        "ErrorService", "SuccessService", "AlertService", "LedService", "PopoverService",
        "DevicePropertyService", "DeviceSettingsService", "DeviceService",
        "Devices", "DeviceActions", "DevicesData",
        "$scope", "$window", "$parse", "$interval", "$timeout",

        DevicesController

    ]

);

app.controller(

    "GroupsController",

    [

        "ErrorService", "SuccessService", "AlertService", "PopoverService", "LedService", "GroupService",
        "DevicePropertyService",
        "Groups", "Devices",
        "$scope",

        GroupsController

    ]

);

app.controller(

    "LedDevicesController",

    [

        "LedDeviceSettingsService",

        LedDevicesController

    ]

);

app.controller(

    "DeviceSettingsController",

    [

        "ErrorService", "SuccessService", "AlertService", "LedService",
        "PopoverService", "DevicePropertyService", "DeviceSettingsService",
        "Devices", "Groups",
        "gridsterConfig",
        "$scope", "$timeout", "$parse",

        DeviceSettingsController

    ]

);

app.controller(

    "EditDeviceController",

    [

        "ErrorService", "SuccessService", "AlertService", "PopoverService", "LedService", "DevicePropertyService",
        "$scope", "$timeout",

        EditDeviceController

    ]

);

app.controller(

    "SettingsController",

    [

        "ErrorService", "SuccessService", "AlertService", "LedService", "PopoverService",
        "Settings",
        "$scope", "$timeout",

        SettingsController

    ]

);

app.controller(

    "AddDeviceController",

    [

        "ErrorService", "SuccessService", "AlertService", "LedService", "PopoverService",
        "Devices", "Settings",
        "$scope",

        AddDeviceController

    ]

);

app.controller(

    "CreateGroupController",

    [

        "ErrorService", "SuccessService", "AlertService", "LedService", "PopoverService",
        "Groups",
        "$scope",

        CreateGroupController

    ]

);

app.controller(

    "DetectDevicesController",

    [

        "ErrorService", "SuccessService" ,"LedService", "AlertService", "PopoverService",
        "DeviceActions", "Settings",
        "$scope", "$timeout",

        DetectDevicesController

    ]

);

app.controller(

    "DeviceInfoController",

    [

        "ErrorService", "SuccessService", "LedService", "PopoverService", "AlertService",
        "Devices", "$scope",

        DeviceInfoController

    ]

);

app.controller(

    "AssignContentController",

    [

        "ErrorService", "SuccessService", "AlertService", "LedService", "PopoverService",
        "Devices", "Content", "GroupContent",
        "$timeout", "$scope",

        AssignContentController

    ]

);

app.controller(

    "DownloadContentController",

    [

        "ErrorService", "SuccessService", "AlertService",
        "Devices",
        "$scope", "$window",

        DownloadContentController

    ]

);

app.controller(

    "ImportDevicesController",

    [

        "PopoverService", "LedService", "ErrorService", "SuccessService", "AlertService",
        "DeviceActions",
        "$scope",

        ImportDevicesController

    ]

);
