import ValueUtilities from "../../utilities/valueUtilities";
import ValidationUtilities from "../../utilities/validationUtilities";
import ArrayUtilities from "../../utilities/arrayUtilities";

import ImportDevicesControllerMessages from "../../messages/controllers/import_devices/importDevicesController";

const ImportDevicesController = function(

    PopoverService, LedService, ErrorService, SuccessService, AlertService, DeviceActions, $scope

) {

    // Popover

    const title = "Error";
    const popover = PopoverService.getAlertsPopoverWithPlacementBottomLeft(title);

    ValidationUtilities.isNotNullOrUndefined(

        popover, ImportDevicesControllerMessages.POPOVER_CAN_NOT_BE_NULL_OR_UNDEFINED

    );

    // Led

    const led = LedService.getGreenOnLed(popover);
    ValidationUtilities.isNotNullOrUndefined(led, ImportDevicesControllerMessages.LED_CAN_NOT_BE_NULL_OR_UNDEFINED);

    // Devices

    let importItems = [];

    const getImportItems = function() {

        return importItems;

    };

    const hasClass = function(importItem, clazz) {

        const hasClassMessages = ImportDevicesControllerMessages.HasClass;

        ValidationUtilities.isNotNullOrUndefined(

            importItem, hasClassMessages.IMPORT_ITEM_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        ValidationUtilities.isString(clazz, hasClassMessages.CLAZZ_HAS_TO_BE_A_STRING);

        const importItemClass = importItem["@class"];

        return importItemClass === clazz;

    };

    const isDevice = function(importItem) {

        return hasClass(importItem, "device");

    };

    const isGroup = function(importItem) {

        return hasClass(importItem, "group");

    };

    const getDevices = function() {

        return importItems.filter(isDevice);

    };

    const getGroups = function() {

        return importItems.filter(isGroup);

    };

    const loadImportItems = function(file) {

        const loadImportItemsMessages = ImportDevicesControllerMessages.LoadImportItems;

        const hasFile = !ValueUtilities.isNullOrUndefined(file);

        if (!hasFile) {

            importItems = [];
            return;

        }

        const fileReader = new FileReader();

        fileReader.onload = function(e) {

            const fileReaderOnloadMessages = loadImportItemsMessages.FileReaderOnload;

            const importItemsJson = e.target.result;
            importItems = JSON.parse(importItemsJson);
            const groups = getGroups();

            const checkGroupBinding = function(group) {

                const checkGroupBindingMessages = fileReaderOnloadMessages.CheckGroupBinding;

                ValidationUtilities.isNotNullOrUndefined(

                    group, checkGroupBindingMessages.GROUP_CAN_NOT_BE_NULL_OR_UNDEFINED

                );

                const devices = getDevices();
                const groupDevices = group.devices;

                const checkDeviceBinding = function(groupDevice) {

                    const checkDeviceBindingMessages = checkGroupBindingMessages.CheckDeviceBinding;

                    ValidationUtilities.isNotNullOrUndefined(

                        groupDevice, checkDeviceBindingMessages.GROUP_DEVICE_CAN_NOT_BE_NULL_OR_UNDEFINED

                    );

                    const serialCode = groupDevice.serialCode;
                    const ipDestination = groupDevice.ipDestination;

                    const checkDevice = function(device) {

                        const checkDeviceMessages = checkDeviceBindingMessages.CheckDevice;

                        ValidationUtilities.isNotNullOrUndefined(

                            device, checkDeviceMessages.DEVICE_CAN_NOT_BE_NULL_OR_UNDEFINED

                        );

                        const serialCodeToCheck = device.serialCode;
                        const hasSerialCode = ValueUtilities.isString(serialCodeToCheck) && (serialCodeToCheck.length > 0);

                        if (hasSerialCode) {

                            return serialCodeToCheck === serialCode;

                        }

                        const ipDestinationToCheck = device.ipDestination;

                        return angular.equals(ipDestinationToCheck, ipDestination);

                    };

                    const foundDevice = devices.find(checkDevice);
                    const hasFoundDevice = (foundDevice !== undefined);

                    if (hasFoundDevice) {

                        const index = groupDevices.indexOf(groupDevice);
                        groupDevices[index] = foundDevice;

                    }

                };

                groupDevices.forEach(checkDeviceBinding);

            };

            groups.forEach(checkGroupBinding);

            SuccessService.handleLedSuccess(led);
            $scope.$apply();

        };

        fileReader.readAsText(file);

    };

    const isImportTrue = function(importItem) {

        const isImportTrueMessages = ImportDevicesControllerMessages.IsImportTrue;

        ValidationUtilities.isNotNullOrUndefined(

            importItem, isImportTrueMessages.IMPORT_ITEM_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        return importItem.import === true;

    };

    const isAnyImportItemSelected = function() {

        return importItems.some(isImportTrue);

    };

    const importDevices = function() {

        const importDevicesMessages = ImportDevicesControllerMessages.ImportDevices;

        ValidationUtilities.isNotNullOrUndefined(

            importItems, importDevicesMessages.DEVICES_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        const imports = importItems.filter(isImportTrue);

        const parameters = {

            action: "import"

        };

        const successHandler = function(importResultViewModelList) {

            const successHandlerMessages = importDevicesMessages.SuccessHandler;

            ValidationUtilities.isNotNullOrUndefined(

                importResultViewModelList,
                successHandlerMessages.IMPORT_RESULT_VIEW_MODEL_LIST_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            ValidationUtilities.isTrue(

                !ArrayUtilities.isEmpty(importResultViewModelList),
                successHandlerMessages.IMPORT_RESULT_VIEW_MODEL_LIST_CAN_NOT_BE_EMPTY

            );

            const isResultSuccess = function(importResultViewModel) {

                const isResultSuccessMessages = successHandlerMessages.IsResultSuccess;

                ValidationUtilities.isNotNullOrUndefined(

                    importResultViewModel,
                    isResultSuccessMessages.IMPORT_RESULT_VIEW_MODEL_CAN_NOT_BE_NULL_OR_UNDEFINED

                );

                const result = importResultViewModel.result;

                return result === "Success";

            };

            const checkDeviceResult = function(importDeviceResultViewModel, importIndex) {

                const checkDeviceResultMessages = successHandlerMessages.CheckDeviceResult;

                ValidationUtilities.isNotNullOrUndefined(

                    importDeviceResultViewModel,
                    checkDeviceResultMessages.IMPORT_DEVICE_RESULT_VIEW_MODEL_CAN_NOT_BE_NULL_OR_UNDEFINED

                );

                ValidationUtilities.isPositiveNumber(

                    importIndex, checkDeviceResultMessages.IMPORT_INDEX_HAS_TO_BE_A_POSITIVE_NUMBER

                );

                const isSuccess = isResultSuccess(importDeviceResultViewModel);
                ValidationUtilities.isBoolean(isSuccess, checkDeviceResultMessages.IS_SUCCESS_HAS_TO_BE_A_BOOLEAN);

                const device = imports[importIndex];

                ValidationUtilities.isNotNullOrUndefined(

                    device, checkDeviceResultMessages.DEVICE_CAN_NOT_BE_NULL_OR_UNDEFINED

                );

                if (isSuccess === true) {

                    device.import = false;
                    device.error = false;
                    device.edit = false;

                } else {

                    const message = importDeviceResultViewModel.message;
                    const alert = AlertService.getDangerAlertWithAlertGlyphicon(message);

                    ErrorService.handleLedError(led, alert);

                    const deviceWithSerialCodeAlreadyExistsRegExp =
                        new RegExp("(serial code)+.+(already exists)");

                    const deviceWithSerialCodeAlreadyExists =
                        message.search(deviceWithSerialCodeAlreadyExistsRegExp) >= 0;

                    const deviceAlreadyExistsRegExp = new RegExp("(Device)+.+(already exists)");
                    const deviceAlreadyExists = message.search(deviceAlreadyExistsRegExp) >= 0;

                    if (deviceWithSerialCodeAlreadyExists) {

                        device.error = true;

                    } else if (deviceAlreadyExists) {

                        device.edit = true;

                    }

                }

            };

            const checkGroupResult = function(importGroupResultViewModel, importIndex) {

                const checkGroupResultMessages = successHandlerMessages.CheckGroupResult;

                ValidationUtilities.isNotNullOrUndefined(

                    importGroupResultViewModel,
                    checkGroupResultMessages.IMPORT_GROUP_RESULT_VIEW_MODEL_CAN_NOT_BE_NULL_OR_UNDEFINED

                );

                ValidationUtilities.isPositiveNumber(

                    importIndex, checkGroupResultMessages.IMPORT_INDEX_HAS_TO_BE_A_POSITIVE_NUMBER

                );

                const isSuccess = isResultSuccess(importGroupResultViewModel);
                ValidationUtilities.isBoolean(isSuccess, checkGroupResultMessages.IS_SUCCESS_HAS_TO_BE_A_BOOLEAN);

                const group = imports[importIndex];

                ValidationUtilities.isNotNullOrUndefined(

                    group, checkGroupResultMessages.GROUP_CAN_NOT_BE_NULL_OR_UNDEFINED

                );

                if (isSuccess === true) {

                    group.import = false;

                }

                const importDeviceResultViewModelList = importGroupResultViewModel.importDeviceResultViewModelList;

                ValidationUtilities.isNotNullOrUndefined(

                    importDeviceResultViewModelList,
                    checkGroupResultMessages.IMPORT_DEVICE_RESULT_VIEW_MODEL_LIST_CAN_NOT_BE_NULL_OR_UNDEFINED

                );

                const checkDeviceResult = function(importDeviceResultViewModel, importDeviceIndex) {

                    const checkDeviceResultMessages = checkGroupResultMessages.CheckDeviceResult;

                    ValidationUtilities.isNotNullOrUndefined(

                        importDeviceResultViewModel,
                        checkDeviceResultMessages.IMPORT_DEVICE_RESULT_VIEW_MODEL_CAN_NOT_BE_NULL_OR_UNDEFINED

                    );

                    ValidationUtilities.isPositiveNumber(

                        importDeviceIndex,
                        checkDeviceResultMessages.IMPORT_DEVICE_INDEX_HAS_TO_BE_A_POSITIVE_NUMBER

                    );

                    const isSuccess = isResultSuccess(importDeviceResultViewModel);

                    ValidationUtilities.isBoolean(

                        isSuccess, checkDeviceResultMessages.IS_SUCCESS_HAS_TO_BE_A_BOOLEAN

                    );

                    const devices = group.devices;

                    ValidationUtilities.isTrue(

                        !ArrayUtilities.isEmpty(devices),
                        checkDeviceResultMessages.DEVICES_CAN_NOT_BE_EMPTY

                    );

                    const device = devices[importDeviceIndex];

                    ValidationUtilities.isNotNullOrUndefined(

                        device, checkDeviceResultMessages.DEVICE_CAN_NOT_BE_NULL_OR_UNDEFINED

                    );

                    if (isSuccess === true) {

                        device.edit = false;

                    } else {

                        let message = "";

                        const groupName = group.name;
                        const hasGroupName = !ValueUtilities.isNullOrUndefined(groupName);

                        if (hasGroupName) {

                            ValidationUtilities.isString(
                                groupName, checkDeviceResultMessages.GROUP_NAME_HAS_TO_BE_A_STRING
                            );

                            message += groupName + " - ";

                        }

                        message += importDeviceResultViewModel.message;

                        const alert = AlertService.getDangerAlertWithAlertGlyphicon(message);
                        ErrorService.handleLedError(led, alert);

                        const deviceAlreadyExistsRegExp = new RegExp("(Device)+.+(already exists)");
                        const deviceAlreadyExists = message.search(deviceAlreadyExistsRegExp) >= 0;

                        if (deviceAlreadyExists) {

                            device.edit = true;

                        }

                    }

                };

                for (let i = 0; i < importDeviceResultViewModelList.length; i++) {

                    const importDeviceResultViewModel = importDeviceResultViewModelList[i];
                    checkDeviceResult(importDeviceResultViewModel, i);

                }

            };

            for (let i = 0; i < importResultViewModelList.length; i++) {

                const importResultViewModel = importResultViewModelList[i];

                ValidationUtilities.isNotNullOrUndefined(

                    importResultViewModel, checkGroupResult.IMPORT_RESULT_VIEW_MODEL_CAN_NOT_BE_NULL_OR_UNDEFINED

                );

                const resultClass = importResultViewModel["@class"];
                const isDevice = (resultClass === "device");
                const isGroup = (resultClass === "group");

                if (isDevice === true) {

                    checkDeviceResult(importResultViewModel, i);

                } else if (isGroup === true) {

                    checkGroupResult(importResultViewModel, i);

                } else {

                    throw checkGroupResult.UNSUPPORTED_RESULT_TYPE;

                }

            }

            const allResultsSuccess = importResultViewModelList.every(isResultSuccess);

            if (allResultsSuccess === true) {

                SuccessService.handleLedSuccess(led);
                $scope.hideModal("importDevicesModal");

            }

        };

        const failHandler = function() {

            const failHandlerMessages = importDevicesMessages.FailHandler;

            const message = failHandlerMessages.FAILED_TO_IMPORT_DEVICES;
            const alert = AlertService.getDangerAlertWithAlertGlyphicon(message);

            ValidationUtilities.isNotNullOrUndefined(

                alert, failHandlerMessages.ALERT_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            ValidationUtilities.isNotEmpty(alert, failHandlerMessages.ALERT_CAN_NOT_BE_EMPTY);

            ErrorService.handleLedError(led, alert);

        };

        DeviceActions.save(parameters, imports, successHandler, failHandler);

    };

    const isImportItemsEmpty = function() {

        return ArrayUtilities.isEmpty(importItems);

    };

    const getDeviceSerialCodeClass = function(device) {

        const getDeviceSerialCodeClassMessages = ImportDevicesControllerMessages.GetDeviceSerialCodeClass;

        ValidationUtilities.isNotNullOrUndefined(

            device, getDeviceSerialCodeClassMessages.DEVICE_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        const shouldImport = isImportTrue(device);
        ValidationUtilities.isBoolean(shouldImport, getDeviceSerialCodeClassMessages.SHOULD_IMPORT_HAS_TO_BE_A_BOOLEAN);

        const error = device.error;
        const hasError = (error === true);

        const importError = (shouldImport && hasError);

        return {

            importError: importError

        };

    };

    const checkDeviceEditState = function(device) {

        const checkDeviceEditStateMessages = ImportDevicesControllerMessages.CheckDeviceEditState;

        ValidationUtilities.isNotNullOrUndefined(

            device, checkDeviceEditStateMessages.DEVICE_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        const shouldImport = isImportTrue(device);
        ValidationUtilities.isBoolean(shouldImport, checkDeviceEditStateMessages.SHOULD_IMPORT_HAS_TO_BE_A_BOOLEAN);

        if (!shouldImport) {

            device.edit = false;

        }

    };

    const checkGroupDevicesEditState = function(group) {

        const checkGroupDevicesEditStateMessages = ImportDevicesControllerMessages.CheckGroupDevicesEditState;

        ValidationUtilities.isNotNullOrUndefined(

            group, checkGroupDevicesEditStateMessages.GROUP_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        const groupImport = group.import;
        const shouldImport = (groupImport === true);

        if (!shouldImport) {

            const devices = group.devices;

            ValidationUtilities.isNotNullOrUndefined(

                devices, checkGroupDevicesEditStateMessages.DEVICES_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            const disableEdit = function(device) {

                const disableEditMessages = checkGroupDevicesEditStateMessages.DisableEdit;

                ValidationUtilities.isNotNullOrUndefined(

                    device, disableEditMessages.DEVICE_CAN_NOT_BE_NULL_OR_UNDEFINED

                );

                device.edit = false;

            };

            devices.forEach(disableEdit);

        }

    };

    const resetImportDevicesForm = function() {

        const resetImportDevicesFormMessages = ImportDevicesControllerMessages.ResetImportDevicesForm;

        const forms = $scope.forms;
        ValidationUtilities.isNotEmpty(forms, resetImportDevicesFormMessages.FORMS_CAN_NOT_BE_EMPTY);

        const importDevicesForm = forms.importDevicesForm;

        ValidationUtilities.isNotEmpty(

            importDevicesForm, resetImportDevicesFormMessages.IMPORT_DEVICES_FORM_CAN_NOT_BE_EMPTY

        );

        importDevicesForm.$setPristine();

        const devices = angular.element("#devices");
        devices.val("");

    };

    angular.element("#importDevicesModal").on("hide.bs.modal", function() {

        const importDeviceModalHideMessages = ImportDevicesControllerMessages.ImportDeviceModalHide;

        resetImportDevicesForm();

        const polling = $scope.polling;
        ValidationUtilities.isNotEmpty(polling, importDeviceModalHideMessages.POLLING_CAN_NOT_BE_EMPTY);

        polling.update();

    });

    angular.element("#importDevicesModal").on("hidden.bs.modal", function() {

        SuccessService.handleLedSuccess(led);
        importItems = [];

    });

    return {

        led: led,

        getImportItems: getImportItems,
        getDevices: getDevices,
        getGroups: getGroups,
        loadImportItems: loadImportItems,
        isAnyImportItemSelected: isAnyImportItemSelected,
        importDevices: importDevices,
        isImportItemsEmpty: isImportItemsEmpty,
        getDeviceSerialCodeClass: getDeviceSerialCodeClass,
        checkDeviceEditState: checkDeviceEditState,
        checkGroupDevicesEditState: checkGroupDevicesEditState

    };

};

Object.freeze(ImportDevicesController);

export default ImportDevicesController;
