import ValidationUtilities from "./../../../../../../../../utilities/validationUtilities";
import ValueUtilities from "./../../../../../../../../utilities/valueUtilities";

import { getHasToBeStringMessage } from "./../../../../../../../messages";
import { getHasToBePositiveNumberMessage } from "./../../../../../../../messages";
import { getFailedToMessage } from "./../../../../../../../messages";

const getFailedToSendContentToFtpMessage = function(contentId, contentTitle, deviceId, deviceName) {

    const contentIdHasToBeStringMessage = getHasToBeStringMessage("Content id");
    ValidationUtilities.isString(contentId, contentIdHasToBeStringMessage);

    const contentTitleHasToBeStringMessage = getHasToBeStringMessage("Content title");
    ValidationUtilities.isString(contentTitle, contentTitleHasToBeStringMessage);

    const deviceIdHasToBePositiveNumberMessage = getHasToBePositiveNumberMessage("Device id");
    ValidationUtilities.isPositiveNumber(deviceId, deviceIdHasToBePositiveNumberMessage);

    let sendContentToFtpMessage = "" +
        "send content " + contentId + " (" + contentTitle + ") to FTP " +
        "of device " + deviceId;

    const hasDeviceName = !ValueUtilities.isNullOrUndefined(deviceName);

    if (hasDeviceName) {

        const deviceNameHasToBeStringMessage = getHasToBeStringMessage("Device name");
        ValidationUtilities.isString(deviceName, deviceNameHasToBeStringMessage);

        sendContentToFtpMessage += " (" + deviceName + ")";

    }

    return getFailedToMessage(sendContentToFtpMessage);

};

Object.freeze(getFailedToSendContentToFtpMessage);

export default getFailedToSendContentToFtpMessage;
