/**
 * Elements attributed with 'ipv4' require an 'ng-model' attribute of which the value will be validated as an
 * IPv4 address.
 */
const Ipv4Directive = function() {

    const link = function(scope, element, attributes, controller) {

        scope.validateNumber =
            /^(?!(0+\.0+\.0+\.0+))(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-4]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/;

        controller.$validators.ipv4 = function(modelValue) {

            return scope.validateNumber.test(modelValue);

        };

    };

    return {

        require: "ngModel",
        link: link

    };

};

export default Ipv4Directive;
