class NavigationBarController {

    constructor(NavigationService, sce) {

        NavigationService
            .getNavigationBarUrl()
            .$promise
            .then((response) => {

                const navigationBarUrl = response.result;
                this._navigationBarUrl = sce.trustAsResourceUrl(navigationBarUrl);

            });

    }

    getNavigationBarUrl() {

        return this._navigationBarUrl;

    }

}

export default NavigationBarController;
