/**
 * Elements attributed with 'maybe-required' get an attribute 'required=required' when their 'ng-model' attribute
 * value !== undefined. Use to make form fields required when some other field has been given a value, to demand either
 * none or both but not just one to have a value.
 */
const MaybeRequiredDirective = function() {

    const scope = {

        ngModel: "@"

    };

    const link = function(scope, element) {

        const watchExpression = function() {

            return scope.ngModel;

        };

        const listener = function() {

            if (scope.ngModel !== void(0)) {

                element.attr("required", "required");

            } else {

                element.removeAttr("required");

            }

        };

        scope.$watch(watchExpression, listener);

    };

    return {

        restrict: "A",
        scope: scope,
        link: link

    };

};

export default MaybeRequiredDirective;
