        ValidationUtilities.isString(

            propertyPath, getRadioButtonLabelClassMessages.PROPERTY_PATH_HAS_TO_BE_A_STRING

        );

        ValidationUtilities.isTrue(

            propertyPath.length > 0, getRadioButtonLabelClassMessages.PROPERTY_PATH_CAN_NOT_BE_EMPTY

        );

