import ValidationUtilities from "../../../../utilities/validationUtilities";

import { getHasToBeStringMessage } from "../../../messages";
import { getCanNotBeEmptyMessage } from "../../../messages";

const getNoModalFoundWithIdMessage = function(id) {

    const idHasToBeStringMessage = getHasToBeStringMessage("Id");
    ValidationUtilities.isString(id, idHasToBeStringMessage);

    const idCanNotBeEmptyMessage = getCanNotBeEmptyMessage("Id");
    ValidationUtilities.isTrue(id.length > 0, idCanNotBeEmptyMessage);

    return "No modal found with id: " + id + ".";

};

Object.freeze(getNoModalFoundWithIdMessage);

export default getNoModalFoundWithIdMessage;
