import ValueUtilities from "../utilities/valueUtilities";
import ValidationUtilities from "../utilities/validationUtilities";

import SuccessServiceMessages from "../messages/services/success/successService";

class SuccessService {

    constructor(LedColor, LedStatus) {

        this._LedColor = LedColor;
        this._LedStatus = LedStatus;

    }

    static get _successServiceMessages() {

        return SuccessServiceMessages;

    }

    handleLedSuccess(led) {

        const handleLedSuccessMessages = SuccessService._successServiceMessages.HandleLedSuccess;

        ValidationUtilities.isNotNullOrUndefined(

            led, handleLedSuccessMessages.LED_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        led.color = this._LedColor.GREEN;
        led.status = this._LedStatus.ON;

        const popover = led.popover;
        const hasPopover = !ValueUtilities.isNullOrUndefined(popover);

        if (hasPopover) {

            // Alerts

            const alerts = popover.alerts;

            ValidationUtilities.isNotNullOrUndefined(

                alerts, handleLedSuccessMessages.ALERTS_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            led.popover.alerts = [];

        }

    }

}

export default SuccessService;
