const ValueUtilities = function() {

    const isNullOrUndefined = function(value) {

        return value === null || value === undefined;

    };

    const isEmpty = function(value) {

        return isNullOrUndefined(value) || Object.keys(value).length === 0;

    };

    const isTypeOf = function(value, type) {

        return (typeof value === type);

    };

    const isString = function(value) {

        return isTypeOf(value, "string");

    };

    return {

        isNullOrUndefined: isNullOrUndefined,
        isEmpty: isEmpty,
        isTypeOf: isTypeOf,
        isString: isString

    };

}();

export default ValueUtilities;
