import ValueUtilities from "../utilities/valueUtilities";

const DevicePropertyService = function(Devices, $parse) {

    /**
     * Top level device model properties mapped to their REST prefix.
     */
    const entries = [

        {

            prefix: "system",
            properties: [
                "sicpVersion", "platformLabel", "platformVersion",
                "modelNumber", "firmwareVersion", "buildDate", "firmwareVersionAndroid"
            ]

        },

        {

            prefix: "general",
            properties: [
                "powerState", "remoteControlLockState", "keypadLockState", "powerStateAtColdStart",
                "monitorRestart", "backlight","languageOSD","autoRestartParameter","clockParameter","autoTimeSync",
                "dateParameter","timeZone"
            ]

        },

        {

            prefix: "inputSources",
            properties: ["inputSource", "autoSignalDetecting", "failovers"]

        },

        {

            prefix: "video",
            properties: ["videoParameters", "colorTemperature", "colorTemperature100K", "colorParameters", "pictureFormat",
                "vgaVideoParameters", "pictureInPicture", "pictureInPictureSource", "pictureStyle"]

        },

        {

            prefix: "audio",
            properties: ["volume", "volumeLimitsSpeakerOut", "volumeLimitsAudioOut", "audioParameters", "mute", "audioSync",
            "speakersStatus"]

        },

        {

            prefix: "miscellaneous",
            properties: [
                "miscellaneous", "smartPower", "temperatureSensor", "serialCode", "tiling", "lightSensor",
                "osdRotating", "osdInformation", "memcEffect", "touch", "noiseReduction", "scanMode", "scanConversion",
                "switchOnDelay", "powerOnLogo", "fanSpeed", "apm", "powerSavingMode", "displayOrientation", "offTimer",
                "lockUsb", "humanSensor", "pixelShift", "ecoMode", "takeScreenshot", "videoPresent", "frameCompensationHorizontal",
                "frameCompensationVertical", "openAndroidMenu", "navigationBar","bootOnSource","hdmiOneWire","rS232Routing",
                "sicpSerialPortForwarding","teamviewerStatus","wOL"
            ]

        },

        {

            prefix: "scheduling",
            properties: ["schedulingParameters"]

        },

        {

            prefix: "edit",
            properties: ["ipDestination", "name", "ftpSettings", "contentRotated"]

        },

        {

            prefix: null,
            properties: ["matrixPosition"]

        }

    ];

    const getPrefix = function(propertyName) {

        const getPropertyIndex = function(entry) {

            let parsedPropertyName = propertyName;

            if (propertyName.startsWith("schedulingParameters")) {

                parsedPropertyName = "schedulingParameters";

            }

            return ~entry.properties.indexOf(parsedPropertyName);

        };

        const entry = entries.find(getPropertyIndex);

        return entry.prefix;

    };

    /**
     * Returns the top-level device properties that are relevant to Device Settings.
     */
    const getSettingsProperties = function() {

        const settingsPrefixes = ["general", "inputSources", "video", "audio", "miscellaneous", "scheduling"];
        var properties = [];

        const getPrefixIndex = function(entry) {

            const prefix = entry.prefix;

            return ~settingsPrefixes.indexOf(prefix);

        };

        const concatenateProperties = function(entry) {

            const entryProperties = entry.properties;
            properties = properties.concat(entryProperties);

        };

        const filteredEntries = entries.filter(getPrefixIndex);
        filteredEntries.forEach(concatenateProperties);

        return properties;

    };

    /**
     * HTTP GET a property, merge the given value into it, and HTTP PUT it. Prevents submission of null in complex types.
     */
    const getPropertyAndSave = function(device, propertyName, fieldName, onSuccess, onFail) {

        const id = device.id;
        const prefix = getPrefix(propertyName);

        let parsedPropertyName = propertyName;
        let value = null;

        switch (propertyName) {

            case "pictureInPictureSource":

                parsedPropertyName = "pictureInPicture";
                value = "source";
                break;

            case "volumeLimitsSpeakerOut":

                parsedPropertyName = "volumeLimits";
                value = "speakerOut";
                break;

            case "volumeLimitsAudioOut":

                parsedPropertyName = "volumeLimits";
                value = "audioOut";
                break;

        }

        const parameters = {

            id: id,
            prefix: prefix,
            property: parsedPropertyName,
            value: value

        };

        const successHandler = function(model) {

            const getFieldName = $parse(fieldName);
            const setFieldName = getFieldName.assign;
            const getPropertyNameFieldName = $parse(propertyName + "." + fieldName);
            const newFieldName = getPropertyNameFieldName(device);

            setFieldName(model, newFieldName);
            device[propertyName] = model;

            Devices.put(parameters, device[propertyName], onSuccess, onFail);

        };

        Devices.get(parameters, null, successHandler, onFail);

    };

    /**
     * HTTP PUT a value to a property.
     */
    const saveProperty = function(device, propertyPath, onSuccess, onFail) {

        const splitPropertyPath = propertyPath.split(".");
        let propertyName = splitPropertyPath[0];
        const fieldName = propertyPath.slice(propertyName.length + 1);
        let prefix = getPrefix(propertyName);

        if ((fieldName.length > 0) && (prefix !== "edit") && (prefix !== "scheduling")) {

            getPropertyAndSave(device, propertyName, fieldName, onSuccess, onFail);

        } else {

            let propertyValue;
            let payload = null;
            let type = null;

            if (prefix === "edit") {

                type = "edit";
                prefix = null;

                if (propertyName === "name") {

                    propertyValue = device.name;

                } else if (propertyName === "contentRotated") {

                    propertyValue = device.contentRotated;

                } else {

                    if (propertyName === "ftpSettings") {

                        prefix = "ftpSettings";

                    }

                    if (fieldName === "password") {

                        const password = device[propertyName][fieldName];

                        payload = {

                            password: password

                        };

                    } else {

                        propertyValue = device[propertyName][fieldName];

                        if (fieldName === "ip") {

                            propertyValue += ".IP";

                        }

                    }

                    propertyName = fieldName;

                }

            } else if ((prefix === "scheduling") && (propertyName === "schedulingParameters")) {

                propertyValue = fieldName;

                const page = device[propertyName][propertyValue];
                const pageToSave = angular.copy(page);

                const oldStart = pageToSave.start;

                if (!ValueUtilities.isNullOrUndefined(oldStart)) {

                    const oldStartHours = oldStart.getHours();
                    const newStartHours = ("0" + oldStartHours).slice(-2);
                    const oldStartMinutes = oldStart.getMinutes();
                    const newStartMinutes = ("0" + oldStartMinutes).slice(-2);
                    pageToSave.start = newStartHours + ":" + newStartMinutes;

                }

                const oldEnd = pageToSave.end;

                if (!ValueUtilities.isNullOrUndefined(oldEnd)) {

                    const oldEndHours = oldEnd.getHours();
                    const newEndHours = ("0" + oldEndHours).slice(-2);
                    const oldEndMinutes = pageToSave.end.getMinutes();
                    const newEndMinutes = ("0" + oldEndMinutes).slice(-2);
                    pageToSave.end = newEndHours + ":" + newEndMinutes;

                }

                payload = pageToSave;

            } else if ((prefix === "miscellaneous") && propertyName === "humanSensor") {
                const step = device.deviceLimits[propertyName].step;
                propertyValue = device[propertyName] / step;
            } else if ((prefix === "miscellaneous") && propertyName === "pixelShift") {
                const step = device.deviceLimits[propertyName].step;
                payload = {
                    value: device[propertyName].value / step,
                    state: device[propertyName].state
                };
            } else if ((prefix === "general") && propertyName === "clockParameter") {
                const clockParameter = device[propertyName];
                propertyValue = clockParameter.getHours() + ":" + clockParameter.getMinutes();
            } else if ((prefix === "general") && propertyName === "dateParameter") {
                const dateParameter = device[propertyName];
                propertyValue = dateParameter.getFullYear() + "-" + (dateParameter.getMonth() + 1) + "-" + dateParameter.getDate();
            } else if ((prefix === "general") && propertyName === "autoRestartParameter") {
                const autoRestartParameter = device[propertyName];
                const restartTime = autoRestartParameter.restartTime;
                payload = {
                    "status": autoRestartParameter.status,
                    "restartTime": restartTime == null ? "" : (restartTime.getHours() + ":" + restartTime.getMinutes())
                };
            } else {
                const isComplexType = typeof(device[propertyName]) == "object";
                propertyValue = isComplexType ? null : device[propertyName];
                payload = isComplexType ? device[propertyName] : null;
            }

            const parameters = {

                id: device.id,
                type: type,
                prefix: prefix,
                property: propertyName,
                value: propertyValue

            };

            Devices.put(parameters, payload, onSuccess, onFail);

        }

    };

    /**
     * HTTP GET a property and assign the returned value to the given device object.
     */
    const updateProperty = function(device, propertyName, onSuccess, onFail) {

        const prefix = getPrefix(propertyName);

        let parsedPropertyName = propertyName;
        let value = null;

        if (propertyName.startsWith("schedulingParameters")) {

            parsedPropertyName = "schedulingParameters";

            const start = "schedulingParameters".length;
            const end = propertyName.length;
            const pageName = propertyName.substring(start, end);
            value = pageName.toLowerCase();

        } else {

            switch (propertyName) {

                case "pictureInPictureSource":

                    parsedPropertyName = "pictureInPicture";
                    value = "source";
                    break;

                case "volumeLimitsSpeakerOut":

                    parsedPropertyName = "volumeLimits";
                    value = "speakerOut";
                    break;

                case "volumeLimitsAudioOut":

                    parsedPropertyName = "volumeLimits";
                    value = "audioOut";
                    break;

            }

        }

        const parameters = {

            id: device.id,
            prefix: prefix,
            property: parsedPropertyName,
            value: value

        };

        const onSuccessHandler = function(response) {

            if (response.hasOwnProperty("result")) {

                response = response.result;

            }

            if (propertyName.startsWith("schedulingParameters")) {

                const pageName = value;
                const schedulingParameters = device[parsedPropertyName];

                if (ValueUtilities.isNullOrUndefined(schedulingParameters)) {

                    device[parsedPropertyName] = {};

                }

                const page = angular.copy(response);

                // Start

                const oldStart = page.start;
                const hasStart = !ValueUtilities.isNullOrUndefined(oldStart);
                const newStart = hasStart ? new Date("1970-01-01T" + oldStart + "Z") : new Date("1970-01-01T00:00Z");
                const newStartOldMinutes = newStart.getMinutes();
                const newStartTimezoneOffset = newStart.getTimezoneOffset();
                const newStartNewMinutes = newStartOldMinutes + newStartTimezoneOffset;
                newStart.setMinutes(newStartNewMinutes);
                page.start = newStart;

                // End

                const oldEnd = page.end;
                const hasEnd = !ValueUtilities.isNullOrUndefined(oldEnd);
                const newEnd = hasEnd ? new Date("1970-01-01T" + oldEnd + "Z") : new Date("1970-01-01T00:00Z");
                const newEndOldMinutes = newEnd.getMinutes();
                const newEndTimezoneOffset = newEnd.getTimezoneOffset();
                const newEndNewMinutes = newEndOldMinutes + newEndTimezoneOffset;
                newEnd.setMinutes(newEndNewMinutes);
                page.end = newEnd;

                device[parsedPropertyName][pageName] = page;

            } else if (propertyName.startsWith("humanSensor")) {
                const step = device.deviceLimits[propertyName].step;
                device[propertyName] = response * step;
            } else if (propertyName.startsWith("pixelShift")) {
                const step = device.deviceLimits[propertyName].step;
                device[propertyName] = {
                    value: response.value * step,
                    state: response.state
                };
            } else if (propertyName.startsWith("dateParameter")) {
                device[propertyName] = new Date(response);
            } else if (propertyName.startsWith("clockParameter")) {
                device[propertyName] = new Date("1970-01-01 " + response);
            } else if (propertyName.startsWith("autoRestartParameter")) {
                if (!ValueUtilities.isNullOrUndefined(response.restartTime)) {
                    response.restartTime = new Date("1970-01-01 " + response.restartTime);
                }
                device[propertyName] = response;
            } else {
                device[propertyName] = response;
            }

            if (onSuccess) {

                onSuccess(response);

            }

        };

        const call = (propertyName === "failovers") ? Devices.query : Devices.get;
        call(parameters, null, onSuccessHandler, onFail);

    };

    return {

        getSettingsProperties: getSettingsProperties,
        saveProperty: saveProperty,
        updateProperty: updateProperty

    };

};

export default DevicePropertyService;
