class GroupService {

    constructor(resource) {

        this._resource = resource;

    }

    static get _GroupsUrl() {

        return "/smartcontrol/api/groups";

    }

    getGroups() {

        const url = GroupService._GroupsUrl;
        const resource = this._resource(url);

        return resource.query({});

    }

    getGroupsWithoutDevices() {

        const url = GroupService._GroupsUrl + "/lazy";
        const resource = this._resource(url);

        return resource.query({});

    }

    getGroup(groupId, orderBy, orderDirection) {

        const url = GroupService._GroupsUrl + "/" + groupId + "?orderBy=" + orderBy + "&orderDirection=" + orderDirection;
        const resource = this._resource(url);

        return resource.get();

    }

    getGroupDevices(groupId, orderBy, orderDirection) {

        const url = GroupService._GroupsUrl + "/" + groupId + "/devices?orderBy=" + orderBy + "&orderDirection=" + orderDirection;
        const resource = this._resource(url);

        return resource.query({});

    }

}

export default GroupService;
