import AlertsPopoverLedDirective from "../directives/alertsPopoverLed";
import Ipv4Directive from "../directives/ipv4";
import MaybeRequiredDirective from "../directives/maybeRequired";
import NzToggleDirective from "../directives/nzToggle";
import OnOffSwitchDirective from "../directives/onOffSwitch";
import RefreshDirective from "../directives/refresh";
import FileDirective from "../directives/file";

const app = angular.module("smartcontrol");

app.directive(

    "alertsPopoverLed",

    [

        "LedColor", "LedStatus",
        AlertsPopoverLedDirective

    ]

);

app.directive("ipv4", Ipv4Directive);
app.directive("maybeRequired", MaybeRequiredDirective);
app.directive("nzToggle", NzToggleDirective);
app.directive("onOffSwitch", OnOffSwitchDirective);

app.directive(

    "refresh",

    [

        "DevicePropertyService", "ErrorService", "SuccessService", "AlertService", "DeviceSettingsService",
        "Devices",

        RefreshDirective

    ]

);

app.directive("file", FileDirective);
