import ValueUtilities from "../../utilities/valueUtilities";
import ValidationUtilities from "../../utilities/validationUtilities";

import DetectDevicesControllerMessages from "../../messages/controllers/detect_devices/detectDevicesController";
import * as Messages from "../../messages/messages";

const DetectDevicesController = function(

    ErrorService, SuccessService, LedService, AlertService, PopoverService, DeviceActions, Settings, $scope, $timeout

) {

    let hasRanDetectAtLeastOnce = false;

    // Settings
    $scope.settings = {};

    // Timeouts

    const timeouts = {};

    // Popover

    const title = "Error";

    const popover = PopoverService.getAlertsPopoverWithPlacementBottom(title);

    ValidationUtilities.isNotNullOrUndefined(

        popover, DetectDevicesControllerMessages.POPOVER_CAN_NOT_BE_NULL_OR_UNDEFINED

    );

    // Led

    const led = LedService.getGreenOnLed(popover);
    ValidationUtilities.isNotNullOrUndefined(led, DetectDevicesControllerMessages.LED_CAN_NOT_BE_NULL_OR_UNDEFINED);

    const detectDevices = function() {

        const detectDevicesMessages = DetectDevicesControllerMessages.DetectDevices;
        const throbber = $scope.setLoading("detectDevices", true);

        const parameters = {

            action: "detect"

        };

        const successHandler = function(deviceListItems) {

            const successHandlerMessages = detectDevicesMessages.SuccessHandler;

            ValidationUtilities.isNotEmpty(

                deviceListItems, successHandlerMessages.RETRIEVED_DEVICE_LIST_ITEMS_CAN_NOT_BE_EMPTY

            );

            throbber.off();

            const getImportItem = function(deviceListItem) {

                const getImportItemMessages = successHandlerMessages.GetImportItem;

                ValidationUtilities.isNotEmpty(

                    deviceListItem, getImportItemMessages.DEVICE_LIST_ITEM_CAN_NOT_BE_EMPTY

                );

                return {

                    deviceListItem: deviceListItem,
                    import: true

                };

            };

            const importItems = deviceListItems.map(getImportItem);
            $scope.setImportItems(importItems);
            hasRanDetectAtLeastOnce = true;

            SuccessService.handleLedSuccess(led);

        };

        const failHandler = function() {

            const failHandlerMessages = detectDevicesMessages.FailHandler;

            throbber.off();

            const message = failHandlerMessages.FAILED_TO_DETECT_DEVICES;

            const alert = AlertService.getDangerAlertWithAlertGlyphicon(message);
            ValidationUtilities.isNotNullOrUndefined(alert, failHandlerMessages.ALERT_CAN_NOT_BE_NULL_OR_UNDEFINED);
            ValidationUtilities.isNotEmpty(alert, failHandlerMessages.ALERT_CAN_NOT_BE_EMPTY);

            ErrorService.handleLedError(led, alert);

        };

        DeviceActions.query(parameters, successHandler, failHandler);

    };

    const shouldImport = function(importItem) {

        const shouldImportMessages = DetectDevicesControllerMessages.ShouldImport;

        ValidationUtilities.isNotEmpty(importItem, shouldImportMessages.IMPORT_ITEM_CAN_NOT_BE_EMPTY);

        return importItem.import === true;

    };

    const importDevices = function() {

        const importDevicesMessages = DetectDevicesControllerMessages.ImportDevices;

        const importItems = $scope.importItems;
        ValidationUtilities.isNotEmpty(importItems, importDevicesMessages.IMPORT_ITEMS_CAN_NOT_BE_EMPTY);

        const getDeviceListItem = function(importItem) {

            const getDeviceListItemMessages = importDevicesMessages.GetDeviceListItem;
            ValidationUtilities.isNotEmpty(importItem, getDeviceListItemMessages.IMPORT_ITEM_CAN_NOT_BE_EMPTY);

            return importItem.deviceListItem;

        };

        const importItemsToImport = importItems.filter(shouldImport);

        ValidationUtilities.isNotNullOrUndefined(

            importItemsToImport,
            importDevicesMessages.IMPORT_ITEMS_TO_IMPORT_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        const deviceListItemsToImport = importItemsToImport.map(getDeviceListItem);

        ValidationUtilities.isNotNullOrUndefined(

            deviceListItemsToImport,
            importDevicesMessages.DEVICE_LIST_ITEMS_TO_IMPORT_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        $scope.hideModal("detectDevicesModal");

        const parameters = {

            action: "detect",
            subAction: "import"

        };

        const successHandler = function() {

            const successHandlerMessages = importDevicesMessages.SuccessHandler;

            SuccessService.handleLedSuccess(led);

            const polling = $scope.polling;
            ValidationUtilities.isNotEmpty(polling, successHandlerMessages.POLLING_CAN_NOT_BE_EMPTY);

            polling.update();

        };

        const failHandler = function() {

            const failHandlerMessages = importDevicesMessages.FailHandler;

            const message = failHandlerMessages.FAILED_TO_IMPORT_DEVICES;

            const alert = AlertService.getDangerAlertWithAlertGlyphicon(message);
            ValidationUtilities.isNotNullOrUndefined(alert, failHandlerMessages.ALERT_CAN_NOT_BE_NULL_OR_UNDEFINED);
            ValidationUtilities.isNotEmpty(alert, failHandlerMessages.ALERT_CAN_NOT_BE_EMPTY);

            ErrorService.handleLedError(led, alert);

        };

        DeviceActions.save(parameters, deviceListItemsToImport, successHandler, failHandler);

    };

    const importItemsToImport = function() {

        const importItems = $scope.importItems;

        return !ValueUtilities.isEmpty(importItems) && importItems.some(shouldImport);

    };

    const isDetecting = function() {

        return $scope.getLoading("detectDevices");

    };

    const isImportItemsEmpty = function() {

        const importItems = $scope.importItems;

        return ValueUtilities.isEmpty(importItems);

    };

    const getDetectTimeout = function() {
        const throbber = $scope.setLoading("getDetectTimeout", true);

        const parameters = {
            setting: "detectDevicesTimeoutInMilliseconds"
        };

        const successHandler = function(response) {
            ValidationUtilities.isNotNullOrUndefined(response, Messages.getCanNotBeNullOrUndefinedMessage("Response"));

            const detectDevicesTimeoutInMilliseconds = response.result;
            ValidationUtilities.isPositiveNumber(
                detectDevicesTimeoutInMilliseconds,
                Messages.getHasToBePositiveNumberMessage("DetectDevicesTimeoutInMilliseconds")
            );

            $scope.settings.detectDevicesTimeoutInMilliseconds = detectDevicesTimeoutInMilliseconds;
            throbber.off();
            SuccessService.handleLedSuccess(led);
        };

        const failHandler = function() {
            throbber.off();
            const message = Messages.getFailedToMessage("get detect devices timeout");

            const alert = AlertService.getDangerAlertWithAlertGlyphicon(message);
            ValidationUtilities.isNotNullOrUndefined(
                alert, Messages.getCanNotBeNullOrUndefinedMessage("Alert")
            );
            ValidationUtilities.isNotEmpty(
                alert, Messages.getCanNotBeEmptyMessage("Alert")
            );

            ErrorService.handleLedError(led, alert);
        };

        Settings.get(parameters, successHandler, failHandler);
    };

    const saveSetting = function(propertyPath) {
        ValidationUtilities.isString(
            propertyPath, Messages.getHasToBeStringMessage("Property path")
        );
        ValidationUtilities.isTrue(
            propertyPath.length > 0, Messages.getCanNotBeEmptyMessage("Property path")
        );

        const splitPropertyPath = propertyPath.split(".");
        const propertyName = splitPropertyPath[0];
        const fieldName = propertyPath.slice(propertyName.length + 1);

        const existingTimeout = timeouts[propertyPath];

        if (existingTimeout) {
            $timeout.cancel(existingTimeout);
            delete timeouts[propertyPath];
        }

        let isSettingValid = false;

        const forms = $scope.forms;
        ValidationUtilities.isNotEmpty(
            forms, Messages.getCanNotBeEmptyMessage("Forms")
        );

        const detectSettingsForm = forms.detectSettingsForm;
        ValidationUtilities.isNotEmpty(
            detectSettingsForm, Messages.getCanNotBeEmptyMessage("Detect settings form")
        );

        let property = null;
        let parsedFieldName = fieldName;

        if (!ValueUtilities.isEmpty(fieldName)) {
            const field = detectSettingsForm[parsedFieldName];
            ValidationUtilities.isNotNullOrUndefined(
                field, Messages.getCanNotBeNullOrUndefinedMessage("Field")
            );

            isSettingValid = $scope.forms.detectSettingsForm[parsedFieldName].$valid;
            property = fieldName;
        } else {
            const field = detectSettingsForm[propertyName];
            ValidationUtilities.isNotNullOrUndefined(
                field, Messages.getCanNotBeNullOrUndefinedMessage("Field")
            );

            isSettingValid = $scope.forms.detectSettingsForm[propertyName].$valid;
        }

        if (isSettingValid === true) {
            const saveProperty = function() {
                const throbber = $scope.setLoading("saveDetectSetting", true);

                let payload = null;
                let value;

                if ($scope.settings !== undefined) {
                    switch (propertyName) {
                        case "detectDevicesTimeoutInMilliseconds":
                            value = $scope.settings.detectDevicesTimeoutInMilliseconds;
                            break;
                    }
                }

                const settings = {
                    setting: propertyName,
                    property: property,
                    value: value
                };

                const successHandler = function() {
                    throbber.off();
                    SuccessService.handleLedSuccess(led);
                };

                const failHandler = function() {
                    throbber.off();
                    const message = Messages.getFailedToMessage("save setting");
                    const alert = AlertService.getDangerAlertWithAlertGlyphicon(message);
                    ValidationUtilities.isNotNullOrUndefined(
                        alert, Messages.getCanNotBeNullOrUndefinedMessage("Alert")
                    );
                    ValidationUtilities.isNotEmpty(
                        alert, Messages.getCanNotBeEmptyMessage("Alert")
                    );

                    ErrorService.handleLedError(led, alert);
                };

                Settings.put(settings, payload, successHandler, failHandler);
            };

            timeouts[propertyPath] = $timeout(saveProperty, 1000);
        }
    };

    const hasDetectBeenRanAtLeastOnce = function() {
        return hasRanDetectAtLeastOnce;
    };

    const resetDetectSettingsForm = function() {
        const forms = $scope.forms;
        ValidationUtilities.isNotEmpty(
            forms, Messages.getCanNotBeEmptyMessage("Forms")
        );

        const detectSettingsForm = forms.detectSettingsForm;
        ValidationUtilities.isNotEmpty(
            detectSettingsForm, Messages.getCanNotBeEmptyMessage("Detect settings form")
        );

        detectSettingsForm.$setPristine();
    };

    angular.element("#detectDevicesModal").on("show.bs.modal", getDetectTimeout);
    angular.element("#detectDevicesModal").on("hide.bs.modal", resetDetectSettingsForm);

    angular.element("#detectDevicesModal").on("hidden.bs.modal", function() {

        $scope.settings = {};
        $scope.resetImportItems();
        $scope.detectDevicesAlerts = [];
        hasRanDetectAtLeastOnce = false;
        SuccessService.handleLedSuccess(led);

    });

    return {

        led: led,

        importDevices: importDevices,
        importItemsToImport: importItemsToImport,
        isDetecting: isDetecting,
        isImportItemsEmpty: isImportItemsEmpty,
        saveSetting: saveSetting,
        detectDevices: detectDevices,
        hasDetectBeenRanAtLeastOnce: hasDetectBeenRanAtLeastOnce

    };

};

export default DetectDevicesController;
