import ValidationUtilities from "../utilities/validationUtilities";
import AlertServiceMessages from "../messages/services/alert/alertService";

class AlertService {

    static get _alertServiceMessages() {

        return AlertServiceMessages;

    }

    getAlert(alertType, glyphiconType, message) {

        const getAlertMessages = AlertService._alertServiceMessages.GetAlert;

        // Validation \\

        // Alert type

        ValidationUtilities.isString(alertType, getAlertMessages.ALERT_TYPE_HAS_TO_BE_A_STRING);
        ValidationUtilities.isTrue(alertType.length > 0, getAlertMessages.ALERT_TYPE_CAN_NOT_BE_EMPTY);

        // Glyphicon type

        ValidationUtilities.isString(glyphiconType, getAlertMessages.GLYPHICON_TYPE_HAS_TO_BE_A_STRING);
        ValidationUtilities.isTrue(glyphiconType.length > 0, getAlertMessages.GLYPHICON_TYPE_CAN_NOT_BE_EMPTY);

        // Message

        ValidationUtilities.isString(message, getAlertMessages.MESSAGE_HAS_TO_BE_A_STRING);
        ValidationUtilities.isTrue(message.length > 0, getAlertMessages.MESSAGE_CAN_NOT_BE_EMPTY);

        // Alert \\

        return {

            type: alertType,
            glyphiconClass: "glyphicon-" + glyphiconType,
            message: message

        };

    }

    getDangerAlert(glyphiconType, message) {

        const getDangerAlertMessages = AlertService._alertServiceMessages.GetDangerAlert;

        // Validation \\

        // Glyphicon type

        ValidationUtilities.isString(glyphiconType, getDangerAlertMessages.GLYPHICON_TYPE_HAS_TO_BE_A_STRING);
        ValidationUtilities.isTrue(glyphiconType.length > 0, getDangerAlertMessages.GLYPHICON_TYPE_CAN_NOT_BE_EMPTY);

        // Message

        ValidationUtilities.isString(message, getDangerAlertMessages.MESSAGE_HAS_TO_BE_A_STRING);
        ValidationUtilities.isTrue(message.length > 0, getDangerAlertMessages.MESSAGE_CAN_NOT_BE_EMPTY);

        // Alert \\

        const alertType = "danger";

        return this.getAlert(alertType, glyphiconType, message);

    }

    getDangerAlertWithAlertGlyphicon(message) {

        const getDangerAlertWithAlertGlyphiconMessages =
            AlertService._alertServiceMessages.GetDangerAlertWithAlertGlyphicon;

        // Validate message \\

        ValidationUtilities.isString(

            message, getDangerAlertWithAlertGlyphiconMessages.MESSAGE_HAS_TO_BE_A_STRING

        );

        ValidationUtilities.isTrue(

            message.length > 0, getDangerAlertWithAlertGlyphiconMessages.MESSAGE_CAN_NOT_BE_EMPTY

        );

        // Alert \\

        const glyphiconType = "alert";

        return this.getDangerAlert(glyphiconType, message);

    }

}

export default AlertService;
