const ResourceActions = function() {

    const put = {

        method: "PUT"

    };

    return {

        put: put

    };

}();

const User = function($resource) {

    return $resource("/smartcontrol/user");

};

const Devices = function($resource) {

    const url = "/smartcontrol/api/devices/:id/:type/:prefix/:property/:value";

    const parameters = {

        id: "@id",
        property: "@property",
        value: "@value",
        prefix: "@prefix",
        type: "@type"

    };

    return $resource(url, parameters, ResourceActions);

};

const Groups = function($resource) {

    const url = "/smartcontrol/api/groups/:id";

    const parameters = {

        id: "@id"

    };

    return $resource(url, parameters, ResourceActions);

};

const GroupContent = function($resource) {

    const url = "/smartcontrol/api/groups/:groupId/content/:contentId";

    const parameters = {

        groupId: "@groupId",
        contentId: "@contentId"

    };

    return $resource(url, parameters, ResourceActions);

};

const DeviceActions = function($resource) {

    const url = "/smartcontrol/api/devices/:action/:subAction";

    const parameters = {

        action: "@action",
        subAction: "@subAction"

    };

    const actions = {

        save: {

            method: "POST",
            isArray: true

        }

    };

    return $resource(url, parameters, actions);

};

const Content = function($resource) {

    return $resource("/smartcontrol/api/content");

};

const Hardware = function($resource) {

    const url = "/smartcontrol/api/hardware/:hardwareKey/:contentId";

    const parameters = {

        hardwareKey: "@hardwareKey",
        contentId: "@contentId"

    };

    return $resource(url, parameters, ResourceActions);

};

const Settings = function($resource) {

    const url = "/smartcontrol/api/settings/:setting/:property/:value";

    const parameters = {

        setting: "@setting",
        property: "@property",
        value: "@value"

    };

    return $resource(url, parameters, ResourceActions);

};

const Navigation = function($resource) {

    return $resource("/smartcontrol/api/navigation");

};

const Version = function($resource) {

    return $resource("/smartcontrol/api/version");

};

const DevicesData = function($resource) {

    return $resource("/smartcontrol/api/data/devices");

};

export default {

    User,
    Devices,
    Groups,
    GroupContent,
    DeviceActions,
    Content,
    Hardware,
    Settings,
    Navigation,
    Version,
    DevicesData

};
