const ValidationUtilities = function() {

    const isNotNull = function(value, message) {

        if (value === null) {

            throw message;

        }

    };

    const isNotUndefined = function(value, message) {

        if (value === undefined) {

            throw message;

        }

    };

    const isNotNullOrUndefined = function(value, message) {

        isNotNull(value, message);
        isNotUndefined(value, message);

    };

    const isTypeOf = function(value, type, message) {

        if (typeof value !== type) {

            throw message;

        }

    };

    const isBoolean = function(value, message) {

        isTypeOf(value, "boolean", message);

    };

    const isString = function(value, message) {

        isTypeOf(value, "string", message);

    };

    const isNumber = function(value, message) {

        const parsedValue = parseFloat(value);

        if (isNaN(parsedValue) || !isFinite(value)) {

            throw message;

        }

    };

    const isPositiveNumber = function(value, message) {

        isNumber(value);

        if (value < 0) {

            throw message;

        }

    };

    const isNotEmpty = function(value, message) {

        isNotNullOrUndefined(value, message);

        if (Object.keys(value).length === 0) {

            throw message;

        }

    };

    const isTrue = function(expression, message) {

        if (expression !== true) {

            throw message;

        }

    };

    return {

        isNotNull: isNotNull,
        isNotUndefined: isNotUndefined,
        isNotNullOrUndefined: isNotNullOrUndefined,
        isTypeOf: isTypeOf,
        isBoolean: isBoolean,
        isString: isString,
        isNumber: isNumber,
        isPositiveNumber: isPositiveNumber,
        isNotEmpty: isNotEmpty,
        isTrue: isTrue

    };

}();

export default ValidationUtilities;
