const validateInput = function(input) {

    if (typeof input !== "string") {

        throw "Input has to be a string.";

    }

    if (input.length <= 0) {

        throw "Input can not be empty.";

    }

};

const getCanNotBeEmptyMessage = function(input) {

    return input.concat(" can't be empty.");

};

const getHasToBeBooleanMessage = function(input) {

    validateInput(input);

    return input.concat(" has to be a boolean.");

};

const getHasToBeStringMessage = function(input) {

    validateInput(input);

    return input.concat(" has to be a string.");

};

const getHasToBePositiveNumberMessage = function(input) {

    validateInput(input);

    return input.concat(" has to be a positive number.");

};

const getHasToBeHigherThanMessage = function(input, number) {

    validateInput(input);

    return input.concat(" has to be higher than ").concat(number).concat(".");

};

const getCanNotBeNullOrUndefinedMessage = function(input) {

    validateInput(input);

    return input.concat(" can't be null or undefined.");

};

const getFailedToMessage = function(input) {

    validateInput(input);

    return "Failed to ".concat(input).concat(".");

};

export {

    validateInput,
    getCanNotBeEmptyMessage,
    getHasToBeBooleanMessage,
    getHasToBeStringMessage,
    getHasToBePositiveNumberMessage,
    getHasToBeHigherThanMessage,
    getCanNotBeNullOrUndefinedMessage,
    getFailedToMessage

};
