import ValueUtilities from "../../../utilities/valueUtilities";
import ValidationUtilities from "../../../utilities/validationUtilities";

import DownloadContentControllerMessages from "../../../messages/controllers/download_content/downloadContentController";

const DownloadContentController = function(ErrorService, SuccessService, AlertService, Devices, $scope, $window) {

    let alert = {};

    const downloadContent = function() {

        const downloadContentMessages = DownloadContentControllerMessages.DownloadContent;

        const device = $scope.currentDevice;
        ValidationUtilities.isNotEmpty(device, downloadContentMessages.DEVICE_CAN_NOT_BE_EMPTY);

        const deviceId = device.id;

        ValidationUtilities.isPositiveNumber(

            deviceId, downloadContentMessages.DEVICE_ID_HAS_TO_BE_A_POSITIVE_NUMBER

        );

        const throbber = $scope.setLoading("info-" + deviceId, true);

        const led = $scope.getDeviceLed(deviceId);
        ValidationUtilities.isNotNullOrUndefined(led, downloadContentMessages.LED_CAN_NOT_BE_NULL_OR_UNDEFINED);
        ValidationUtilities.isNotEmpty(led, downloadContentMessages.LED_CAN_NOT_BE_EMPTY);

        const parameters = {

            id: deviceId,
            type: "info"

        };

        const successHandler = function(deviceInfo) {

            const successHandlerMessages = downloadContentMessages.SuccessHandler;

            ValidationUtilities.isNotEmpty(deviceInfo, successHandlerMessages.DEVICE_INFO_CAN_NOT_BE_EMPTY);
            throbber.off();

            const serialCode = deviceInfo.serialCode;
            const deviceName = device.name;

            const hasDeviceName = !ValueUtilities.isNullOrUndefined(deviceName);

            if (hasDeviceName) {

                ValidationUtilities.isString(

                    deviceName, successHandlerMessages.DEVICE_NAME_HAS_TO_BE_A_STRING

                );

            }

            if (ValueUtilities.isNullOrUndefined(serialCode) || ValueUtilities.isEmpty(serialCode)) {

                const message = successHandlerMessages.getSerialCodeUnknownMessage(deviceId, deviceName);
                alert = AlertService.getDangerAlertWithAlertGlyphicon(message);

                ValidationUtilities.isNotNullOrUndefined(

                    alert, successHandlerMessages.ALERT_CAN_NOT_BE_NULL_OR_UNDEFINED

                );

                ValidationUtilities.isNotEmpty(alert, successHandlerMessages.ALERT_CAN_NOT_BE_EMPTY);

                return;

            }

            const contentTitle = deviceInfo.contentTitle;
            ValidationUtilities.isString(contentTitle, successHandlerMessages.CONTENT_TITLE_HAS_TO_BE_A_STRING);
            ValidationUtilities.isTrue(contentTitle.length > 0, successHandlerMessages.CONTENT_TITLE_CAN_NOT_BE_EMPTY);

            if (contentTitle === "None") {

                const message = successHandlerMessages.getNoContentAssignedMessage(deviceId, deviceName);
                alert = AlertService.getDangerAlertWithAlertGlyphicon(message);

                ValidationUtilities.isNotNullOrUndefined(

                    alert, successHandlerMessages.ALERT_CAN_NOT_BE_NULL_OR_UNDEFINED

                );

                ValidationUtilities.isNotEmpty(alert, successHandlerMessages.ALERT_CAN_NOT_BE_EMPTY);

                return;

            } else {

                $window.location.href = "/smartcontrol/api/devices/" + deviceId + "/content/download";
                $scope.hideModal("downloadContentModal");

            }

            SuccessService.handleLedSuccess(led);

        };

        const failHandler = function() {

            const failHandlerMessages = downloadContentMessages.FailHandler;

            throbber.off();

            const message = failHandlerMessages.FAILED_TO_DOWNLOAD_CONTENT;
            const alert = AlertService.getDangerAlertWithAlertGlyphicon(message);

            ValidationUtilities.isNotNullOrUndefined(

                alert, failHandlerMessages.ALERT_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            ValidationUtilities.isNotEmpty(alert, failHandlerMessages.ALERT_CAN_NOT_BE_EMPTY);

            ErrorService.handleLedError(led, alert);
            $scope.hideModal("downloadContentModal");

        };

        Devices.get(parameters, null, successHandler, failHandler);

    };

    const getAlertId = function() {

        const getAlertIdMessages = DownloadContentControllerMessages.GetAlertId;
        ValidationUtilities.isNotNullOrUndefined(alert, getAlertIdMessages.ALERT_CAN_NOT_BE_NULL_OR_UNDEFINED);

        return alert.id;

    };

    const getAlertType = function() {

        const getAlertTypeMessages = DownloadContentControllerMessages.GetAlertType;
        ValidationUtilities.isNotNullOrUndefined(alert, getAlertTypeMessages.ALERT_CAN_NOT_BE_NULL_OR_UNDEFINED);

        return alert.type;

    };

    const getAlertGlyphiconClass = function() {

        const getAlertGlyphiconClassMessages = DownloadContentControllerMessages.GetAlertGlyphiconClass;

        ValidationUtilities.isNotNullOrUndefined(

            alert, getAlertGlyphiconClassMessages.ALERT_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        return alert.glyphiconClass;

    };

    const getAlertMessage = function() {

        const getAlertMessage = DownloadContentControllerMessages.GetAlertMessage;
        ValidationUtilities.isNotNullOrUndefined(alert, getAlertMessage.ALERT_CAN_NOT_BE_NULL_OR_UNDEFINED);

        return alert.message;

    };

    angular.element("#downloadContentModal").on("show.bs.modal", downloadContent);

    angular.element("#downloadContentModal").on("hidden.bs.modal", function() {

        alert = {};
        $scope.resetCurrentDevice();

    });

    return {

        getAlertId: getAlertId,
        getAlertType: getAlertType,
        getAlertGlyphiconClass: getAlertGlyphiconClass,
        getAlertMessage: getAlertMessage

    };

};

export default DownloadContentController;
