import ValidationUtilities from "../../utilities/validationUtilities";
import CreateGroupControllerMessages from "../../messages/controllers/create_group/createGroupController";

const CreateGroupController = function(

    ErrorService, SuccessService, AlertService, LedService, PopoverService, Groups, $scope

) {

    // Popover

    const title = "Error";

    const popover = PopoverService.getAlertsPopoverWithPlacementBottom(title);

    ValidationUtilities.isNotNullOrUndefined(

        popover, CreateGroupControllerMessages.POPOVER_CAN_NOT_BE_NULL_OR_UNDEFINED

    );

    // Led

    const led = LedService.getGreenOnLed(popover);
    ValidationUtilities.isNotNullOrUndefined(led, CreateGroupControllerMessages.LED_CAN_NOT_BE_NULL_OR_UNDEFINED);

    const removeDevice = function(device) {

        const removeDeviceMessages = CreateGroupControllerMessages.RemoveDevice;

        ValidationUtilities.isNotEmpty(device, removeDeviceMessages.DEVICE_CAN_NOT_BE_EMPTY);

        const currentGroup = $scope.currentGroup;
        ValidationUtilities.isNotEmpty(currentGroup, removeDeviceMessages.CURRENT_GROUP_CAN_NOT_BE_EMPTY);

        const devices = currentGroup.devices;
        ValidationUtilities.isNotEmpty(devices, removeDeviceMessages.DEVICES_CAN_NOT_BE_EMPTY);

        const deviceIndex = devices.indexOf(device);

        ValidationUtilities.isPositiveNumber(

            deviceIndex, removeDeviceMessages.DEVICE_INDEX_HAS_TO_BE_A_POSITIVE_NUMBER

        );

        $scope.currentGroup.devices.splice(deviceIndex, 1);

        const checkedDevices = $scope.checkedDevices;

        ValidationUtilities.isNotNullOrUndefined(

            checkedDevices, removeDeviceMessages.CHECKED_DEVICES_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        checkedDevices[device.id] = false;

    };

    const isGroupValid = function() {

        const isGroupValidMessages = CreateGroupControllerMessages.IsGroupValid;

        const currentGroup = $scope.currentGroup;
        ValidationUtilities.isNotEmpty(currentGroup, isGroupValidMessages.CURRENT_GROUP_CAN_NOT_BE_EMPTY);

        const devices = currentGroup.devices;
        ValidationUtilities.isNotEmpty(devices, isGroupValidMessages.DEVICES_CAN_NOT_BE_EMPTY);

        const forms = $scope.forms;
        ValidationUtilities.isNotEmpty(forms, isGroupValidMessages.FORMS_CAN_NOT_BE_EMPTY);

        const createGroupForm = forms.createGroupForm;
        ValidationUtilities.isNotEmpty(createGroupForm, isGroupValidMessages.CREATE_GROUP_FORM_CAN_NOT_BE_EMPTY);

        return (devices.length >= 2) && $scope.forms.createGroupForm.$valid;

    };

    const createGroup = function() {

        const createGroupMessages = CreateGroupControllerMessages.CreateGroup;

        const currentGroup = $scope.currentGroup;
        ValidationUtilities.isNotEmpty(currentGroup, createGroupMessages.CURRENT_GROUP_CAN_NOT_BE_EMPTY);

        const successHandler = function() {

            const successHandlerMessages = createGroupMessages.SuccessHandler;

            $scope.resetCheckedDevices();

            const polling = $scope.polling;
            ValidationUtilities.isNotEmpty(polling, successHandlerMessages.POLLING_CAN_NOT_BE_EMPTY);

            polling.update();

            $scope.hideModal("createGroupModal");

        };

        const failHandler = function() {

            const failHandlerMessages = createGroupMessages.FailHandler;

            const message = failHandlerMessages.FAILED_TO_CREATE_GROUP;

            const alert = AlertService.getDangerAlertWithAlertGlyphicon(message);
            ValidationUtilities.isNotNullOrUndefined(alert, failHandlerMessages.ALERT_CAN_NOT_BE_NULL_OR_UNDEFINED);
            ValidationUtilities.isNotEmpty(alert, failHandlerMessages.ALERT_CAN_NOT_BE_EMPTY);

            ErrorService.handleLedError(led, alert);

        };

        Groups.save(null, currentGroup, successHandler, failHandler);

    };

    angular.element("#createGroupModal").on("hidden.bs.modal", function() {

        SuccessService.handleLedSuccess(led);

    });

    return {

        led: led,

        removeDevice: removeDevice,
        isGroupValid: isGroupValid,
        createGroup: createGroup

    };

};

export default CreateGroupController;
