import ValueUtilities from "../../utilities/valueUtilities";
import ValidationUtilities from "../../utilities/validationUtilities";

import DeviceInfoControllerMessages from "../../messages/controllers/device_info/deviceInfoController";

const DeviceInfoController = function(

    ErrorService, SuccessService, LedService, PopoverService, AlertService, Devices, $scope

) {

    // Popover

    const title = "Error";
    const popover = PopoverService.getAlertsPopoverWithPlacementBottom(title);

    ValidationUtilities.isNotNullOrUndefined(

        popover, DeviceInfoControllerMessages.POPOVER_CAN_NOT_BE_NULL_OR_UNDEFINED

    );

    // Led

    const led = LedService.getGreenOnLed(popover);
    ValidationUtilities.isNotNullOrUndefined(led, DeviceInfoControllerMessages.LED_CAN_NOT_BE_NULL_OR_UNDEFINED);

    // Other

    const loadDeviceInfo = function() {

        const loadDeviceInfoMessages = DeviceInfoControllerMessages.LoadDeviceInfo;

        const device = $scope.currentDevice;
        ValidationUtilities.isNotNullOrUndefined(device, loadDeviceInfoMessages.DEVICE_CAN_NOT_BE_NULL_OR_UNDEFINED);

        const deviceId = device.id;
        ValidationUtilities.isPositiveNumber(deviceId, loadDeviceInfoMessages.DEVICE_ID_HAS_TO_BE_A_POSITIVE_NUMBER);

        const throbber = $scope.setLoading("info-" + deviceId, true);

        const parameters = {

            id: deviceId,
            type: "info"

        };

        const successHandler = function(model) {

            const successHandlerMessages = loadDeviceInfoMessages.SuccessHandler;

            ValidationUtilities.isNotNullOrUndefined(

                model, successHandlerMessages.MODEL_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            ValidationUtilities.isNotEmpty(model, successHandlerMessages.MODEL_CAN_NOT_BE_EMPTY);

            model.id = deviceId;
            $scope.setCurrentDevice(model);
            SuccessService.handleLedSuccess(led);
            throbber.off();

        };

        const failHandler = function() {

            const failHandlerMessages = loadDeviceInfoMessages.FailHandler;
            throbber.off();

            const deviceName = device.name;
            const hasDeviceName = !ValueUtilities.isNullOrUndefined(deviceName);

            if (hasDeviceName) {

                ValidationUtilities.isString(

                    deviceName, failHandlerMessages.DEVICE_NAME_HAS_TO_BE_A_STRING

                );

            }

            const message = failHandlerMessages.getFailedToLoadDeviceMessage(deviceId, deviceName);
            const alert = AlertService.getDangerAlertWithAlertGlyphicon(message);

            ValidationUtilities.isNotNullOrUndefined(

                alert, failHandlerMessages.ALERT_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            ValidationUtilities.isNotEmpty(alert, failHandlerMessages.ALERT_CAN_NOT_BE_EMPTY);

            ErrorService.handleLedError(led, alert);

        };

        Devices.get(parameters, null, successHandler, failHandler);

    };

    const isSerialCodeKnown = function(device) {

        const isSerialCodeKnownMessages = DeviceInfoControllerMessages.IsSerialCodeKnown;

        ValidationUtilities.isNotNullOrUndefined(

            device, isSerialCodeKnownMessages.DEVICE_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        ValidationUtilities.isNotEmpty(device, isSerialCodeKnownMessages.DEVICE_CAN_NOT_BE_EMPTY);

        const serialCode = device.serialCode;

        return !ValueUtilities.isNullOrUndefined(serialCode);

    };

    const unassignContent = function(device) {

        const unassignContentMessages = DeviceInfoControllerMessages.UnassignContent;

        ValidationUtilities.isNotNullOrUndefined(

            device, unassignContentMessages.DEVICE_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        const deviceId = device.id;

        ValidationUtilities.isPositiveNumber(

            deviceId, unassignContentMessages.DEVICE_ID_HAS_TO_BE_A_POSITIVE_NUMBER

        );

        const parameters = {

            id: deviceId,
            type: "content",
            prefix: "unassign"

        };

        const successHandler = function() {

            SuccessService.handleLedSuccess(led);
            loadDeviceInfo();

        };

        const failHandler = function() {

            const failHandlerMessages = unassignContentMessages.FailHandler;

            const message = failHandlerMessages.FAILED_TO_UNASSIGN_CONTENT;
            const alert = AlertService.getDangerAlertWithAlertGlyphicon(message);

            ValidationUtilities.isNotNullOrUndefined(

                alert, failHandlerMessages.ALERT_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            ValidationUtilities.isNotEmpty(alert, failHandlerMessages.ALERT_CAN_NOT_BE_EMPTY);

            ErrorService.handleLedError(led, alert);

        };

        return Devices.put(parameters, null, successHandler, failHandler);

    };

    const isAnyContentAssigned = function(device) {

        const isAnyContentAssignedMessages = DeviceInfoControllerMessages.IsAnyContentAssigned;

        ValidationUtilities.isNotNullOrUndefined(

            device, isAnyContentAssignedMessages.DEVICE_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        const contentTitle = device.contentTitle;
        const hasContentTitle = !ValueUtilities.isNullOrUndefined(contentTitle);

        if (hasContentTitle) {

            ValidationUtilities.isString(

                contentTitle, isAnyContentAssignedMessages.CONTENT_TITLE_HAS_TO_BE_A_STRING

            );

        }

        return hasContentTitle && (contentTitle !== "None");

    };

    angular.element("#deviceInfoModal").on("show.bs.modal", loadDeviceInfo);
    angular.element("#deviceInfoModal").on("hidden.bs.modal", function() {

        $scope.resetCurrentDevice();
        SuccessService.handleLedSuccess(led);

    });

    return {

        led: led,

        isSerialCodeKnown: isSerialCodeKnown,
        unassignContent: unassignContent,
        isAnyContentAssigned: isAnyContentAssigned

    };

};

export default DeviceInfoController;
