import ValidationUtilities from "./../../../../../../utilities/validationUtilities";

import { getHasToBeStringMessage } from "./../../../../../messages";
import { getFailedToMessage } from "./../../../../../messages";

const getFailedToAssignContentMessage = function(contentId, contentTitle) {

    const contentIdHasToBeStringMessage = getHasToBeStringMessage("Content id");
    ValidationUtilities.isString(contentId, contentIdHasToBeStringMessage);

    const contentTitleHasToBeStringMessage = getHasToBeStringMessage("Content title");
    ValidationUtilities.isString(contentTitle, contentTitleHasToBeStringMessage);

    const assignContentMessage = "assign content " + contentId + " (" + contentTitle + ")";

    return getFailedToMessage(assignContentMessage);

};

Object.freeze(getFailedToAssignContentMessage);

export default getFailedToAssignContentMessage;
