const OnOffSwitchDirective = function() {

    const link = function(scope, element, attributes, ngModel) {

        if (ngModel) { // Don't do anything unless we have a model

            // Parser
            const parser = function(value) {

                if (value === true) {

                    return "ON";

                } else if (value === false) {

                    return "OFF";

                }

            };

            ngModel.$parsers.push(parser);

            // Formatter
            const formatter = function(value) {

                if (value === "ON") {

                    return true;

                } else if (value === "OFF") {

                    return false;

                }

            };

            ngModel.$formatters.push(formatter);

        }

    };

    return {

        restrict: "A",
        require: "ngModel",
        link: link

    };

};

export default OnOffSwitchDirective;
