import ValueUtilities from "../utilities/valueUtilities";
import ValidationUtilities from "../utilities/validationUtilities";

import LedServiceMessages from "../messages/services/led/ledService";

class LedService {

    constructor(LedColor, LedStatus) {

        this._LedColor = LedColor;
        this._LedStatus = LedStatus;

    }

    static get _ledServiceMessages() {

        return LedServiceMessages;

    }

    getLed(color, status, popover) {

        const getLedMessages = LedService._ledServiceMessages.GetLed;

        // Validation \\

        // Color

        ValidationUtilities.isString(color, getLedMessages.COLOR_HAS_TO_BE_A_STRING);
        ValidationUtilities.isTrue(color.length > 0, getLedMessages.COLOR_CAN_NOT_BE_EMPTY);

        // Status

        ValidationUtilities.isString(status, getLedMessages.STATUS_HAS_TO_BE_A_STRING);
        ValidationUtilities.isTrue(status.length > 0, getLedMessages.STATUS_CAN_NOT_BE_EMPTY);

        // Led \\

        const led = {

            color: color,
            status: status

        };

        const hasPopover = !ValueUtilities.isNullOrUndefined(popover);
        ValidationUtilities.isBoolean(hasPopover, getLedMessages.HAS_POPOVER_HAS_TO_BE_A_BOOLEAN);

        if (hasPopover) {

            led.popover = popover;

        }

        return led;

    }

    getGreenLed(status, popover) {

        const getGreenLedMessages = LedService._ledServiceMessages.GetGreenLed;

        // Validate status \\

        ValidationUtilities.isString(status, getGreenLedMessages.STATUS_HAS_TO_BE_A_STRING);
        ValidationUtilities.isTrue(status.length > 0, getGreenLedMessages.STATUS_CAN_NOT_BE_EMPTY);

        // Led \\

        const color = this._LedColor.GREEN;

        return this.getLed(color, status, popover);

    }

    getRedLed(status, popover) {

        const getRedLedMessages = LedService._ledServiceMessages.GetRedLed;

        // Validate status \\

        ValidationUtilities.isString(status, getRedLedMessages.STATUS_HAS_TO_BE_A_STRING);
        ValidationUtilities.isTrue(status.length > 0, getRedLedMessages.STATUS_CAN_NOT_BE_EMPTY);

        // Led \\

        const color = this._LedColor.RED;

        return this.getLed(color, status, popover);

    }

    getGreenOnLed(popover) {

        const status = this._LedStatus.ON;

        return this.getGreenLed(status, popover);

    }

}

export default LedService;
