import ValidationUtilities from "../../../../utilities/validationUtilities";
import ValueUtilities from "../../../../utilities/valueUtilities";

import { getHasToBePositiveNumberMessage } from "../../../messages";
import { getHasToBeStringMessage } from "../../../messages";

const getDeviceIsStillInGroupMessage = function(groupId, groupName) {

    const groupIdHasToBePositiveNumberMessage = getHasToBePositiveNumberMessage("Group id");
    ValidationUtilities.isPositiveNumber(groupId, groupIdHasToBePositiveNumberMessage);

    let deviceIsStillInGroupMessage = "Device is still in group " + groupId;

    const hasGroupName = !ValueUtilities.isNullOrUndefined(groupName);

    if (hasGroupName) {

        const groupNameHasToBeStringMessage = getHasToBeStringMessage("Group name");
        ValidationUtilities.isString(groupName, groupNameHasToBeStringMessage);

        deviceIsStillInGroupMessage += " (" + groupName + ")";

    }

    deviceIsStillInGroupMessage += ".";

    return deviceIsStillInGroupMessage;

};

Object.freeze(getDeviceIsStillInGroupMessage);

export default getDeviceIsStillInGroupMessage;
