import ValueUtilities from "../../utilities/valueUtilities";
import ValidationUtilities from "../../utilities/validationUtilities";
import StringUtilities from "../../utilities/stringUtilities";

import EditDeviceControllerMessages from "../../messages/controllers/edit_device/editDeviceController";

const EditDeviceController = function(

    ErrorService, SuccessService, AlertService, PopoverService, LedService, DevicePropertyService, $scope, $timeout

) {

    // Timeouts

    const timeouts = {};

    // Popover

    const title = "Error";

    const popover = PopoverService.getAlertsPopoverWithPlacementBottom(title);

    ValidationUtilities.isNotNullOrUndefined(

        popover, EditDeviceControllerMessages.POPOVER_CAN_NOT_BE_NULL_OR_UNDEFINED

    );

    // Led

    const led = LedService.getGreenOnLed(popover);
    ValidationUtilities.isNotNullOrUndefined(led, EditDeviceControllerMessages.LED_CAN_NOT_BE_NULL_OR_UNDEFINED);

    const saveSetting = function(propertyPath) {

        const saveSettingMessages = EditDeviceControllerMessages.SaveSetting;

        ValidationUtilities.isString(propertyPath, saveSettingMessages.PROPERTY_PATH_HAS_TO_BE_A_STRING);
        ValidationUtilities.isTrue(propertyPath.length > 0, saveSettingMessages.PROPERTY_PATH_CAN_NOT_BE_EMPTY);

        const splitPropertyPath = propertyPath.split(".");
        const propertyName = splitPropertyPath[0];
        const fieldName = propertyPath.slice(propertyName.length + 1);

        const existingTimeout = timeouts[propertyPath];

        if (existingTimeout) {

            $timeout.cancel(existingTimeout);
            delete timeouts[propertyPath];

        }

        let isEditDeviceFormValid = false;

        if (!ValueUtilities.isEmpty(fieldName)) {

            let parsedFieldName = fieldName;

            if (propertyName === "ftpSettings") {

                const capitalizedFieldName = StringUtilities.capitalize(fieldName);
                parsedFieldName = "ftpSettings" + capitalizedFieldName;

            }

            isEditDeviceFormValid = $scope.forms.editDeviceForm[parsedFieldName].$valid;

        } else {

            isEditDeviceFormValid = $scope.forms.editDeviceForm[propertyName].$valid;

        }

        if (isEditDeviceFormValid === true) {

            const saveProperty = function() {

                const savePropertyMessages = saveSettingMessages.SaveProperty;

                const failHandler = function() {

                    const failHandlerMessages = savePropertyMessages.FailHandler;

                    const message = failHandlerMessages.FAILED_TO_SAVE_SETTING;
                    const alert = AlertService.getDangerAlertWithAlertGlyphicon(message);

                    ValidationUtilities.isNotNullOrUndefined(

                        alert, failHandlerMessages.ALERT_CAN_NOT_BE_NULL_OR_UNDEFINED

                    );

                    ValidationUtilities.isNotEmpty(

                        alert, failHandlerMessages.ALERT_CAN_NOT_BE_EMPTY

                    );

                    ErrorService.handleLedError(led, alert);

                };

                const device = angular.copy($scope.currentDevice);

                DevicePropertyService.saveProperty(device, propertyPath, null, failHandler);
                delete timeouts[propertyPath];

            };

            timeouts[propertyPath] = $timeout(saveProperty, 1000);

        }

    };

    const refreshOverviewIfNeeded = function() {

        const refreshOverviewIfNeededMessages = EditDeviceControllerMessages.RefreshOverviewIfNeeded;

        const forms = $scope.forms;
        ValidationUtilities.isNotEmpty(forms, refreshOverviewIfNeededMessages.FORMS_CAN_NOT_BE_EMPTY);

        const editDeviceForm = forms.editDeviceForm;

        ValidationUtilities.isNotEmpty(

            editDeviceForm, refreshOverviewIfNeededMessages.EDIT_DEVICE_FORM_CAN_NOT_BE_EMPTY

        );

        const isDirty = function(fieldName) {

            const isDirtyMessages = refreshOverviewIfNeededMessages.IsDirty;

            ValidationUtilities.isString(

                fieldName, isDirtyMessages.FIELD_NAME_HAS_TO_BE_A_STRING

            );

            ValidationUtilities.isTrue(

                fieldName.length > 0, isDirtyMessages.FIELD_NAME_CAN_NOT_BE_EMPTY

            );

            const field = editDeviceForm[fieldName];

            ValidationUtilities.isNotNullOrUndefined(

                field, isDirtyMessages.FIELD_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            return field.$dirty === true;

        };

        const fields = ["ip", "port", "controlId", "name"];
        const isAnyFieldDirty = fields.some(isDirty);

        if (isAnyFieldDirty) {

            const polling = $scope.polling;
            ValidationUtilities.isNotEmpty(polling, refreshOverviewIfNeededMessages.POLLING_CAN_NOT_BE_EMPTY);

            polling.update();

        }

        editDeviceForm.$setPristine();

    };

    angular.element("#editDeviceModal").on("hide.bs.modal", refreshOverviewIfNeeded);

    angular.element("#editDeviceModal").on("hidden.bs.modal", function() {

        SuccessService.handleLedSuccess(led);

    });

    return {

        led: led,

        saveSetting: saveSetting

    };

};

export default EditDeviceController;
