import ValueUtilities from "../utilities/valueUtilities";
import ValidationUtilities from "../utilities/validationUtilities";
import ArrayUtilities from "../utilities/arrayUtilities";

import OverviewControllerMessages from "../messages/controllers/overview/overviewController";

const OverviewController = function(

    LedService, PopoverService, DeviceService, GroupService, PopoverPlacement, Groups,
    $scope, $cookies, $location, $interval, $timeout

) {

    // Other \\

    $scope.deviceList = [];
    $scope.importItems = [];
    $scope.forms = {};
    $scope.groups = [];
    $scope.currentGroup = {};
    $scope.checkedDevices = {};
    $scope.checkedGroups = {};
    $scope.currentDevice = {};
    $scope.currentGroupDevices = [];
    $scope.matrixDevices = [];
    $scope.deviceLeds = {};
    $scope.groupLeds = {};
    $scope.devicesInGroup = {};

    $scope.devicesSorting = {

        column: "id",
        direction: "asc"

    };

    $scope.groupDevicesSorting = [];

    $scope.setDeviceList = function(deviceList) {

        const setDeviceListMessages = OverviewControllerMessages.SetDeviceList;

        const isDeviceListArray = Array.isArray(deviceList);
        ValidationUtilities.isTrue(isDeviceListArray, setDeviceListMessages.DEVICE_LIST_HAS_TO_BE_AN_ARRAY);

        $scope.deviceList = deviceList;

    };

    $scope.setCurrentDevice = function(device) {

        const setCurrentDeviceMessages = OverviewControllerMessages.SetCurrentDevice;
        ValidationUtilities.isNotEmpty(device, setCurrentDeviceMessages.DEVICE_CAN_NOT_BE_EMPTY);

        $scope.currentDevice = device;

    };

    $scope.resetCurrentDevice = function() {

        $scope.currentDevice = {};

    };

    $scope.setCurrentGroup = function(group) {

        const setCurrentGroupMessages = OverviewControllerMessages.SetCurrentGroup;
        ValidationUtilities.isNotEmpty(group, setCurrentGroupMessages.GROUP_CAN_NOT_BE_EMPTY);

        $scope.currentGroup = group;

    };

    $scope.resetCurrentGroup = function() {

        $scope.currentGroup = {};

    };

    $scope.setCurrentGroupDevices = function(devices) {

        const setCurrentGroupDevicesMessages = OverviewControllerMessages.SetCurrentGroupDevices;
        ValidationUtilities.isNotEmpty(devices, setCurrentGroupDevicesMessages.DEVICES_CAN_NOT_BE_EMPTY);

        $scope.currentGroupDevices = devices;

    };

    $scope.resetCurrentGroupDevices = function() {

        $scope.currentGroupDevices = [];

    };

    $scope.setMatrixDevices = function(devices) {

        const setMatrixDevicesMessages = OverviewControllerMessages.SetMatrixDevices;
        ValidationUtilities.isNotEmpty(devices, setMatrixDevicesMessages.DEVICES_CAN_NOT_BE_EMPTY);

        $scope.matrixDevices = devices;

    };

    $scope.resetMatrixDevices = function() {

        $scope.matrixDevices = [];

    };

    $scope.setImportItems = function(importItems) {

        const setImportItemsMessages = OverviewControllerMessages.SetImportItems;

        ValidationUtilities.isNotNullOrUndefined(

            importItems, setImportItemsMessages.IMPORT_ITEMS_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        $scope.importItems = importItems;

    };

    $scope.resetImportItems = function() {

        $scope.importItems = [];

    };

    $scope.getCheckedDevices = function() {

        const getCheckedDevicesMessages = OverviewControllerMessages.GetCheckedDevices;

        const deviceList = $scope.deviceList;

        ValidationUtilities.isNotNullOrUndefined(

            deviceList, getCheckedDevicesMessages.DEVICE_LIST_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        const checkedDevices = $scope.checkedDevices;

        ValidationUtilities.isNotNullOrUndefined(

            checkedDevices, getCheckedDevicesMessages.CHECKED_DEVICES_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        const isDeviceChecked = function(device) {

            const isDeviceCheckedMessages = getCheckedDevicesMessages.IsDeviceChecked;
            ValidationUtilities.isNotEmpty(device, isDeviceCheckedMessages.DEVICE_CAN_NOT_BE_EMPTY);

            return checkedDevices[device.id] === true;

        };

        return deviceList.filter(isDeviceChecked);

    };

    $scope.resetCheckedDevices = function() {

        $scope.checkedDevices = {};

    };

    $scope.getCheckedGroups = function() {

        const getCheckedGroupsMessages = OverviewControllerMessages.GetCheckedGroups;
        const groups = $scope.groups;

        ValidationUtilities.isNotNullOrUndefined(

            groups, getCheckedGroupsMessages.GROUPS_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        const checkedGroups = $scope.checkedGroups;

        ValidationUtilities.isNotNullOrUndefined(

            checkedGroups, getCheckedGroupsMessages.CHECKED_GROUPS_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        const isGroupChecked = function(group) {

            const isGroupCheckedMessages = getCheckedGroupsMessages.IsGroupChecked;
            ValidationUtilities.isNotEmpty(group, isGroupCheckedMessages.GROUP_CAN_NOT_BE_EMPTY);

            return checkedGroups[group.id] === true;

        };

        return groups.filter(isGroupChecked);

    };

    $scope.isAnyDeviceOrGroupChecked = function() {

        const checkedDevices = $scope.getCheckedDevices();
        const checkedGroups = $scope.getCheckedGroups();

        const isAnyDeviceChecked = !ArrayUtilities.isEmpty(checkedDevices);
        const isAnyGroupChecked = !ArrayUtilities.isEmpty(checkedGroups);

        return isAnyDeviceChecked || isAnyGroupChecked;

    };

    $scope.setGroupDevicesSorting = function(groupId, groupDevicesSorting) {

        $scope.groupDevicesSorting[groupId] = groupDevicesSorting;

    };

    $scope.resetGroupDevicesSorting = function() {

        $scope.groupDevicesSorting = [];

    };

    $scope.getGroupDevicesSorting = function(groupId) {

        return $scope.groupDevicesSorting[groupId];

    };

    $scope.pollingStatus = false;

    $scope.polling = function() {

        const pollingMessages = OverviewControllerMessages.Polling;
        const time = 30000;
        let enabled = $cookies.get("polling-enabled") === "true";
        let override = false; // true -> block updates
        let interval = null;
        let active = false;

        // Ignore incoming value from toggleSwitch
        const willUpdate = function() {

            return enabled && !override;

        };

        // Manage interval
        const evaluate = function() {

            if (willUpdate()) {

                if (interval !== null) {

                    $interval.cancel(interval);

                }

                interval = $interval(update, time);

            } else {

                if (interval !== null) {

                    $interval.cancel(interval);
                    interval = null;

                }

            }

        };

        const isEnabled = function() {

            return enabled === true;

        };

        // User control
        const setEnabled = function(value) {

            const setEnabledMessages = pollingMessages.SetEnabled;
            ValidationUtilities.isBoolean(value, setEnabledMessages.VALUE_HAS_TO_BE_A_BOOLEAN);

            enabled = value;
            updateActive();
            evaluate();

        };

        const toggleEnabled = function() {

            setEnabled(!enabled);
            $cookies.put("polling-enabled", enabled);

            // User expects a refresh immediately when enabling polling
            if (enabled) {

                update();

            }

        };

        // Background code setting, visible to user but not modifiable

        const isOverride = function() {

            return override === true;

        };

        const setOverride = function(value) {

            const setOverrideMessages = pollingMessages.SetOverride;
            ValidationUtilities.isBoolean(value, setOverrideMessages.VALUE_HAS_TO_BE_A_BOOLEAN);

            override = value;
            updateActive();
            evaluate();

        };

        const updateActive = function() {

            active = willUpdate();

            let pollingStatus;

            switch (active) {

                case true:

                    pollingStatus = "ON";
                    break;

                case false:

                    pollingStatus = "OFF";
                    break;

                default:

                    pollingStatus = null;

            }

            $scope.pollingStatus = pollingStatus;

        };

        // 1 refresh
        const update = function() {

            $scope.loadDevices();

        };

        return {

            willUpdate: willUpdate,
            update: update,
            isEnabled: isEnabled,
            setEnabled: setEnabled,
            toggleEnabled: toggleEnabled,
            isOverride: isOverride,
            setOverride: setOverride

        };

    }();

    $scope.sortGroupDevices = function(group, column, direction) {

        const sortGroupDevicesMessages = OverviewControllerMessages.SortGroupDevices;
        ValidationUtilities.isNotNullOrUndefined(group, sortGroupDevicesMessages.GROUP_CAN_NOT_BE_NULL_OR_UNDEFINED);

        const groupId = group.id;
        ValidationUtilities.isPositiveNumber(groupId, sortGroupDevicesMessages.GROUP_ID_HAS_TO_BE_A_POSITIVE_NUMBER);

        ValidationUtilities.isString(

            column, sortGroupDevicesMessages.COLUMN_HAS_TO_BE_A_STRING

        );

        ValidationUtilities.isTrue(column.length > 0, sortGroupDevicesMessages.COLUMN_CAN_NOT_BE_EMPTY);

        const sorting = $scope.getGroupDevicesSorting(groupId);

        ValidationUtilities.isNotNullOrUndefined(

            sorting, sortGroupDevicesMessages.SORTING_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        const sortColumn = sorting.column;
        ValidationUtilities.isString(sortColumn, sortGroupDevicesMessages.SORT_COLUMN_HAS_TO_BE_A_STRING);
        ValidationUtilities.isTrue(sortColumn.length > 0, sortGroupDevicesMessages.SORT_COLUMN_CAN_NOT_BE_EMPTY);

        const hasDirection = !ValueUtilities.isNullOrUndefined(direction);

        if (sortColumn === column) {

            if (hasDirection) {

                sorting.direction = direction;

            } else {

                const sortDirection = sorting.direction;

                ValidationUtilities.isString(

                    sortDirection, sortGroupDevicesMessages.SORT_DIRECTION_HAS_TO_BE_A_STRING

                );

                ValidationUtilities.isTrue(

                    sortDirection.length > 0,
                    sortGroupDevicesMessages.SORT_DIRECTION_CAN_NOT_BE_EMPTY

                );

                if (sortDirection === "asc") {

                    sorting.direction = "desc";

                } else {

                    sorting.direction = "asc";

                }

            }

        } else {

            sorting.column = column;

            if (hasDirection) {

                sorting.direction = direction;

            } else {

                sorting.direction = "asc";

            }

        }

        const successHandler = function(devices) {

            const successHandlerMessages = sortGroupDevicesMessages.SuccessHandler;

            ValidationUtilities.isNotNullOrUndefined(

                devices, successHandlerMessages.DEVICES_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            group.devices = devices;

        };

        const promise = GroupService
            .getGroupDevices(groupId, sorting.column, sorting.direction)
            .$promise;

        promise
            .then(successHandler);

        return promise;

    };

    $scope.loadDevices = function() {

        const loadDevicesMessages = OverviewControllerMessages.LoadDevices;

        angular.element("#deviceLoadingSpinner").removeClass("invisible-fade");
        const throbber = $scope.setLoading("devices", true);

        const hideSpinner = function() {

            const hideSpinnerTimeout = function() {

                angular.element("#deviceLoadingSpinner").addClass("invisible-fade");
                throbber.off();

            };

            $timeout(hideSpinnerTimeout, 100);

        };

        const checkElementLed = function(oldElementLeds, newElementLeds, element, popoverPlacement) {

            const checkElementLed = loadDevicesMessages.CheckElementLed;

            ValidationUtilities.isNotNullOrUndefined(

                oldElementLeds, checkElementLed.OLD_ELEMENT_LEDS_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            ValidationUtilities.isNotNullOrUndefined(

                newElementLeds, checkElementLed.NEW_ELEMENT_LEDS_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            ValidationUtilities.isNotNullOrUndefined(

                element, checkElementLed.ELEMENT_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            ValidationUtilities.isString(

                popoverPlacement, checkElementLed.POPOVER_PLACEMENT_HAS_TO_BE_A_STRING

            );

            ValidationUtilities.isTrue(

                popoverPlacement.length > 0, checkElementLed.POPOVER_PLACEMENT_CAN_NOT_BE_EMPTY

            );

            const elementId = element.id;

            ValidationUtilities.isPositiveNumber(

                elementId, checkElementLed.ELEMENT_ID_HAS_TO_BE_A_POSITIVE_NUMBER

            );

            const oldElementLed = oldElementLeds[elementId];
            const elementHasOldLed = !ValueUtilities.isNullOrUndefined(oldElementLed);

            if (!elementHasOldLed) {

                // Popover

                const title = "Error";
                const popover = PopoverService.getAlertsPopover(popoverPlacement, title);

                ValidationUtilities.isNotNullOrUndefined(

                    popover, checkElementLed.POPOVER_CAN_NOT_BE_NULL_OR_UNDEFINED

                );

                const newElementLed = LedService.getGreenOnLed(popover);

                ValidationUtilities.isNotNullOrUndefined(

                    newElementLed, checkElementLed.NEW_ELEMENT_LED_CAN_NOT_BE_NULL_OR_UNDEFINED

                );

                newElementLeds[elementId] = newElementLed;

            } /*else {

                 newElementLeds[elementId] = oldElementLed;

                 }*/

        };

        const devicesSuccessHandler = function(devices) {

            const successHandlerMessages = loadDevicesMessages.DevicesSuccessHandler;

            ValidationUtilities.isNotNullOrUndefined(

                devices, successHandlerMessages.DEVICES_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            $scope.setDeviceList(devices);

            //const deviceLedsCopy = angular.copy($scope.deviceLeds);
            //$scope.deviceLeds = {};

            const checkLed = function(device) {

                const checkLedMessages = successHandlerMessages.CheckLed;

                ValidationUtilities.isNotNullOrUndefined(

                    device, checkLedMessages.DEVICE_CAN_NOT_BE_NULL_OR_UNDEFINED

                );

                const deviceLeds = $scope.deviceLeds;
                const placement = PopoverPlacement.LEFT;

                checkElementLed(deviceLeds, deviceLeds, device, placement);

            };

            devices.forEach(checkLed);

            const checkedDevices = $scope.checkedDevices;

            ValidationUtilities.isNotNullOrUndefined(

                checkedDevices, successHandlerMessages.CHECKED_DEVICES_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            const checkedDevicesCopy = angular.copy(checkedDevices);
            $scope.checkedDevices = {};

            const checkIfDeviceShouldBeChecked = function(device) {

                const checkIfDeviceShouldBeCheckedMessages = successHandlerMessages.CheckIfDeviceShouldBeChecked;

                ValidationUtilities.isNotNullOrUndefined(

                    device, checkIfDeviceShouldBeCheckedMessages.DEVICE_CAN_NOT_BE_NULL_OR_UNDEFINED

                );

                ValidationUtilities.isNotEmpty(

                    device, checkIfDeviceShouldBeCheckedMessages.DEVICE_CAN_NOT_BE_EMPTY

                );

                const deviceId = device.id;

                ValidationUtilities.isPositiveNumber(

                    deviceId, checkIfDeviceShouldBeCheckedMessages.DEVICE_ID_HAS_TO_BE_A_POSITIVE_NUMBER

                );

                const isDeviceChecked = checkedDevicesCopy[deviceId];

                if (isDeviceChecked === true) {

                    $scope.checkedDevices[deviceId] = true;

                }

            };

            devices.forEach(checkIfDeviceShouldBeChecked);

        };

        const failHandler = function() {

            hideSpinner();

        };

        const sorting = $scope.devicesSorting;

        DeviceService
            .getDevices(sorting.column, sorting.direction)
            .$promise
            .then(devicesSuccessHandler)
            .catch(failHandler);

        const groupsSuccessHandler = function(groups) {

            const groupsSuccessHandlerMessages = loadDevicesMessages.GroupsSuccessHandler;

            ValidationUtilities.isNotNullOrUndefined(

                groups, groupsSuccessHandlerMessages.GROUPS_CAN_NOT_BE_NULL_OR_UNDEFINED

            );

            const sortGroupDevicesPromises = [];

            const checkGroupDevicesSorting = function(group) {

                const checkGroupDevicesSortingMessages = groupsSuccessHandlerMessages.CheckGroupDevicesSorting;

                ValidationUtilities.isNotNullOrUndefined(

                    group, checkGroupDevicesSortingMessages.GROUP_CAN_NOT_BE_NULL_OR_UNDEFINED

                );

                const groupId = group.id;

                ValidationUtilities.isPositiveNumber(

                    groupId, checkGroupDevicesSortingMessages.GROUP_ID_HAS_TO_BE_A_POSITIVE_NUMBER

                );

                let sorting = $scope.getGroupDevicesSorting(groupId);
                const hasSorting = !ValueUtilities.isNullOrUndefined(sorting);

                if (!hasSorting) {

                    sorting = {

                        column: "id",
                        direction: "asc"

                    };

                    $scope.setGroupDevicesSorting(groupId, sorting);

                }

                const promise = $scope.sortGroupDevices(group, sorting.column, sorting.direction);
                sortGroupDevicesPromises.push(promise);

            };

            groups.forEach(checkGroupDevicesSorting);

            Promise
                .all(sortGroupDevicesPromises)
                .then(function() {

                    $scope.groups = groups;

                    const checkLed = function(group) {

                        const checkLedMessages = groupsSuccessHandlerMessages.CheckLed;

                        ValidationUtilities.isNotNullOrUndefined(

                            group, checkLedMessages.GROUP_CAN_NOT_BE_NULL_OR_UNDEFINED

                        );

                        const groupLeds = $scope.groupLeds;
                        const placement = PopoverPlacement.RIGHT;

                        checkElementLed(groupLeds, groupLeds, group, placement);

                    };

                    groups.forEach(checkLed);

                    const checkedGroups = $scope.checkedGroups;

                    ValidationUtilities.isNotNullOrUndefined(

                        checkedGroups, groupsSuccessHandlerMessages.CHECKED_GROUPS_CAN_NOT_BE_NULL_OR_UNDEFINED

                    );

                    const checkedGroupsCopy = angular.copy(checkedGroups);
                    $scope.checkedGroups = {};

                    const checkIfGroupShouldBeChecked = function(group) {

                        const checkIfGroupShouldBeCheckedMessages =
                            groupsSuccessHandlerMessages.CheckIfGroupShouldBeChecked;

                        ValidationUtilities.isNotNullOrUndefined(

                            group, checkIfGroupShouldBeCheckedMessages.GROUP_CAN_NOT_BE_NULL_OR_UNDEFINED

                        );

                        ValidationUtilities.isNotEmpty(

                            group, checkIfGroupShouldBeCheckedMessages.GROUP_CAN_NOT_BE_EMPTY

                        );

                        const groupId = group.id;

                        ValidationUtilities.isPositiveNumber(

                            groupId, checkIfGroupShouldBeCheckedMessages.GROUP_ID_HAS_TO_BE_A_POSITIVE_NUMBER

                        );

                        const isGroupChecked = checkedGroupsCopy[groupId];

                        if (isGroupChecked === true) {

                            $scope.checkedGroups[groupId] = true;

                        }

                    };

                    groups.forEach(checkIfGroupShouldBeChecked);

                    $scope.devicesInGroup = {};

                    const checkDevicesInGroup = function(group) {

                        const checkDevicesInGroupMessages = groupsSuccessHandlerMessages.CheckDevicesInGroup;

                        ValidationUtilities.isNotNullOrUndefined(

                            group, checkDevicesInGroupMessages.GROUP_CAN_NOT_BE_NULL_OR_UNDEFINED

                        );

                        const checkDevice = function(device) {

                            const checkDeviceMessages = checkDevicesInGroupMessages.CheckDevice;

                            ValidationUtilities.isNotNullOrUndefined(

                                device, checkDeviceMessages.DEVICE_CAN_NOT_BE_NULL_OR_UNDEFINED

                            );

                            const deviceId = device.id;

                            ValidationUtilities.isPositiveNumber(

                                deviceId, checkDeviceMessages.DEVICE_ID_HAS_TO_BE_A_POSITIVE_NUMBER

                            );

                            const devicesInGroup = $scope.devicesInGroup;

                            ValidationUtilities.isNotNullOrUndefined(

                                devicesInGroup, checkDeviceMessages.DEVICES_IN_GROUPS_CAN_NOT_BE_NULL_OR_UNDEFINED

                            );

                            $scope.devicesInGroup[deviceId] = true;

                        };

                        const devices = group.devices;

                        ValidationUtilities.isNotNullOrUndefined(

                            devices, checkDevicesInGroupMessages.DEVICES_CAN_NOT_BE_NULL_OR_UNDEFINED

                        );

                        devices.forEach(checkDevice);

                    };

                    groups.forEach(checkDevicesInGroup);

                    hideSpinner();

                });

        };

        GroupService
            .getGroupsWithoutDevices()
            .$promise
            .then(groupsSuccessHandler)
            .catch(failHandler);

    };

    // Misc

    const showOrHideModal = function(id, action) {

        const showOrHideModalMessages = OverviewControllerMessages.ShowOrHideModal;

        ValidationUtilities.isString(id, showOrHideModalMessages.ID_HAS_TO_BE_A_STRING);
        ValidationUtilities.isTrue(id.length > 0, showOrHideModalMessages.ID_CAN_NOT_BE_EMPTY);

        ValidationUtilities.isString(action, showOrHideModalMessages.ACTION_HAS_TO_BE_A_STRING);
        ValidationUtilities.isTrue(action.length > 0, showOrHideModalMessages.ACTION_CAN_NOT_BE_EMPTY);

        const modalSelector = "#" + id;

        const modalElement = angular.element(modalSelector);
        ValidationUtilities.isNotNullOrUndefined(modalElement, showOrHideModalMessages.getNoModalFoundWithIdMessage(id));

        modalElement.modal(action);

    };

    $scope.showModal = function(id) {

        const showModalMessages = OverviewControllerMessages.ShowModal;

        ValidationUtilities.isString(id, showModalMessages.ID_HAS_TO_BE_A_STRING);
        ValidationUtilities.isTrue(id.length > 0, showModalMessages.ID_CAN_NOT_BE_EMPTY);

        showOrHideModal(id, "show");

    };

    $scope.hideModal = function(id) {

        const hideModalMessages = OverviewControllerMessages.HideModal;

        ValidationUtilities.isString(id, hideModalMessages.ID_HAS_TO_BE_A_STRING);
        ValidationUtilities.isTrue(id.length > 0, hideModalMessages.ID_CAN_NOT_BE_EMPTY);

        showOrHideModal(id, "hide");

    };

    const resetCurrentDevice = function() {

        $scope.resetCurrentDevice();
        $scope.$apply();

    };

    // Modal hiding
    angular.element("#addDeviceModal").on("hidden.bs.modal", function() {

        resetCurrentDevice();

    });

    angular.element("#editDeviceModal").on("hidden.bs.modal", function() {

        resetCurrentDevice();

    });

    angular.element("#deviceInfoModal").on("hidden.bs.modal", resetCurrentDevice);

    angular.element("#createGroupModal").on("hidden.bs.modal", function() {

        resetCurrentDevice();

    });

    $scope.isModalOpen = function(id) {

        const isModalOpenMessages = OverviewControllerMessages.IsModalOpen;

        ValidationUtilities.isString(id, isModalOpenMessages.ID_HAS_TO_BE_A_STRING);
        ValidationUtilities.isTrue(id.length > 0, isModalOpenMessages.ID_CAN_NOT_BE_EMPTY);

        const selector = "#" + id;
        const modal = angular.element(selector);

        ValidationUtilities.isNotNullOrUndefined(modal, isModalOpenMessages.getNoModalFoundWithIdMessage(id));

        const modalData = modal.data("bs.modal");

        if (!ValueUtilities.isEmpty(modalData)) {

            return modalData.isShown;

        }

        return false;

    };

    $scope.getDeviceLed = function(deviceId) {

        const getDeviceLedMessages = OverviewControllerMessages.GetDeviceLed;
        ValidationUtilities.isPositiveNumber(deviceId, getDeviceLedMessages.DEVICE_ID_HAS_TO_BE_A_POSITIVE_NUMBER);

        const deviceLeds = $scope.deviceLeds;

        ValidationUtilities.isNotNullOrUndefined(

            deviceLeds, getDeviceLedMessages.DEVICE_LEDS_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        return deviceLeds[deviceId];

    };

    $scope.getGroupLed = function(groupId) {

        const getGroupLedMessages = OverviewControllerMessages.GetGroupLed;
        ValidationUtilities.isPositiveNumber(groupId, getGroupLedMessages.GROUP_ID_HAS_TO_BE_A_POSITIVE_NUMBER);

        const groupLeds = $scope.groupLeds;

        ValidationUtilities.isNotNullOrUndefined(

            groupLeds, getGroupLedMessages.GROUP_LEDS_CAN_NOT_BE_NULL_OR_UNDEFINED

        );

        return groupLeds[groupId];

    };

    $scope.getModalTitle = function() {

        const getModalTitleMessages = OverviewControllerMessages.GetModalTitle;

        let model = $scope.currentDevice;
        ValidationUtilities.isNotNullOrUndefined(model, getModalTitleMessages.MODEL_CAN_NOT_BE_NULL_OR_UNDEFINED);

        let id = model.id;
        const hasId = !ValueUtilities.isNullOrUndefined(id);

        if (!hasId) {

            model = $scope.currentGroup;
            id = model.id;

        }

        let title = "(" + id;

        const name = model.name;
        const hasName = !ValueUtilities.isNullOrUndefined(name);

        if (hasName) {

            ValidationUtilities.isString(name, getModalTitleMessages.NAME_HAS_TO_BE_A_STRING);
            const isEmpty = ValueUtilities.isEmpty(name);

            if (!isEmpty) {

                title += " - " + name;

            }

        }

        const modelNumber = model.modelNumber;
        const hasModelNumber = !ValueUtilities.isNullOrUndefined(modelNumber);

        if (hasModelNumber) {

            ValidationUtilities.isString(modelNumber, getModalTitleMessages.MODEL_NUMBER_HAS_TO_BE_A_STRING);
            ValidationUtilities.isTrue(modelNumber.length > 0, getModalTitleMessages.MODEL_CAN_NOT_BE_EMPTY);

            title += " - " + modelNumber;

        }

        title += ")";

        return title;

    };

    const polling = $scope.polling;
    ValidationUtilities.isNotEmpty(polling, OverviewControllerMessages.POLLING_CAN_NOT_BE_EMPTY);

    polling.update();

    //const enabled = $cookies.get("polling-enabled") === "true";
    //polling.setEnabled(enabled);

    polling.setEnabled(true);

};

export default OverviewController;
