import StringUtilities from "../utilities/stringUtilities";

const EnumValueFilter = function() {

    const exclude = ["HDMI", "USB", "OPS", "CVI", "VGA", "PC", "IWB", "PDF", "POP", "PBP", "SICP"];

    const specialCases = [
        {
            value: "SRGB",
            display: "sRGB"
        },

        {

            value: "S_VIDEO",
            display: "S-Video"

        },

        {

            value: "CARD_DVI_D",
            display: "Card DVI-D"

        },

        {

            value: "DVI_D",
            display: "DVI-D"

        },

        {

            value: "_21_9",
            display: "21:9"

        },

        {

            value: "_16_9",
            display: "16:9"

        },

        {

            value: "TWO_DOT_TWO",
            display: "2.2"

        },

        {

            value: "TWO_DOT_FOUR",
            display: "2.4"

        },

        {

            value: "RGB_OFF_VIDEO_OFF",
            display: "RGB off, video off"

        },

        {

            value: "RGB_OFF_VIDEO_ON",
            display: "RGB off, video on"

        },

        {

            value: "RGB_ON_VIDEO_OFF",
            display: "RGB on, video off"

        },

        {

            value: "RGB_ON_VIDEO_ON",
            display: "RGB on, video on"

        },

        {

            value: "ON_CLOCKWISE",
            display: "Clockwise (OPS only)"

        },

        {

            value: "ON_COUNTERCLOCKWISE",
            display: "Counterclockwise (OPS only)"

        },

        {

            value: "SMART_CMS",
            display: "CMND & Play"

        },

        {

            value: "CMND_PLAY_WEB",
            display: "CMND&Play Web"

        },

        {

            value: "HOME_LAUNCHER",
            display: "Home/Launcher"

        },

        {

            value: "USB_TYPEC",
            display: "USB TypeC"

        },

        {

            value: "SMART_INFO",
            display: "Smart Info"

        },

        {

            value: "GOOGLE_CAST",
            display: "Google Cast"

        }

    ];

    return function(input, capitalizeEachWord) {

        // Special case \\

        const getSpecialCaseDisplay = function(value) {

            const getSpecialCase = function(specialCase) {

                return specialCase.value === value;

            };

            const specialCase = specialCases.find(getSpecialCase);

            if (specialCase !== undefined) {

                return specialCase.display;

            }

            return undefined;

        };

        const specialCaseDisplay = getSpecialCaseDisplay(input);

        if (specialCaseDisplay !== undefined) {

            return specialCaseDisplay;

        }

        // Remove leading underscore if present

        if (input.charAt(0) === "_") {

            input = input.slice(1);

        }

        // Color temperature

        const colorTemperatureRegex = new RegExp("^[0-9]+K$");
        const isInputColorTemperature = colorTemperatureRegex.test(input);

        if (isInputColorTemperature === true) {

            return input.replace("k", "K");

        }

        // Normal case \\

        const splitInput = input.split("_");

        for (var i = 0; i < splitInput.length; i++) {

            var value = splitInput[i];

            // If in list of excludes, skip
            if (exclude.indexOf(value) !== -1) {

                continue;

            }

            value = value.toLowerCase();

            if (capitalizeEachWord === true) {

                value = StringUtilities.capitalize(value);

            }

            splitInput[i] = value;

        }

        input = splitInput.join(" ");

        if (capitalizeEachWord !== true) {

            input = StringUtilities.capitalize(input);

        }

        return input;

    };

};

export default EnumValueFilter;
