import ValidationUtilities from "../utilities/validationUtilities";
import DeviceSettingsServiceMessages from "../messages/services/device_settings/deviceSettingsService";

class DeviceSettingsService {

    static get _deviceSettingsServiceMessages() {

        return DeviceSettingsServiceMessages;

    }

    getSettingName(propertyName) {

        const getSettingNameMessages = DeviceSettingsService._deviceSettingsServiceMessages.GetSettingName;

        ValidationUtilities.isString(

            propertyName, getSettingNameMessages.PROPERTY_NAME_HAS_TO_BE_A_STRING

        );

        ValidationUtilities.isTrue(

            propertyName.length > 0, getSettingNameMessages.PROPERTY_NAME_CAN_NOT_BE_EMPTY

        );

        switch (propertyName) {

            // Info \\

            case "serialCode":

                return "serial number";

            case "miscellaneous":

                return "run time";

            case "sicpVersion":

                return "SICP version";

            case "firmwareVersion":

                return "firmware version (scaler)";

            case "firmwareVersionAndroid":

                return "firmware version (Android)";

            case "temperatureSensor":

                return "temperature";

            // Settings \\

            case "touch":

                return "touch screen";

            case "lockUsb":
                return "lock USB";

            case "osdRotating":

                return "OSD rotating";

            case "osdInformation":

                return "OSD information";

            case "apm":

                return "APM";

            case "memcEffect":

                return "MEMC effect";

            case "vgaVideoParameters":

                return "VGA video parameters";

            case "colorTemperature100K":

                return "color temperature 100K";

            case "ecoMode":
                return "ECO mode";

            default:

                return propertyName
                    .replace(/([A-Z])/g, " $1")
                    .trim()
                    .toLowerCase();

        }

    }

}

export default DeviceSettingsService;
