import NavigationService from "../services/navigationService";
import VersionService from "../services/versionService";
import AlertService from "../services/alertService";
import SuccessService from "../services/successService";
import ErrorService from "../services/errorService";
import LedService from "../services/ledService";
import PopoverService from "../services/popoverService";
import LedDeviceSettingsService from "../services/ledDeviceSettingsService";
import DeviceSettingsService from "../services/deviceSettingsService";
import DevicePropertyService from "../services/devicePropertyService";
import DeviceService from "../services/deviceService";
import GroupService from "../services/groupService";

const app = angular.module("smartcontrol");

app.service(

    "NavigationService",

    [

        "$resource", NavigationService

    ]

);

app.service(

    "VersionService",

    [

        "$resource", VersionService

    ]

);

app.service("AlertService", AlertService);

app.service(

    "SuccessService",

    [

        "LedColor", "LedStatus",
        SuccessService

    ]

);

app.service(

    "ErrorService",

    [

        "LedColor", "LedStatus",
        ErrorService

    ]

);

app.service(

    "LedService",

    [

        "LedColor", "LedStatus",
        LedService

    ]

);

app.service(

    "PopoverService",

    [

        "PopoverPlacement", PopoverService

    ]

);

app.service(

    "LedDeviceSettingsService",

    [

        "$resource", LedDeviceSettingsService

    ]

);

app.service("DeviceSettingsService", DeviceSettingsService);

app.service(

    "DeviceService",

    [

        "$resource", DeviceService

    ]

);

app.service(

    "GroupService",

    [

        "$resource", GroupService

    ]

);

app.factory(

    "DevicePropertyService",

    [

        "Devices",
        "$parse",

        DevicePropertyService

    ]

);
