import ValueUtilities from "../utilities/valueUtilities";
import ValidationUtilities from "../utilities/validationUtilities";

import RefreshDirectiveMessages from "../messages/directives/refresh/refreshDirective";

/**
 * Clicking on an element attributed with 'refresh=property' HTTP GETs the given property for the device passed by the
 * 'refresh-parent=device' attribute and stores it in that device. The clicked element gets the class 'refreshing' while
 * the HTTP GET is running. Use to update form fields with current server values when clicking the field's label.
 */
const RefreshDirective = function(

    DevicePropertyService, ErrorService, SuccessService, AlertService, DeviceSettingsService, Devices

) {

    const scope = {

        refresh: "@",
        parent: "=refreshParent",
        led: "=refreshLed"

    };

    const link = function(scope, element) {

        const linkMessages = RefreshDirectiveMessages.Link;

        element.bind("click", function() {

            const parent = scope.parent;
            const parentId = parent.id;
            const hasParentId = !ValueUtilities.isNullOrUndefined(parentId);

            const refresh = scope.refresh;

            if (hasParentId) {

                const refreshingClass = "refreshing";
                element.addClass(refreshingClass);

                const led = scope.led;
                const hasLed = !ValueUtilities.isNullOrUndefined(led);

                const finish = function() {

                    element.removeClass(refreshingClass);

                };

                const successHandler = function() {

                    if (hasLed) {

                        SuccessService.handleLedSuccess(led);

                    }

                    finish();

                };

                const failHandler = function() {

                    const failHandlerMessages = linkMessages.FailHandler;

                    if (hasLed) {

                        const settingName = DeviceSettingsService.getSettingName(refresh);

                        ValidationUtilities.isString(

                            settingName, failHandlerMessages.SETTING_NAME_HAS_TO_BE_A_STRING

                        );

                        ValidationUtilities.isTrue(

                            settingName.length > 0, failHandlerMessages.SETTING_NAME_CAN_NOT_BE_EMPTY

                        );

                        const message = failHandlerMessages.getFailedToGetSettingMessage(settingName);
                        const alert = AlertService.getDangerAlertWithAlertGlyphicon(message);

                        ValidationUtilities.isNotNullOrUndefined(

                            alert, failHandlerMessages.ALERT_CAN_NOT_BE_NULL_OR_UNDEFINED

                        );

                        ValidationUtilities.isNotEmpty(

                            alert, failHandlerMessages.ALERT_CAN_NOT_BE_EMPTY

                        );

                        ErrorService.handleLedError(led, alert);

                    }

                    finish();

                };

                DevicePropertyService.updateProperty(scope.parent, scope.refresh, successHandler, failHandler);

            }

        });

    };

    return {

        restrict: "A",
        scope: scope,
        link: link

    };

};

export default RefreshDirective;
